KB.add({"board":"02","title":"佛教、道教与世界宗教","note":"交大考过：禅宗、玄奘、唐僧、西天、《大唐西域记》、大乘佛法、汉传佛教、达摩、慧能、顿悟、道教、上帝、犹太教、基督教、希伯来；选择题考过佛教时间单位、三藏、五戒、鸠摩罗什弟子、佛经四大翻译家、佛源词、印度教三大主神。这是交大与翻译专业直接相连的板块，译经史尤其重要。","clusters":[{"cid":"02a","name":"佛教起源与基本教义","line":"前6至前5世纪古印度释迦牟尼创立佛教：认识人生是苦（四谛），找出解脱的道路（八正道、戒定慧），用三法印检验是否佛法，众生依业在六道中轮回，最终目标是涅槃；皈依佛法僧三宝、守五戒是信徒的起点。"},{"cid":"02b","name":"佛教的分化与三大语系","line":"佛灭后经部派分裂，大乘自称普度众生、贬称早期派别为小乘；向南传入斯里兰卡和东南亚成为南传（巴利语系），向北经中亚传入中国成为汉传，7世纪后传入西藏形成藏传；全部经典称三藏，汇编成大藏经。"},{"cid":"02c","name":"佛教入华与西行求法","line":"两汉之际佛教沿丝绸之路传入，汉明帝永平求法、建白马寺是官方标志；为求真经，朱士行、法显、玄奘、义净先后西行，玄奘口述《大唐西域记》，“西天”指天竺印度；鉴真则反向东渡日本。"},{"cid":"02d","name":"佛经翻译：译家、译场与译论","line":"东汉安世高、支娄迦谶开译经之端，早期用“格义”借道家术语比附；道安总结五失本三不易，鸠摩罗什开“旧译”，玄奘以五种不翻开“新译”；四大译经家为鸠摩罗什、真谛、玄奘、不空，译场分工协作，大量佛源词进入汉语。"},{"cid":"02e","name":"汉传八宗与禅宗","line":"隋唐形成汉传八宗，天台宗最早本土化；禅宗以达摩为初祖，五祖弘忍传衣钵给慧能，南宗慧能主顿悟、北宗神秀主渐修，《六祖坛经》是唯一称“经”的中国僧人著作，后分五家七宗。"},{"cid":"02f","name":"佛教文化：名山、菩萨与节日","line":"大乘菩萨信仰在中国落地为四大菩萨与四大佛教名山；佛教还带来石窟艺术、变文俗讲和大量节日习俗。"},{"cid":"02g","name":"道教：本土宗教的形成与派别","line":"道教奉老子为太上老君，东汉张道陵创五斗米道、张角创太平道；魏晋葛洪发展神仙方术，北魏寇谦之、南朝陆修静和陶弘景加以改革；金元形成北方全真道与南方正一道两大派。"},{"cid":"02h","name":"亚伯拉罕诸教：犹太教、基督教、伊斯兰教","line":"犹太教是希伯来人的一神教，摩西律法与《希伯来圣经》是根基；1世纪从中产生基督教，1054年分裂为天主教与东正教，16世纪宗教改革产生新教；7世纪穆罕默德在阿拉伯半岛创立伊斯兰教，唐代传入中国。基督教入华分唐景教、元也里可温、明清天主教、近代新教四波。"},{"cid":"02i","name":"印度教及其他宗教","line":"婆罗门教演变为印度教，主神为梵天、毗湿奴、湿婆；同期还有耆那教，日本则有本土神道教；佛教、基督教、伊斯兰教合称世界三大宗教。"}],"entries":[{"id":"b02-001","t":"禅宗","cid":"02e","p":1,"kind":"流派","exam":["2013名解","2019名解"],"alias":["南宗禅","禅门"],"one":"汉传佛教最具中国特色的宗派，达摩初祖、慧能六祖，见性成佛。","ans":"禅宗是**汉传佛教最具中国特色的宗派**，主张**“不立文字，教外别传，直指人心，见性成佛”**。**传统尊南朝梁时来华的菩提达摩为初祖，经慧可、僧璨、道信、弘忍传至六祖慧能**。慧能主张**顿悟成佛**，形成南宗，神秀主渐修，形成北宗，史称“南顿北渐”；记录慧能言行的**《六祖坛经》**是禅宗根本典籍。禅宗是佛教中国化的代表，深刻影响宋明理学、文学艺术，并传入日本、朝鲜。","pts":["汉传佛教中国化宗派，见性成佛","达摩初祖，慧能六祖，南顿北渐","《六祖坛经》，影响理学与东亚"],"mem":"传承口诀“**达慧僧信忍能**”：达摩、慧可、僧璨、道信、弘忍、慧能。宗旨记两句：“直指人心，见性成佛”。","mix":"达摩是禅宗初祖，释迦牟尼是佛教创始人。慧能偈“菩提本无树，明镜亦非台”，神秀偈“身是菩提树，心如明镜台”。","mcq":[{"q":"禅宗尊奉的中国初祖是","o":["道信","慧能","弘忍","达摩"],"a":3,"w":"达摩为初祖，慧能为六祖。"},{"q":"主张渐修的禅宗北宗代表人物是","o":["神秀","弘忍","慧能","道生"],"a":0,"w":"神秀主渐修，慧能主顿悟，史称南顿北渐。"}],"rel":[{"t":"达摩","n":"初祖"},{"t":"慧能与《六祖坛经》","n":"六祖与经典"},{"t":"神秀与南顿北渐","n":"北宗渐修"},{"t":"禅宗五家七宗","n":"后世分支"},{"t":"宋明理学（道学）","n":"禅宗影响的思想"}]},{"id":"b02-002","t":"玄奘","cid":"02c","p":1,"kind":"人物","exam":["2014名解","2015名解","2018名解"],"alias":["唐僧","唐三藏","三藏法师","陈祎"],"one":"唐代高僧，西行天竺取经，开“新译”，创法相宗，口述《大唐西域记》。","ans":"玄奘（602–664），**唐代高僧、佛经翻译家，俗称“唐僧”“唐三藏”**。**贞观初年他从长安出发，经西域到天竺（印度）那烂陀寺求法，645年回到长安**，带回佛经六百余部。他**主持译场，译出佛经75部1335卷，提出“五种不翻”原则，开创“新译”**，与弟子窥基创立法相宗（唯识宗）。他口述、弟子辩机笔录的**《大唐西域记》**记载西域和印度一百多个国家与地区的情况，是研究中亚、南亚史地的重要文献。","pts":["唐代高僧，西行天竺求法","译经75部1335卷，五种不翻，新译","法相宗，《大唐西域记》"],"mem":"三个“西”：**西行**（求法）、**西域**（《大唐西域记》）、**西天**（目的地天竺）。年份挂钩：602生、645回长安、664卒。旧译新译口诀：“罗什旧，玄奘新”。","mix":"鉴真东渡日本，玄奘西行印度；法显陆去海回，义净海路往返，玄奘陆路往返。《西游记》以玄奘取经为原型，但情节多为虚构。","mcq":[{"q":"口述《大唐西域记》的高僧是","o":["法显","鉴真","义净","玄奘"],"a":3,"w":"《大唐西域记》由玄奘口述、辩机笔录。"},{"q":"玄奘与弟子窥基创立的宗派是","o":["法相宗（唯识宗）","天台宗","华严宗","净土宗"],"a":0,"w":"法相宗主“万法唯识”，以《成唯识论》为依据。"}],"rel":[{"t":"《大唐西域记》","n":"口述的游记"},{"t":"法相宗（唯识宗）","n":"创立的宗派"},{"t":"鸠摩罗什","n":"旧译对新译"},{"t":"中国翻译史四次高潮","n":"佛经翻译是第一次高潮"},{"t":"《西游记》","n":"取经故事的原型"}],"more":"贞观十九年（645）回长安，后在大慈恩寺等地译经。\n652年主持建大雁塔，存放经像。\n译有《心经》《成唯识论》等。"},{"id":"b02-003","t":"鸠摩罗什","cid":"02d","p":1,"kind":"人物","exam":["2022选择","2026选择"],"alias":["罗什","童寿"],"one":"龟兹高僧，后秦长安译场主持，旧译代表，四大翻译家之一。","ans":"鸠摩罗什（344–413），**西域龟兹人，东晋十六国时期高僧，佛经四大翻译家之一**。**401年后秦姚兴迎其至长安，主持国立译场**，译出《妙法莲华经》《金刚经》《维摩诘经》《阿弥陀经》及《中论》《百论》《十二门论》等。他的译文**注重意译、文辞流畅**，代表**“旧译”**的最高水平，《金刚经》《法华经》译本流传至今。弟子僧肇、道生、道融、僧叡称**“什门四圣”**，其所译三论成为三论宗的依据。","pts":["龟兹人，后秦长安译场","四大翻译家之一，旧译代表，意译流畅","什门四圣，三论宗依据"],"mem":"“**罗什旧译，玄奘新译**”。四部名经串成一句：妙法金刚维摩阿弥陀。弟子口诀“生肇融叡”（道生、僧肇、道融、僧叡）。","mix":"生卒年另有350–409说。罗什“旧译”重达意，玄奘“新译”重准确；三论指《中论》《百论》《十二门论》。","mcq":[{"q":"被视为佛经“旧译”代表的译经大师是","o":["鸠摩罗什","真谛","玄奘","不空"],"a":0,"w":"罗什译文流畅，代表旧译；玄奘开新译。"},{"q":"下列人物中，不属于“什门四圣”的是","o":["僧肇","慧远","僧叡","道生"],"a":1,"w":"什门四圣为道生、僧肇、道融、僧叡；慧远是庐山高僧，不是罗什弟子。"}],"rel":[{"t":"什门四圣","n":"弟子合称"},{"t":"佛经四大翻译家","n":"四人之一"},{"t":"玄奘","n":"旧译对新译"},{"t":"《金刚经》","n":"代表译作"},{"t":"三论宗","n":"所译三论为依据"}],"more":"代表译作：《妙法莲华经》《金刚经》《维摩诘经》《阿弥陀经》《中论》《百论》《十二门论》。"},{"id":"b02-004","t":"佛经四大翻译家","cid":"02d","p":1,"kind":"合称","exam":["2026选择"],"alias":["四大译经家","四大翻译家","四大佛经翻译家"],"one":"鸠摩罗什、真谛、玄奘、不空（一说以义净代不空）。","ans":"佛经四大翻译家是**中国佛经汉译史上最具代表性的四位译经大师的合称**，通行指**鸠摩罗什、真谛、玄奘、不空**（一说以义净代不空）。**鸠摩罗什为后秦译家，代表“旧译”；真谛为南朝梁陈时期来华的印度僧人，译《摄大乘论》；玄奘为唐代高僧，开创“新译”；不空为唐代密宗大师**。他们主持译场、确立译名与译经方法，推动了佛教在中国的传播和汉语词汇、文学的发展。","pts":["汉译佛经代表人物合称","鸠摩罗什、真谛、玄奘、不空","旧译与新译，推动中国化"],"members":[["鸠摩罗什","后秦，旧译代表，《金刚经》《法华经》"],["真谛","南朝梁陈，《摄大乘论》《俱舍论》"],["玄奘","唐，新译代表，法相宗"],["不空","唐，密宗，开元三大士之一"]],"mem":"口诀“**罗真玄空**”：鸠摩罗什、真谛、玄奘、不空。时代由早到晚：后秦、梁陈、唐、唐。联想：罗什译《金刚》，玄奘译《心经》，不空译密典。","mix":"2026年选择题答案是鉴真。道安（提出五失本三不易）、法显（著《佛国记》）、义净也不在通行四人内，只有义净是另一说的替补。","mcq":[{"q":"下列人物中，不属于佛经四大翻译家的是","o":["玄奘","真谛","不空","法显"],"a":3,"w":"法显是东晋求法僧，著《佛国记》，不在四大翻译家之内。"},{"q":"四大翻译家中，南朝梁陈时期来华的西天竺僧人是","o":["鸠摩罗什","真谛","玄奘","不空"],"a":1,"w":"真谛于546年来华，译《摄大乘论》《俱舍论》。"}],"rel":[{"t":"鸠摩罗什","n":"旧译代表"},{"t":"玄奘","n":"新译代表"},{"t":"真谛","n":"梁陈译家"},{"t":"不空","n":"密宗译家"},{"t":"译场","n":"集体译经的组织"}]},{"id":"b02-005","t":"大乘佛教","cid":"02b","p":1,"kind":"流派","exam":["2018名解"],"alias":["大乘","大乘佛法","菩萨乘"],"one":"1世纪前后兴起，主张普度众生、菩萨理想，汉传藏传都属大乘。","ans":"大乘佛教是**公元1世纪前后在印度兴起的佛教派别**，“乘”指运载，**自称能运载无量众生到达涅槃彼岸**。它**以菩萨为修行理想，主张自利利他、普度众生**，并把早期强调个人解脱的部派佛教贬称为“小乘”。大乘经典有《般若经》《法华经》《华严经》等。**汉传佛教和藏传佛教都属于大乘**，经中亚传入中国，再传到朝鲜、日本、越南。大乘思想推动了佛教在东亚的广泛传播。","pts":["1世纪前后兴起，普度众生","以菩萨为理想，自利利他","汉传、藏传属大乘"],"mem":"“乘”就是车。**大乘**是大车，载众生一起过河；**小乘**是小车，只载自己。汉传、藏传属大乘，南传佛教多属上座部。","mix":"南传佛教（斯里兰卡、东南亚、我国云南傣族地区）属上座部，修行目标是阿罗汉果；“小乘”是大乘文献对非大乘诸传统的称谓，南传上座部是具体传承。","mcq":[{"q":"下列佛教体系中，属于大乘佛教的是","o":["斯里兰卡佛教","泰国佛教","汉传佛教","缅甸佛教"],"a":2,"w":"汉传、藏传属大乘；斯里兰卡与东南亚属南传上座部。"},{"q":"大乘佛教的修行理想是","o":["阿罗汉","居士","辟支佛","菩萨"],"a":3,"w":"大乘以菩萨为理想，主张自利利他；阿罗汉是上座部的目标。"}],"rel":[{"t":"汉传佛教","n":"属大乘"},{"t":"藏传佛教","n":"也属大乘"},{"t":"南传佛教","n":"上座部，常被对举"},{"t":"佛教三大语系","n":"分布与经典语言"},{"t":"《法华经》","n":"大乘重要经典"}]},{"id":"b02-006","t":"汉传佛教","cid":"02b","p":1,"kind":"流派","exam":["2019名解"],"alias":["北传佛教","汉语系佛教","汉地佛教"],"one":"以汉文经典为依据的大乘佛教，两汉之际传入，隋唐宗派林立。","ans":"汉传佛教是**经西域传入中原、以汉文经典为依据的大乘佛教体系**，属于北传佛教。**相传两汉之际传入，东汉明帝时建洛阳白马寺**，魏晋南北朝通过译经和格义广泛传播，**隋唐形成天台、华严、法相、禅宗、净土等宗派**。汉传佛教与儒、道互动，实现中国化，并传入朝鲜半岛、日本、越南。它与藏传佛教、南传佛教并称中国佛教三大语系。","pts":["汉文经典，大乘，北传","两汉之际传入，白马寺","隋唐立宗，中国化，传东亚"],"mem":"三个坐标：**两汉传入**（白马驮经）、**魏晋译经**（格义）、**隋唐立宗**（八宗）。路线像一条线：印度→西域→长安、洛阳→朝鲜、日本、越南。","mix":"藏传佛教用藏文经典，俗称“喇嘛教”；南传佛教用巴利文经典，属上座部。","mcq":[{"q":"相传汉明帝时为安置来华僧人而在洛阳修建的寺院是","o":["那烂陀寺","白马寺","少林寺","东林寺"],"a":1,"w":"白马寺是汉传佛教官方传入的标志。"},{"q":"按传播体系分类，汉传佛教属于","o":["藏语系佛教","南传佛教","巴利语系佛教","北传佛教"],"a":3,"w":"汉传、藏传佛教都可归入北传佛教。"}],"rel":[{"t":"大乘佛教","n":"汉传属大乘"},{"t":"白马寺","n":"传入的官方标志"},{"t":"汉传佛教八宗","n":"隋唐形成的宗派"},{"t":"佛教三大语系","n":"与藏传、南传并称"},{"t":"永平求法与《四十二章经》","n":"传入的传说起点"}]},{"id":"b02-007","t":"道教","cid":"02g","p":1,"kind":"流派","exam":["2016名解"],"alias":["天师道"],"one":"东汉末形成的本土宗教，尊老子，张道陵创五斗米道，金元分全真、正一。","ans":"道教是**中国本土宗教，形成于东汉末年**。**张道陵创五斗米道（天师道），张角创太平道**，奉老子为教主“太上老君”，以《道德经》为主要经典，追求得道成仙、长生久视。**东晋葛洪著《抱朴子》**，北魏寇谦之、南朝陶弘景改革发展；**金元时期形成全真道（王重阳、丘处机）与正一道两大派**。道教影响中国医学、化学（炼丹术）、民俗和文学艺术，宫观是其活动场所。","pts":["东汉末形成的本土宗教","五斗米道、太平道，尊老子","全真、正一两派，影响医药民俗"],"mem":"时间线口诀：东汉“**陵角**”（张道陵、张角），魏晋“**葛洪**”，南北朝“**寇陆陶**”（寇谦之、陆修静、陶弘景），金元“**全真正一**”。","mix":"道教是宗教，道家是先秦思想学派；“道学”指宋明理学，不是道教。","mcq":[{"q":"创立五斗米道的是","o":["张道陵","张角","寇谦之","葛洪"],"a":0,"w":"张角创太平道，张道陵创五斗米道。"},{"q":"金元时期形成的道教两大派是","o":["南宗与北宗","全真道与正一道","上清派与灵宝派","天师道与太平道"],"a":1,"w":"全真道在北方，正一道在南方。"}],"rel":[{"t":"五斗米道（天师道）与太平道","n":"早期教派"},{"t":"全真道","n":"金元北方教派"},{"t":"正一道","n":"金元南方教派"},{"t":"太上老君与道教三清","n":"神仙体系"},{"t":"三教合一","n":"与儒释融合"}]},{"id":"b02-008","t":"三藏","cid":"02b","p":1,"kind":"合称","exam":["2024选择"],"alias":["佛教三藏","三藏经典"],"one":"佛教经典总称：经藏、律藏、论藏。","ans":"三藏是**佛教经典的总称**，包括**经藏、律藏、论藏**。**经藏**记载佛陀所说教法，**律藏**记载戒律和僧团规章，**论藏**是后世对教义的阐释论著。“藏”有容纳收藏之意。精通三藏的僧人尊称“三藏法师”，玄奘因此被称为**“唐三藏”**。汉文佛典后世汇编为**大藏经**，藏传佛教则有甘珠尔、丹珠尔两部藏经。","pts":["佛教经典总称","经、律、论三部分","三藏法师，玄奘称唐三藏"],"members":[["经藏","佛陀所说教法"],["律藏","戒律与僧团规章"],["论藏","对教义的阐释论著"]],"mem":"口诀“**经律论**”：佛说**经**，僧守**律**，后人写**论**。三藏装的都是“法”这一宝，所以三藏是三宝（佛法僧）里“法宝”的细分。","mix":"三宝是佛、法、僧，不是三藏；三法印、三学（戒定慧）也是别的“三”。","mcq":[{"q":"佛教“三藏”指","o":["贪、嗔、痴","戒、定、慧","经、律、论","佛、法、僧"],"a":2,"w":"佛法僧是三宝，戒定慧是三学，贪嗔痴是三毒。"},{"q":"《西游记》中唐僧又称“唐三藏”，“三藏”的含义是","o":["他取回的三部经书","他所在寺院的名字","精通经律论的法师","唐太宗赐的姓名"],"a":2,"w":"三藏法师是对精通经、律、论的僧人的尊称。"}],"rel":[{"t":"大藏经","n":"汉文佛典的汇编"},{"t":"三宝","n":"常被混淆的另一组三"},{"t":"玄奘","n":"唐三藏"},{"t":"《西游记》","n":"唐三藏的文学形象"}]},{"id":"b02-009","t":"佛教基本教义","cid":"02a","p":1,"kind":"概念","alias":["佛教教义","佛教基本思想"],"one":"四谛、八正道、缘起、业报轮回，最高目标是涅槃。","ans":"佛教由**古印度迦毗罗卫国王子乔达摩·悉达多（释迦牟尼）于公元前6至前5世纪创立**。基本教义以**四谛**为核心，即苦谛、集谛、灭谛、道谛，指人生皆苦、苦因在贪欲烦恼、烦恼可断、解脱之道是**八正道**。**缘起论**认为一切事物依条件而生灭，**业报轮回**说明善恶行为决定众生在六道中的去向。修行的最终目标是**涅槃**，即熄灭烦恼、超越生死的境界。三法印（诸行无常、诸法无我、涅槃寂静）是判别佛法的标准。","pts":["释迦牟尼创立，前6至前5世纪","四谛、八正道、缘起、业报轮回","最终目标涅槃，三法印为判准"],"mem":"四谛像看病：**苦**是病情，**集**是病因，**灭**是痊愈，**道**是药方（八正道）。再记三法印“无常、无我、寂静”，其中“寂静”对应涅槃，三句话就能串起整套教义。","mix":"涅槃不等于死亡，指烦恼熄灭的境界。三宝（佛、法、僧）、三藏（经、律、论）、三法印是三组不同的“三”，选择题常互换。","mcq":[{"q":"佛教“三法印”是判别是否佛法的标准，下列属于三法印的是","o":["佛法僧","不杀生","诸法无我","苦集灭道"],"a":2,"w":"三法印为诸行无常、诸法无我、涅槃寂静；苦集灭道是四谛，佛法僧是三宝。"},{"q":"佛教修行的最终目标是","o":["得道成仙","升入天堂","羽化登仙","涅槃"],"a":3,"w":"涅槃指熄灭烦恼、超越生死；得道成仙属道教，升入天堂属基督教。"}],"rel":[{"t":"释迦牟尼","n":"佛教创立者"},{"t":"四谛","n":"教义核心"},{"t":"三法印","n":"判别佛法的标准"},{"t":"涅槃","n":"最终目标"},{"t":"婆罗门教","n":"佛教兴起的印度背景"}],"more":"三宝：佛、法、僧。\n六道：天、人、阿修罗、畜生、饿鬼、地狱。","exam":[]},{"id":"b02-010","t":"达摩","cid":"02e","p":1,"kind":"人物","exam":["2019名解"],"alias":["菩提达摩","达磨","初祖达摩"],"one":"南朝梁时来华的印度僧人，禅宗初祖，传说面壁九年。","ans":"达摩（菩提达摩）是**南朝梁时来华的印度僧人，传统尊为中国禅宗初祖**。相传他由海路到广州，与梁武帝论法不契，遂**渡江入魏，在嵩山少林寺面壁九年**。他倡导“二入四行”，主张“壁观”禅修，并以《楞伽经》传给弟子慧可，慧可再传僧璨、道信、弘忍，至慧能而大成。达摩事迹多出传说，但他被奉为禅宗开山，**少林寺**因此成为禅宗祖庭，“一苇渡江”“面壁九年”成为著名典故。","pts":["南朝梁时来华的印度僧人","禅宗初祖，嵩山少林寺面壁九年","传慧可，少林为禅宗祖庭"],"mem":"画面记忆：一位胡僧在少林寺对着石壁坐了九年。传承“**达慧僧信忍能**”，达摩排第一。","mix":"达摩不是释迦牟尼；达摩创少林功夫属后世传说。","mcq":[{"q":"传统尊为中国禅宗初祖的是","o":["弘忍","释迦牟尼","达摩","慧能"],"a":2,"w":"达摩是禅宗初祖，释迦牟尼是佛教创始人。"},{"q":"相传达摩面壁九年的寺院是","o":["白马寺","南禅寺","少林寺","东林寺"],"a":2,"w":"达摩在嵩山少林寺面壁九年，少林寺为禅宗祖庭。"}],"rel":[{"t":"禅宗","n":"初祖"},{"t":"少林寺","n":"面壁九年处"},{"t":"禅宗六祖","n":"传承终点"},{"t":"慧能与《六祖坛经》","n":"六祖"}]},{"id":"b02-011","t":"慧能与《六祖坛经》","cid":"02e","p":1,"kind":"人物","exam":["2019名解"],"alias":["慧能","惠能","六祖","六祖慧能","坛经","《坛经》"],"one":"唐代禅宗六祖，南宗创始人，主顿悟；《六祖坛经》唯一称“经”的中国僧人著作。","ans":"慧能（638–713）是**唐代禅宗六祖，南宗创始人**，俗姓卢，新州（今广东新兴）人。他早年砍柴为生，闻《金刚经》而发心，到黄梅拜**五祖弘忍**，以“菩提本无树，明镜亦非台”一偈得传衣钵，后在岭南弘法。他主张**顿悟成佛、见性成佛**，与神秀的北宗渐修对立，形成“南顿北渐”。弟子法海等记录其说法而成的**《六祖坛经》，是唯一被尊称为“经”的中国僧人著作**。慧能一系成为禅宗主流，后世五家七宗都出自南宗。","pts":["唐代禅宗六祖，南宗创始人，主顿悟","得弘忍衣钵，南顿北渐","《六祖坛经》唯一称“经”的僧人著作"],"mem":"画面：砍柴少年听《金刚经》，在墙上和了一首偈，夺得衣钵。“**能顿秀渐**”：慧能顿，神秀渐。《坛经》记一个特例：其他僧人著作称论、传、记，只有它称“经”。","mix":"《坛经》是弟子记录，不是慧能亲笔；神秀偈与慧能偈别互换。神秀北宗主渐，慧能南宗主顿。","mcq":[{"q":"唯一被尊称为“经”的中国僧人著作是","o":["《肇论》","《佛国记》","《六祖坛经》","《大唐西域记》"],"a":2,"w":"其余三部是论著或游记，《坛经》记慧能说法，被尊为“经”。"},{"q":"禅宗五祖弘忍传衣钵给了","o":["神秀","慧可","慧能","道信"],"a":2,"w":"慧能以偈得衣钵，成为六祖。"}],"rel":[{"t":"禅宗六祖","n":"同一人物"},{"t":"神秀与南顿北渐","n":"北宗对手"},{"t":"顿悟","n":"核心主张"},{"t":"禅宗","n":"所属宗派"},{"t":"《金刚经》","n":"启发慧能的经典"}],"more":"慧能偈：菩提本无树，明镜亦非台。本来无一物，何处惹尘埃。"},{"id":"b02-012","t":"顿悟","cid":"02e","p":1,"kind":"概念","exam":["2019名解"],"alias":["顿悟成佛","见性成佛"],"one":"禅宗南宗主张：一念觉悟即可成佛，与渐修相对。","ans":"顿悟是**禅宗南宗的核心主张：众生本有佛性，一念觉悟即可成佛，无须长期渐进修行**。该说最早由**鸠摩罗什弟子道生**提出“顿悟成佛”，与印度佛教渐修成佛的传统相对。唐代**慧能**继承发展，主张**“见性成佛”**，认为自性本净，迷则为凡，悟则为佛，简化了修行仪轨。与之相对的是神秀北宗的**“渐修”**，形成“南顿北渐”。顿悟说降低了成佛门槛，影响宋明理学，南宋严羽也以禅喻诗，提出“妙悟”。","pts":["一念觉悟即可成佛，与渐修相对","道生首倡，慧能发展","南顿北渐，影响理学与诗论"],"mem":"顿是一步登顶，渐是一级级爬台阶。偈语对照：神秀“时时勤拂拭”是天天擦（渐），慧能“本来无一物”是根本无尘（顿）。","mix":"顿悟不等于不修行，它强调觉悟不分阶段；道生的顿悟早于慧能约两个世纪。","mcq":[{"q":"最早提出“顿悟成佛”说的是","o":["道生","神秀","慧能","僧肇"],"a":0,"w":"道生是罗什弟子，慧能后来继承发展。"},{"q":"禅宗北宗主张的修行方式是","o":["念佛往生","顿悟","持咒","渐修"],"a":3,"w":"神秀北宗主渐修，慧能南宗主顿悟。"}],"rel":[{"t":"慧能与《六祖坛经》","n":"南宗代表"},{"t":"神秀与南顿北渐","n":"渐修对立面"},{"t":"什门四圣","n":"道生出身"},{"t":"严羽","n":"以禅喻诗"},{"t":"禅宗","n":"所属宗派"}]},{"id":"b02-013","t":"五戒","cid":"02a","p":1,"kind":"合称","exam":["2025选择"],"alias":["佛教五戒","优婆塞戒"],"one":"不杀生、不偷盗、不邪淫、不妄语、不饮酒，在家信众的基本戒律。","ans":"五戒是**佛教在家信众的基本戒律**，也是全部佛教戒律的起点，内容为**不杀生、不偷盗、不邪淫、不妄语、不饮酒**。信徒皈依佛法僧**三宝**之后受持五戒，男居士称优婆塞，女居士称优婆夷。出家人另受沙弥十戒、比丘具足戒，条文更多。戒律属**三藏中的律藏**，守戒是“戒定慧”三学之首，作用是约束身口意、止恶行善。“不杀生”后来成为中国佛教素食、放生习俗的依据。","pts":["在家信众的基本戒律","杀、盗、淫、妄语、饮酒五条","三学之首，属律藏"],"members":[["不杀生","不伤害生命"],["不偷盗","不取不予之物"],["不邪淫","不行不正当的男女关系，2025选择考点"],["不妄语","不说谎话"],["不饮酒","不饮酒以免迷乱心智"]],"mem":"口诀“**杀盗淫妄酒**”，前四条管行为和言语，最后一条管心智。拿它和摩西十诫对比：十诫讲对神与对人，五戒只讲个人行为约束。","mix":"五戒是在家戒，沙弥十戒另有不非时食、不蓄金银等；别与儒家“五常”（仁义礼智信）、佛教“五蕴”混。","mcq":[{"q":"下列不属于佛教五戒的是","o":["不偷盗","不坐高广大床","不饮酒","不妄语"],"a":1,"w":"不坐高广大床属于沙弥十戒，不在在家五戒之内。"},{"q":"佛教五戒是下列哪类人的基本戒律","o":["沙弥尼","寺院住持","在家信众","出家比丘"],"a":2,"w":"五戒是在家信众的基本戒；出家人另受沙弥戒、具足戒。"}],"rel":[{"t":"三宝","n":"受戒以皈依三宝为前提"},{"t":"戒定慧三学","n":"戒是三学之首"},{"t":"三藏","n":"戒律属律藏"},{"t":"摩西与“十诫”","n":"东西方宗教戒条对照"}]},{"id":"b02-014","t":"佛教时间单位","cid":"02f","p":1,"kind":"常识","exam":["2020选择"],"alias":["刹那","须臾","弹指","罗预"],"one":"佛经时间量词，由短到长：刹那、瞬、弹指、罗预、须臾。","ans":"佛教时间单位是**佛经中由短到长的一组时间量词：刹那、瞬、弹指、罗预、须臾**。据《僧祇律》，**二十念为一瞬，二十瞬为一弹指，二十弹指为一罗预，二十罗预为一须臾**，每级相差二十倍。“刹那”是梵语音译，指极短的一瞬间，后进入日常汉语，“弹指”“须臾”也成为常用时间词。2020年选择题考“由大到小排序”，原题四项，次序为**须臾＞弹指＞瞬＞刹那**。","pts":["刹那、瞬、弹指、罗预、须臾","逐级乘二十","由大到小：须臾＞弹指＞瞬＞刹那"],"mem":"由短到长口诀“**刹瞬弹罗须，逐级乘二十**”。须臾排最后，是最大的一个，别因为日常说“须臾之间”就当成短的。","mix":"日常语里“须臾”“弹指”都形容时间短，但佛典中须臾远大于弹指（二十乘二十倍）。“劫”是佛教最长的时间单位，不在这组序列内。","mcq":[{"q":"按佛教时间单位，下列由大到小排序正确的是","o":["瞬＞须臾＞刹那＞弹指","刹那＞瞬＞弹指＞须臾","须臾＞弹指＞瞬＞刹那","弹指＞须臾＞瞬＞刹那"],"a":2,"w":"每级二十倍：刹那、瞬、弹指、罗预、须臾依次增大。"},{"q":"《僧祇律》说“二十念为一（　）”，空格应填","o":["罗预","须臾","瞬","弹指"],"a":2,"w":"二十念为一瞬，二十瞬为一弹指。"}],"rel":[{"t":"佛教汉译词","n":"刹那是音译词"},{"t":"十二时辰","n":"中国传统时间单位对照"},{"t":"佛教基本教义","n":"无常观念相关"}]},{"id":"b02-015","t":"佛教汉译词","cid":"02d","p":1,"kind":"常识","exam":["2023选择"],"alias":["佛源词","佛教借词"],"one":"源于佛经的汉语词：世界、刹那、烦恼、解脱等，“宇宙”不是。","ans":"佛教汉译词是**佛经汉译过程中产生、后来进入日常汉语的词语**。佛经翻译大量借用或创造新词，如**世界、刹那、觉悟、烦恼、方便、平等、因果、当下、解脱**，以及成语**一尘不染、五体投地、天花乱坠、不二法门**，都源于佛经。这些词多通过意译或音译（如“刹那”“涅槃”）进入汉语，丰富了汉语的哲学与抽象词汇。**“宇宙”出自先秦典籍，不是佛源词**，是常见的选择题干扰项。","pts":["佛经汉译产生并进入日常汉语","世界、刹那、烦恼、解脱等","宇宙出自先秦，不是佛源词"],"mem":"九个词首字串成一句：“**世刹觉烦方，平因当解脱**”（世界、刹那、觉悟、烦恼、方便、平等、因果、当下、解脱）。反例记“宇宙”：先秦就有，《尸子》“上下四方曰宇，往古来今曰宙”。","mix":"宇宙、天下、万物等是汉语固有词；“天花乱坠”原指佛说法时天降花雨，贬义是后来的用法。","mcq":[{"q":"下列词语中，不属于佛经汉译词的是","o":["烦恼","宇宙","刹那","解脱"],"a":1,"w":"宇宙出自先秦典籍，其余三个均源于佛经。"},{"q":"下列成语源于佛经的是","o":["刻舟求剑","守株待兔","亡羊补牢","五体投地"],"a":3,"w":"五体投地原为佛教最高礼拜；其余三个出自先秦寓言。"}],"rel":[{"t":"译场","n":"佛源词产生的场所"},{"t":"鸠摩罗什","n":"创译新词的译家"},{"t":"五种不翻","n":"音译词的原则"},{"t":"中国翻译史四次高潮","n":"佛经翻译是第一次"}],"more":"其他佛源词：苦海、因缘、境界、执着、现身说法、昙花一现、衣钵、心心相印。"},{"id":"b02-016","t":"西天","cid":"02c","p":2,"kind":"地理","exam":["2014名解"],"alias":["西天取经","天竺","五天竺"],"one":"古代对天竺（印度）的称呼，佛教发源地，取经目的地。","ans":"西天是中国古代对**天竺（今印度）**一带的称呼，因其位于中原以西而得名，是**佛教的发源地**。魏晋以后，朱士行、法显、玄奘、义净等僧人不远万里前往求取真经，称“**西天取经**”。唐玄奘西行十七年，著有《大唐西域记》，明代吴承恩据此演绎成长篇神魔小说《**西游记**》，“西天”遂成为取经目的地的代称，也成为中印文化交流的象征。","pts":["古代对天竺（印度）的称呼","佛教发源地，西行求法目的地","《西游记》取经终点"],"mem":"“西天”就是“西边的天竺”。记一条线：长安出发，过西域，到天竺，取回真经；小说里唐僧师徒走的就是这条线，终点雷音寺在西天。","mix":"“西天”指印度，“西域”指玉门关、阳关以西的新疆及中亚地区；“东土”指中国。西天取经的历史原型是玄奘，不要与法显、义净混淆。","mcq":[{"q":"我国古代所说的“西天”，通常指","o":["西域诸国","古代天竺（印度）","波斯","罗马帝国"],"a":1,"w":"西天指天竺，即今印度一带，佛教发源地。"}],"rel":[{"t":"玄奘","n":"西天取经的历史原型"},{"t":"《西游记》","n":"小说演绎取经"},{"t":"西域","n":"路途必经地区，易混"},{"t":"《大唐西域记》","n":"记述西天见闻"}]},{"id":"b02-017","t":"印度教三大主神","cid":"02i","p":1,"kind":"合称","exam":["2021选择"],"alias":["三相神","梵天毗湿奴湿婆"],"one":"梵天（创造）、毗湿奴（护持）、湿婆（毁灭）。","ans":"印度教三大主神指**梵天、毗湿奴、湿婆**，分别主管**创造、护持（保护）、毁灭**，又称三相神。印度教由**古代婆罗门教**演变而来，吸收佛教、耆那教和民间信仰，是**印度的主要宗教**。梵天是创造之神；毗湿奴维护宇宙秩序，常以化身下凡，罗摩、克里希那都是其化身；湿婆是毁灭与再生之神。三者共同构成宇宙循环。印度两大史诗《摩诃婆罗多》《罗摩衍那》与毗湿奴信仰关系密切。","pts":["梵天、毗湿奴、湿婆","创造、护持、毁灭","印度教由婆罗门教演变"],"members":[["梵天","创造之神"],["毗湿奴","护持之神，罗摩、克里希那是其化身"],["湿婆","毁灭与再生之神"]],"mem":"顺序口诀“**造、护、灭**”对“**梵、毗、湿**”。谐音帮忙：湿婆≈“失”去，管毁灭。","mix":"梵天（Brahma，创造神）、婆罗门（祭司种姓）、梵（Brahman，宇宙本体）三者不同；因陀罗是吠陀时代的雷神，不在三大主神内。“护持”“保护”是同一意思。","mcq":[{"q":"印度教三大主神中主管毁灭的是","o":["梵天","毗湿奴","罗摩","湿婆"],"a":3,"w":"罗摩是毗湿奴的化身，不是三大主神之一。"},{"q":"下列不属于印度教三大主神的是","o":["毗湿奴","湿婆","梵天","因陀罗"],"a":3,"w":"因陀罗是吠陀时代的雷雨神。"}],"rel":[{"t":"印度教","n":"所属宗教"},{"t":"婆罗门教","n":"前身"},{"t":"印度两大史诗","n":"毗湿奴化身故事所在"},{"t":"奥林匹斯十二主神","n":"神系对照"},{"t":"种姓制度","n":"婆罗门教的社会制度"}]},{"id":"b02-018","t":"五种不翻","cid":"02d","p":1,"kind":"概念","alias":["五不翻","玄奘五不翻"],"one":"玄奘提出的五种只音译不意译的情形。","ans":"五种不翻是**唐代玄奘提出的佛经翻译原则**，指在五种情况下只音译、不意译：**秘密故不翻、多含故不翻、此无故不翻、顺古故不翻、生善故不翻**。秘密故，如陀罗尼（咒语）；多含故，一词含多义，如“薄伽梵”；此无故，中土没有对应事物，如“阎浮树”；顺古故，沿用前人通行译法，如“阿耨多罗三藐三菩提”；生善故，译成汉语会减弱敬重感，如“般若”。它体现了玄奘“新译”忠实准确的主张，使“涅槃”“菩提”等音译词进入汉语。","pts":["玄奘提出的译经原则","五种情形只音译不意译","秘密、多含、此无、顺古、生善"],"members":[["秘密故不翻","如陀罗尼（咒语）"],["多含故不翻","一词多义，如薄伽梵"],["此无故不翻","中土无此物，如阎浮树"],["顺古故不翻","沿用旧译，如阿耨多罗三藐三菩提"],["生善故不翻","译后敬重感减弱，如般若"]],"mem":"口诀“**秘多此顺生**”（秘密、多含、此无、顺古、生善）。例子顺着背：咒语、多义、没有、老例、敬重。“般若”译成“智慧”会显得浅，所以保留音译。","mix":"别与道安“五失本三不易”混：道安讲译经的难处，玄奘讲哪些词不翻。此说载于宋代《翻译名义集》序，归在玄奘名下，通常视为后人对其译例的归纳。","mcq":[{"q":"提出“五种不翻”译经原则的是","o":["玄奘","道安","真谛","鸠摩罗什"],"a":0,"w":"五种不翻归在玄奘名下，是“新译”的特点。"},{"q":"“五种不翻”中“此无故不翻”指","o":["中土没有对应事物，如阎浮树","一词含多种意义","沿用前人已通行的音译","译成汉语会减弱尊敬感"],"a":0,"w":"一词多义是多含故，沿用旧译是顺古故，减弱敬重是生善故。"}],"rel":[{"t":"玄奘","n":"提出者"},{"t":"道安“五失本三不易”","n":"同样是“五”的译论"},{"t":"佛教汉译词","n":"音译词的结果"},{"t":"鸠摩罗什","n":"意译风格的对照"},{"t":"德莱顿翻译三分法","n":"中西译论对照"}],"exam":[]},{"id":"b02-019","t":"旧译与新译","cid":"02d","p":2,"kind":"概念","alias":["旧译","新译","古译"],"one":"以玄奘为界：之前（鸠摩罗什为代表）称旧译，之后称新译。","ans":"旧译与新译是**佛经汉译史上以玄奘为界的分期**。玄奘之前的译经称**旧译**，以**鸠摩罗什**为代表，译文流畅，偏重意译，如《金刚经》《法华经》；玄奘及其后的译经称**新译**，以**玄奘**为代表，译文严谨，忠实原文，提出“五种不翻”。新译在术语统一和梵文对照上更精确，两者分别代表了佛经翻译由意译为主到直译与意译结合的发展。","pts":["以玄奘为界分期","旧译：鸠摩罗什，重意译，文辞流畅","新译：玄奘，重忠实，术语严谨"],"mem":"“罗什旧，玄奘新”：罗什译得顺（旧），玄奘译得准（新）。可对比严复“信达雅”前后的翻译观，风格是“先顺后准”。","mix":"旧译不是“错误的翻译”，二者只是不同时期的风格，如《金刚经》罗什译本流传最广。玄奘提出的是“五种不翻”，道安提出的是“五失本、三不易”。","mcq":[{"q":"佛经翻译史上“旧译”的代表人物是","o":["玄奘","鸠摩罗什","义净","不空"],"a":1,"w":"旧译以鸠摩罗什为代表，新译以玄奘为代表。"}],"rel":[{"t":"鸠摩罗什","n":"旧译代表"},{"t":"玄奘","n":"新译代表"},{"t":"佛经四大翻译家","n":"译家全景"},{"t":"中国翻译史四次高潮","n":"第一次高潮的内容"}],"exam":[]},{"id":"b02-020","t":"希伯来","cid":"02h","p":2,"kind":"概念","exam":["2014名解"],"alias":["希伯来人","希伯来语","希伯来文化"],"one":"古代犹太民族的称呼，希伯来语是犹太教经典语言，今为以色列官方语言。","ans":"希伯来是**古代居住在巴勒斯坦一带的闪米特人的一支**，是犹太人的祖先，故“希伯来”也指古代犹太民族。希伯来人创造了**一神教信仰**，摩西带领他们出埃及，形成《旧约》（《希伯来圣经》）的核心叙事，**希伯来语**是犹太教经典所用语言，现代以色列将其作为官方语言。希伯来文明与古希腊文明被认为是西方文明的两大源头，即“**两希文明**”，对基督教和西方文化影响深远。","pts":["古代犹太民族的称呼，居巴勒斯坦","一神教起源，希伯来语为经典语言","与古希腊并称“两希文明”"],"mem":"一条线：希伯来人，摩西出埃及，《希伯来圣经》，希伯来语。“两希”的另一个“希”是希腊，一个管信仰，一个管理性。对应记：希腊是理性，希伯来是信仰。","mix":"“希伯来”指民族和语言文化，“犹太教”指宗教，“以色列”则是民族名和现代国家名。《希伯来圣经》就是基督教所称《旧约》，不要与《新约》（希腊文）混淆。","mcq":[{"q":"关于“希伯来”，下列说法正确的是","o":["希伯来语是《新约》使用的语言","是古代犹太民族的称呼","是古希腊人的另一称呼","是现代阿拉伯人的先祖"],"a":1,"w":"希伯来是古代犹太民族的称呼；《新约》用希腊文。"}],"rel":[{"t":"犹太教","n":"希伯来人的宗教"},{"t":"摩西与“十诫”","n":"希伯来人的领袖"},{"t":"《圣经》","n":"《旧约》即《希伯来圣经》"},{"t":"《七十子希腊文本》","n":"《旧约》的希腊文译本"}]},{"id":"b02-021","t":"上帝","cid":"02h","p":2,"kind":"概念","exam":["2014名解"],"alias":["天主","天帝","神"],"one":"先秦古籍中指天帝，明末传教士借此词译基督教的God。","ans":"“上帝”**本是中国先秦古籍中对天帝的称呼**，如《诗经》《尚书》中的“上帝”，是至上的天神。**明末来华的传教士**为了向中国人传播基督教，借用“上帝”“天主”来翻译基督教的唯一神 God，**利玛窦**等耶稣会士多用“天主”，也用“上帝”。后来在**译名之争**中，天主教多用“天主”，新教则多用“上帝”或“神”，“上帝”由此成为基督教神名的通行译法。","pts":["先秦古籍中指天帝","明末传教士借用来译God","天主教多称天主，新教多称上帝"],"mem":"一词两用：先秦的“上帝”是中国的天帝，明末的“上帝”是借来译 God 的词。两套译名记成“天主教叫天主，新教叫上帝”。","mix":"“上帝”借自中国古词，是翻译史上“借用本土词汇译外来概念”的典型。与佛经翻译用“格义”借道家词语相似，可以对比。","mcq":[{"q":"明末传教士借用中国古代词语翻译基督教的 God，被借用的词是","o":["上帝","玉皇","天尊","圣人"],"a":0,"w":"“上帝”本指先秦古籍中的天帝，传教士借来译 God。"}],"rel":[{"t":"利玛窦","n":"借用“天主”“上帝”译神名"},{"t":"明清来华耶稣会士","n":"传教士群体"},{"t":"基督教","n":"所信神的名称"},{"t":"佛教汉译词","n":"借词翻译的另一案例"}]},{"id":"b02-022","t":"景教","cid":"02h","p":2,"kind":"流派","alias":["聂斯托利派","聂斯脱利派","大秦景教","《大秦景教流行中国碑》"],"one":"唐代传入中国的基督教聂斯托利派，西安有《大秦景教流行中国碑》（781年）。","ans":"景教是**唐代传入中国的基督教聂斯托利派**，唐太宗贞观九年（635年）由波斯人**阿罗本**带到长安，朝廷准许传教，称“大秦景教”，并建寺院。**781年**，景教徒在长安立《**大秦景教流行中国碑**》，碑文用汉文和叙利亚文刻成，记述景教入华经过，**明末在西安出土，现藏西安碑林**。会昌五年（845年）唐武宗灭佛时，景教受到牵连而衰落，元代以“也里可温”之名再次兴起。","pts":["唐代传入的基督教聂斯托利派","635年阿罗本到长安，781年立碑","碑在西安，元代称也里可温"],"mem":"年份口诀：635 入，781 碑，845 灭。碑名里有“大秦”，大秦是中国古称罗马帝国一带的词；碑文既有汉字又有叙利亚文，是“中西合璧”。","mix":"景教是基督教的一支（聂斯托利派），不等于天主教。元代的“也里可温”则指蒙元时期的基督徒（含景教徒）。景教与祆教、摩尼教合称“唐代三夷教”。","mcq":[{"q":"唐代传入中国、在西安留有《大秦景教流行中国碑》的宗教是","o":["伊斯兰教","祆教","摩尼教","景教"],"a":3,"w":"景教即基督教聂斯托利派，碑立于781年。"}],"rel":[{"t":"唐代三夷教","n":"同期三种外来宗教"},{"t":"基督教","n":"景教所属宗教"},{"t":"大秦与甘英","n":"“大秦”指罗马一带"},{"t":"明清来华耶稣会士","n":"基督教入华后续一波"}],"exam":[]},{"id":"b02-023","t":"白马寺","cid":"02c","p":2,"kind":"地理","alias":["释源","祖庭","洛阳白马寺"],"one":"东汉明帝时洛阳所建，中国第一座官办佛寺，称“释源”。","ans":"白马寺位于**河南洛阳**，始建于**东汉明帝永平十一年（68年）**，被视为**中国第一座官办佛寺**，有“释源”“祖庭”之称。相传汉明帝夜梦金人，遣使西行求法，迎来印度僧人迦叶摩腾、竺法兰，两人以**白马驮经**到洛阳，皇帝便在此建寺，并以白马命名。寺内曾译出《四十二章经》。白马寺是佛教正式传入中国的象征，对佛教在中国的传播有开端意义。","pts":["东汉洛阳，永平十一年建","中国第一座官办佛寺，释源、祖庭","因白马驮经而得名"],"mem":"“白马驮经”四字就是全部由来：白马驮着佛经到了洛阳，皇帝建寺纪念，所以叫白马寺。记成“洛阳白马，东汉明帝，第一官寺”。","mix":"白马寺是第一座官办佛寺，不等于第一座佛寺；“寺”原是官署名，后来才指佛寺。少林寺在登封，与白马寺不同。","mcq":[{"q":"被视为中国第一座官办佛寺的是","o":["少林寺","东林寺","灵隐寺","白马寺"],"a":3,"w":"白马寺建于东汉明帝时的洛阳，称“释源”。"}],"rel":[{"t":"永平求法与《四十二章经》","n":"建寺的由来"},{"t":"少林寺","n":"同为著名古刹"},{"t":"慧远与东林寺","n":"另一著名佛寺"}],"exam":[]},{"id":"b02-024","t":"释迦牟尼","cid":"02a","p":2,"kind":"人物","alias":["乔达摩·悉达多","悉达多","佛陀","释迦","如来佛","佛祖"],"one":"佛教创始人，释迦族圣人，俗名乔达摩·悉达多，尊称佛陀。","ans":"释迦牟尼意为“**释迦族的圣人**”，俗名**乔达摩·悉达多**，生活在公元前6至前5世纪的古印度，原为迦毗罗卫国太子。他29岁出家，在菩提树下成道，被尊称为**佛陀**（觉悟者），随后在鹿野苑初转法轮，讲说**四谛**与八正道，建立僧团，传教四十余年，80岁左右在拘尸那迦涅槃。他创立了**佛教**，与基督教、伊斯兰教并称世界三大宗教。","pts":["释迦族圣人，俗名乔达摩·悉达多","菩提树下成道，鹿野苑初转法轮","佛教创始人，尊称佛陀（觉悟者）"],"mem":"一生四站对应四大圣地：蓝毗尼出生，菩提伽耶成道，鹿野苑说法，拘尸那迦涅槃。“释迦”是族名，“牟尼”是圣人，合起来就是“释迦族的圣人”，“佛陀”才是觉悟者的尊号。","mix":"“释迦牟尼”是尊称，俗名是乔达摩·悉达多；生卒年有前565至前485、前563至前483等说法，选择题多不考具体年份。他是佛教创始人，与孔子大体同时代。","mcq":[{"q":"佛教创始人释迦牟尼的俗名是","o":["乔达摩·悉达多","摩诃毗罗","阿难陀","舍利弗"],"a":0,"w":"释迦牟尼俗名乔达摩·悉达多，阿难、舍利弗是其弟子。"}],"rel":[{"t":"佛教四大圣地","n":"对应其生平四节点"},{"t":"佛教基本教义","n":"其教说的核心"},{"t":"佛陀十大弟子","n":"追随他的弟子"},{"t":"孔子","n":"大体同时代的东方圣哲"}],"more":"佛陀别称：如来、世尊、应供、正遍知等“十号”。\n成道后初转法轮处为鹿野苑，所说为四谛、八正道。","exam":[]},{"id":"b02-025","t":"三宝","cid":"02a","p":2,"kind":"合称","alias":["佛法僧","皈依三宝"],"one":"佛、法、僧三者，佛教徒皈依的对象。","ans":"三宝指**佛、法、僧**，是佛教徒信仰和皈依的三个对象。“佛”指觉悟者，即释迦牟尼等佛陀；“法”指佛所说的**教义经典**；“僧”指**出家修行的僧团**。成为佛教徒的起点是“皈依三宝”，并受持五戒。三宝是佛教信仰体系的基础，佛教徒自称“三宝弟子”即由此而来。","pts":["佛、法、僧","佛是觉者，法是教义，僧是僧团","皈依三宝是入教起点"],"members":[["佛","觉悟者，指释迦牟尼等佛陀"],["法","佛所说的教义"],["僧","奉行佛法的僧团"]],"mem":"顺序按“人、话、团队”记：佛是说话的人，法是说的话，僧是听话并照做的团队。三个字连起来就是“佛法僧”，与“三藏”（经律论）不要混用。","mix":"三宝（佛法僧）与三藏（经、律、论）、三学（戒定慧）都是“三”开头的佛教合称，成员完全不同。基督教的“三位一体”也是三，但与此无关。","mcq":[{"q":"佛教“三宝”指的是","o":["经、律、论","戒、定、慧","佛、法、僧","天、人、阿修罗"],"a":2,"w":"三宝是佛、法、僧；经律论为三藏，戒定慧为三学。"}],"rel":[{"t":"戒定慧三学","n":"另一组佛教三合称"},{"t":"佛教基本教义","n":"“法”的主要内容"},{"t":"世界三大宗教","n":"佛教所属"}],"more":"皈依三宝后通常受五戒：不杀生、不偷盗、不邪淫、不妄语、不饮酒。","exam":[]},{"id":"b02-026","t":"菩萨与罗汉","cid":"02a","p":2,"kind":"概念","alias":["菩萨","罗汉","阿罗汉","菩提萨埵"],"one":"菩萨是大乘理想，自利利他；罗汉是上座部的解脱果位。","ans":"菩萨是梵语“菩提萨埵”的简称，意为觉悟的有情，是**大乘佛教的修行理想**，主张**自利利他**、普度众生，在中国影响最大的有观音、文殊、普贤、地藏四大菩萨。罗汉是“阿罗汉”的简称，是**上座部（小乘）佛教**修行者所能达到的最高解脱果位，侧重**自我解脱**，断尽烦恼后不再轮回。两者的差别体现了大乘与小乘对修行目标的不同理解。","pts":["菩萨：大乘理想，自利利他","罗汉：上座部解脱果位，侧重自度","大乘与小乘目标不同"],"mem":"对比记：菩萨“带人过河”，罗汉“自己上岸”。大乘重普度，所以中国寺庙里供的主要是菩萨；罗汉多以十八罗汉、五百罗汉的群像出现。","mix":"“小乘”是大乘对早期部派的贬称，学界常用“上座部”。罗汉不等于佛，佛是圆满觉悟，罗汉只是自己解脱。","mcq":[{"q":"关于菩萨与罗汉，下列说法正确的是","o":["罗汉是大乘理想，强调普度众生","菩萨是大乘理想，自利利他","菩萨是上座部的最高果位","二者都是道教神仙"],"a":1,"w":"菩萨是大乘的修行理想，罗汉是上座部的解脱果位。"}],"rel":[{"t":"大乘佛教","n":"菩萨道所属"},{"t":"南传佛教","n":"以罗汉为目标"},{"t":"四大佛教名山","n":"对应四大菩萨道场"}],"exam":[]},{"id":"b02-027","t":"法显《佛国记》","cid":"02c","p":2,"kind":"作品","alias":["佛国记","法显传","历游天竺记传","法显"],"one":"东晋法显西行求法的游记，现存最早的中国人赴印度旅行记。","ans":"《佛国记》又名《法显传》，是**东晋高僧法显**所著的西行游记。法显**399年**从长安出发，经西域翻越葱岭到达天竺，游历佛教圣地，抄得大批戒律经典，**412年由海路**经师子国（斯里兰卡）回国，历时十余年。书中记述了沿途约三十国的地理、风俗与佛教情况，是**现存最早的中国人赴印度旅行记**，也是研究中亚、南亚古代史和中外交通的重要史料。","pts":["东晋法显著，又名《法显传》","399年陆路去，412年海路回","现存最早的中国人赴印度游记"],"mem":"去陆回海：399年出发走陆路，412年乘船回来，经斯里兰卡。与玄奘对比：法显是东晋，玄奘是唐；法显写《佛国记》，玄奘口述《大唐西域记》，两本书相差约两百年。","mix":"法显（东晋，《佛国记》，陆去海回）、玄奘（唐，《大唐西域记》，往返陆路）、义净（唐，海路往返，《南海寄归内法传》）三者最易混。","mcq":[{"q":"东晋法显记述西行求法见闻的著作是","o":["《大唐西域记》","《佛国记》","《南海寄归内法传》","《洛阳伽蓝记》"],"a":1,"w":"《佛国记》即《法显传》；《大唐西域记》为玄奘口述。"}],"rel":[{"t":"玄奘","n":"唐代求法，作《大唐西域记》"},{"t":"《大唐西域记》","n":"常与之对举"},{"t":"丝绸之路","n":"西行路线"}],"exam":[]},{"id":"b02-028","t":"道安","cid":"02d","p":2,"kind":"人物","alias":["释道安","五失本三不易"],"one":"东晋高僧，倡僧人以“释”为姓，提出“五失本、三不易”。","ans":"道安（312–385）是**东晋高僧**，长期在前秦长安主持译经与讲学。他提倡**僧人一律以“释”为姓**，沿用至今；编撰《**综理众经目录**》，是中国最早的佛经目录（原书已佚，内容保存在《出三藏记集》中）；在译经理论上提出“**五失本、三不易**”，指出译经有五种可能失去原文本来面貌的情形和三种不易之处，是**中国早期重要翻译理论**。他还推荐鸠摩罗什入华，主持长安译场，对佛教在中国的本土化贡献很大。","pts":["东晋高僧，倡僧人姓“释”","编《综理众经目录》","提出译经“五失本、三不易”"],"mem":"“释”姓记法：道安说“僧人都跟释迦牟尼姓”。“五失本三不易”是中国最早成体系的翻译理论之一，记“五＋三＝八”，与严复“信达雅”“三”字对举。","mix":"道安不属于四大翻译家，他提出翻译理论，也并非译主；“五失本三不易”与玄奘的“五种不翻”都带“五”，不要混淆。","mcq":[{"q":"提出佛经翻译“五失本、三不易”的是","o":["道安","玄奘","鸠摩罗什","支谦"],"a":0,"w":"“五失本、三不易”出自东晋道安。"}],"rel":[{"t":"道安“五失本三不易”","n":"其翻译理论"},{"t":"鸠摩罗什","n":"由其推荐入华"},{"t":"格义","n":"他曾批评的方法"}],"exam":[]},{"id":"b02-029","t":"格义","cid":"02d","p":2,"kind":"概念","alias":["格义佛教","以玄解佛"],"one":"魏晋时用老庄等中国固有概念比附解释佛教义理的方法。","ans":"格义是**魏晋时期**佛教界用**中国固有的思想概念**，尤其是**老庄道家术语**，去比附、解释佛教义理的方法，例如以“无”比“空”、以“道”译“菩提”。它降低了佛教传入初期的理解难度，推动了佛教与玄学的融合，是佛教**中国化的早期形态**。但这种方法容易曲解佛理，东晋**道安**已提出批评，鸠摩罗什精确译经后，格义逐渐被取代。","pts":["魏晋，用老庄概念比附佛理","如以“无”比“空”","佛教中国化早期形态，后被道安批评"],"mem":"“格”是“比对”，“义”是“义理”：拿中国的术语去“对号入座”。例子记一个：用道家的“无”去解释佛教的“空”。","mix":"格义是方法，不是宗派；玄学兴盛的魏晋是它的背景。后来罗什、玄奘译经更忠实原文，格义逐渐退出。","mcq":[{"q":"魏晋时期佛教界用老庄概念比附佛理的方法称为","o":["格义","顿悟","会通","判教"],"a":0,"w":"格义以老庄等固有概念比附佛教义理。"}],"rel":[{"t":"魏晋玄学","n":"格义的思想背景"},{"t":"道家（老庄）","n":"借用术语的来源"},{"t":"道安","n":"批评格义"},{"t":"佛教汉译词","n":"后世术语的来源"}],"exam":[]},{"id":"b02-030","t":"译场","cid":"02d","p":2,"kind":"制度","alias":["译经场","译经院","传译场"],"one":"集体译经机构，设译主、笔受、度语、证义、润文等职。","ans":"译场是**中国古代佛经翻译的集体组织**，由多人分工合作完成译经。东晋道安已组织译场，**鸠摩罗什**在长安逍遥园、**玄奘**在长安大慈恩寺等主持的译场规模最大，后来朝廷设立国立译经院。译场分设**译主、笔受、度语、证义、润文**等职，分别负责主讲、记录、传译、审校与文字润色，使翻译兼顾准确和文采。译场是我国翻译史上**集体翻译的重要制度**。","pts":["集体译经机构，多人分工","译主、笔受、度语、证义、润文","罗什、玄奘主持过国立译场"],"mem":"流程像“流水线”：译主念梵文（宣读），度语转成汉语口语，笔受写成文字，证义核对义理，润文修饰文字。五个职位按顺序记“主、度、笔、证、润”。","mix":"译场是翻译机构，不是宗派；译主不一定是笔录者。江南制造总局翻译馆是近代翻译机构，与佛经译场性质不同，不要混。","mcq":[{"q":"下列职位中，不属于古代佛经译场分工的是","o":["译主","笔受","润文","主簿"],"a":3,"w":"译场设译主、笔受、度语、证义、润文等职，没有主簿。"}],"rel":[{"t":"鸠摩罗什","n":"主持长安译场"},{"t":"玄奘","n":"主持大慈恩寺译场"},{"t":"京师同文馆与江南制造总局翻译馆","n":"近代翻译机构对照"}],"exam":[]},{"id":"b02-031","t":"净土宗","cid":"02e","p":2,"kind":"流派","alias":["莲宗","白莲社","弥陀宗"],"one":"专念阿弥陀佛、求往生西方极乐世界的汉传宗派，慧远为初祖。","ans":"净土宗是**汉传佛教宗派**，主张口念“**南无阿弥陀佛**”，求死后往生**西方极乐世界**。东晋**慧远**在庐山东林寺邀集同道结**白莲社**，被后世尊为初祖，故又称莲宗。唐代**善导**确立称名念佛的修行法门，实际创立宗派。该宗修行简便，不要求高深义理，信众遍及社会各阶层，是中国流传最广的佛教宗派之一，也传入日本、朝鲜。","pts":["专念阿弥陀佛，往生西方极乐世界","东晋慧远结白莲社，为初祖","唐善导实际创立，修行简便"],"mem":"一句话串联：慧远立社（庐山），善导立宗（唐代），念的是“阿弥陀佛”。“净土”可联想“西方净土”，宗派名与目的地同名。","mix":"慧远是初祖，善导才是宗派实际创立者，题目问“初祖”选慧远，问“创立”多选善导。净土宗与禅宗都主张简易，但前者靠他力往生，后者靠自力见性。","mcq":[{"q":"净土宗被尊为初祖的是东晋的","o":["智顗","慧远","道宣","法藏"],"a":1,"w":"慧远在庐山东林寺结白莲社，后世尊为净土宗初祖。"}],"rel":[{"t":"慧远与东林寺","n":"初祖与祖庭"},{"t":"汉传佛教八宗","n":"八宗之一"},{"t":"禅宗","n":"同重简易修行"},{"t":"大乘佛教","n":"所属体系"}],"exam":[]},{"id":"b02-032","t":"天台宗","cid":"02e","p":2,"kind":"流派","alias":["法华宗","智者大师","智顗"],"one":"隋代智顗创立，依《法华经》，中国第一个本土佛教宗派。","ans":"天台宗是**隋代智顗（智者大师）在浙江天台山创立**的佛教宗派，因山得名，又称法华宗。该宗以**《法华经》**为最高经典，教义讲“**一心三观**”“一念三千”，主张**止观并重**、定慧双修。智顗的著作《法华玄义》《法华文句》《摩诃止观》合称天台三大部。天台宗是**中国第一个本土化的佛教宗派**，标志着佛教由单纯译介转向独立创宗，后传入朝鲜、日本。","pts":["隋智顗创立，因天台山得名","依《法华经》，止观并重","中国第一个本土宗派"],"mem":"“天台”在浙江，“法华”是经名，“智者”是尊号，三个名字对应同一个宗。记忆线：最早的本土宗派，所以最先出现在八宗表第一行。","mix":"天台宗和华严宗都讲圆融，前者依《法华经》，后者依《华严经》。创宗者智顗是隋人，华严宗法藏是唐人。","mcq":[{"q":"被称为中国佛教第一个本土宗派的是","o":["华严宗","法相宗","天台宗","三论宗"],"a":2,"w":"天台宗由隋代智顗创立，依《法华经》，最早本土化。"}],"rel":[{"t":"《法华经》","n":"根本经典"},{"t":"汉传佛教八宗","n":"八宗之一"},{"t":"华严宗","n":"同讲圆融，依经不同"},{"t":"净土宗","n":"同属隋唐宗派"}],"exam":[]},{"id":"b02-033","t":"藏传佛教","cid":"02b","p":2,"kind":"流派","alias":["藏传佛教","喇嘛教","藏语系佛教"],"one":"7世纪传入吐蕃，与苯教融合，有达赖班禅转世系统的佛教。","ans":"藏传佛教是**流传于我国藏族、蒙古族等地区的佛教**，属藏语系。**7世纪**佛教传入吐蕃，相传与松赞干布迎娶文成公主、尺尊公主有关，后与当地**苯教**融合，形成独具特色的密教化体系。主要有宁玛、萨迦、噶举、格鲁四大派，**格鲁派**由宗喀巴创立，俗称黄教，其**达赖、班禅转世系统**影响最大。元代尊八思巴为帝师，清代设金瓶掣签制度，使藏传佛教与中央政权关系日益密切。","pts":["7世纪传入吐蕃，与苯教融合","四大派，格鲁派（黄教）最盛","达赖、班禅活佛转世系统"],"mem":"“藏传四大派”口诀：宁萨噶格，宁玛（红）、萨迦（花）、噶举（白）、格鲁（黄）。传入线索记人物：松赞干布、文成公主，再到宗喀巴、五世达赖。","mix":"藏传佛教（藏语系，大乘为主，兼有密宗）与南传佛教（巴利语系，上座部）不同；“喇嘛教”是旧称，现多不用。","mcq":[{"q":"下列关于藏传佛教的说法，正确的是","o":["属于巴利语系","格鲁派由宗喀巴创立","四大派中包括天台宗","主要流行于斯里兰卡"],"a":1,"w":"格鲁派（黄教）为明初宗喀巴所创，藏传佛教属藏语系。"}],"rel":[{"t":"藏传佛教四大派","n":"内部四个派别"},{"t":"宗喀巴与格鲁派","n":"格鲁派创立者"},{"t":"达赖与班禅（活佛转世与金瓶掣签）","n":"转世制度"},{"t":"佛教三大语系","n":"藏语系"}],"exam":[]},{"id":"b02-034","t":"南传佛教","cid":"02b","p":2,"kind":"流派","alias":["上座部佛教","巴利语系佛教","南传上座部"],"one":"上座部佛教，用巴利语，流行斯里兰卡、东南亚及云南傣族地区。","ans":"南传佛教即**上座部佛教**，属**巴利语系**，相传由**阿育王之子摩哂陀**传入斯里兰卡，再传到缅甸、泰国、老挝、柬埔寨等东南亚国家。它保持早期佛教面貌，以**阿罗汉**为修行目标，经典用巴利语书写。传入我国后，主要流行于**云南傣族**、布朗族、德昂族等地区。南传佛教与汉传佛教、藏传佛教并称佛教三大传承。","pts":["上座部佛教，巴利语系","流行斯里兰卡、缅甸、泰国","我国云南傣族等地区信仰"],"mem":"一个“南”字串起来：南传＝向南传＝斯里兰卡、东南亚＝巴利语＝上座部。云南西双版纳的傣族寺院是国内最典型的一处。","mix":"南传（巴利语、上座部）与汉传（汉语、大乘为主）、藏传（藏语）三个语系常被放在一起考，不要把傣族地区的佛教误选为藏传。","mcq":[{"q":"我国云南傣族地区流行的佛教属于","o":["汉传佛教","藏传佛教","南传佛教","密宗"],"a":2,"w":"傣族等信仰南传上座部佛教。"}],"rel":[{"t":"佛教三大语系","n":"属巴利语系"},{"t":"阿育王","n":"派子传法斯里兰卡"},{"t":"菩萨与罗汉","n":"以罗汉为目标"},{"t":"汉传佛教","n":"并称三大传承"}],"exam":[]},{"id":"b02-035","t":"全真道","cid":"02g","p":2,"kind":"流派","alias":["全真教","全真派","龙门派"],"one":"金代王重阳创立的北方道教派别，主性命双修、出家清修。","ans":"全真道是**金代王重阳创立的道教派别**，盛行于**北方**，与南方的正一道并称道教两大派。该派主张**儒、释、道三教合一**，重内丹修炼，强调**性命双修**，要求道士出家、不娶妻、住宫观。王重阳弟子**全真七子**中的**丘处机**曾远赴西域觐见**成吉思汗**，受命掌管天下道教，全真道由此兴盛。祖庭为陕西鄠邑（原户县）重阳宫，**北京白云观**是龙门派祖庭，号称“全真第一丛林”。","pts":["金王重阳创立，北方道派","三教合一，性命双修，出家清修","丘处机谒成吉思汗，白云观为龙门祖庭"],"mem":"“全真”可拆成“保全真性”，所以要出家清修。南北对举：全真在北，正一在南；全真出家，正一可以娶妻。丘处机觐见成吉思汗，是全真走向兴盛的转折，一句话记：丘处机见成吉思汗，全真由此成大派。","mix":"全真道与正一道的区别：全真重内丹，出家；正一重符箓，可居家。龙门派是丘处机一系，祖庭在北京白云观，不要与陕西重阳宫混。","mcq":[{"q":"下列关于全真道的说法，正确的是","o":["创立者是东汉张道陵","以符箓为主，道士可以婚娶","丘处机曾谒见成吉思汗","盛行于南方，以龙虎山为中心"],"a":2,"w":"全真道由金代王重阳创立，盛行北方，重出家清修；丘处机曾谒见成吉思汗。"}],"rel":[{"t":"全真七子","n":"王重阳七位弟子"},{"t":"正一道","n":"南北两大派对举"},{"t":"道教","n":"所属宗教"},{"t":"三教合一","n":"全真道主张"}],"exam":[]},{"id":"b02-036","t":"葛洪《抱朴子》","cid":"02g","p":2,"kind":"人物","alias":["葛洪","抱朴子","葛稚川"],"one":"东晋道教理论家，《抱朴子》内篇论神仙炼丹，外篇论政治伦理。","ans":"葛洪（约284–364），**东晋道教理论家、医药学家**，号抱朴子，丹阳句容人。他出身士族，系统总结魏晋以来的神仙方术，著**《抱朴子》**，其中**内篇论神仙、炼丹、符箓**，**外篇论政治得失与人事伦理**，主张“**内神仙而外儒术**”。他把神仙信仰与儒家纲常结合，为道教争取士族接受，**奠定了道教的神仙理论**。他还著有《肘后备急方》，是重要的医学著作。","pts":["东晋道教理论家，号抱朴子","内篇论神仙炼丹，外篇论政治伦理","内神仙而外儒术，奠定神仙理论"],"mem":"“抱朴”二字就是葛洪的号，也是书名。内篇讲“神仙”（外丹炼丹与方术），外篇讲“人间”（政治伦理），可记成：内篇仙，外篇俗。另外他还写了医书《肘后备急方》，一书两面：修道与医药。","mix":"魏晋南北朝对道教的改革者有寇谦之（北魏）、陆修静（南朝宋）、陶弘景（南朝梁），葛洪时间在前，主要贡献是理论而非教团改革。生卒年也有“283–363”等说法。","mcq":[{"q":"《抱朴子》的作者是","o":["陶弘景","葛洪","寇谦之","陆修静"],"a":1,"w":"《抱朴子》为东晋葛洪所著，内篇论神仙，外篇论政治伦理。"}],"rel":[{"t":"道教","n":"神仙理论奠基者"},{"t":"《道德经》与《道藏》","n":"道教典籍"},{"t":"五斗米道（天师道）与太平道","n":"早期教团，对举"},{"t":"三教合一","n":"内神仙外儒术的先声"}],"more":"《抱朴子》内篇20卷，外篇50卷。\n另著《肘后备急方》。","exam":[]},{"id":"b02-037","t":"四大佛教名山","cid":"02f","p":2,"kind":"合称","alias":["佛教四大名山"],"one":"五台山文殊、峨眉山普贤、普陀山观音、九华山地藏。","ans":"四大佛教名山是**汉传佛教四大菩萨的道场**：**山西五台山供奉文殊菩萨，四川峨眉山供奉普贤菩萨，浙江普陀山供奉观音菩萨，安徽九华山供奉地藏菩萨**。文殊象征智慧，普贤象征行愿，观音象征大悲，地藏象征大愿。四座名山分居山西、四川、浙江、安徽，历代寺院林立，是**汉传佛教信仰和朝圣的中心**，也是重要的旅游与文化遗产地。","pts":["五台山文殊、峨眉山普贤","普陀山观音、九华山地藏","四大菩萨道场，智慧、行愿、大悲、大愿"],"members":[["五台山","山西，文殊菩萨，智慧"],["峨眉山","四川，普贤菩萨，行愿"],["普陀山","浙江，观音菩萨，大悲"],["九华山","安徽，地藏菩萨，大愿"]],"mem":"通行口诀：智（文殊）、行（普贤）、悲（观音）、愿（地藏）。山名配菩萨按“五文、峨普、陀观、九地”记：五台配文殊，峨眉配普贤，普陀配观音，九华配地藏。","mix":"四大佛教名山与“道教四大名山”（武当山、龙虎山、青城山、齐云山）不同；普陀山在浙江舟山，是海岛，别与四川峨眉山混。","mcq":[{"q":"供奉观音菩萨的佛教名山是","o":["五台山","峨眉山","九华山","普陀山"],"a":3,"w":"观音道场在浙江普陀山；五台文殊，峨眉普贤，九华地藏。"},{"q":"安徽九华山供奉的菩萨是","o":["地藏","文殊","普贤","观音"],"a":0,"w":"九华山为地藏菩萨道场。"}],"rel":[{"t":"佛教四大圣地","n":"印度佛教圣地，对举"},{"t":"道教四大名山","n":"道教对应的四座名山"},{"t":"汉传佛教","n":"所属体系"},{"t":"大乘佛教","n":"菩萨信仰所属"}],"exam":[]},{"id":"b02-038","t":"道教四大名山","cid":"02g","p":3,"kind":"合称","alias":["中国道教四大名山","道教名山"],"one":"中国道教史上声名最显赫的四大名山仙境：武当山、龙虎山、齐云山、青城山。","ans":"道教四大名山是中国道教洞天福地的卓越代表：**湖北武当山、江西龙虎山、安徽齐云山、四川青城山**。武当山供奉**真武大帝**，龙虎山为**正一派天师道祖庭**，齐云山宫观宏整，青城山为创教圣地，集道教仙道文化与自然山水之大成。","pts":["湖北武当山、江西龙虎山、安徽齐云山、四川青城山","武当真武、龙虎天师、齐云胜景、青城发源","展现中国道教宫观建筑与洞天福地文化"],"members":[["湖北武当山","主祀真武大帝，玄武神道场，武当内家拳发源地"],["江西龙虎山","张道陵第四代天师张盛定居之地，正一天师道历代祖庭"],["安徽齐云山","古称白岳，供奉真武大帝，以丹霞地貌与道教石刻著称"],["四川青城山","张道陵创道结茅传教之所，青城派发源地，号“青城天下幽”"]],"mem":"首字联想：“**武龙齐青**”（鄂武当、赣龙虎、皖齐云、川青城）；对应佛教四大名山“五峨九普”。","mix":"道教四大名山中，武当山和齐云山均供奉真武大帝；佛教四大名山则是五台山、峨眉山、普陀山、九华山，切勿混淆。","mcq":[{"q":"下列不属于中国“道教四大名山”的是","o":["湖北武当山","江西龙虎山","四川青城山","山西五台山"],"a":3,"w":"山西五台山为中国佛教四大名山之一（文殊菩萨道场），不属于道教四大名山（武当、龙虎、齐云、青城）。"}],"rel":[{"t":"四大佛教名山","n":"佛道名山并称对照"},{"t":"张道陵、张角","n":"张道陵传道青城龙虎"},{"t":"正一道","n":"龙虎山为正一祖庭"}],"exam":[]},{"id":"b02-039","t":"开元三大士","cid":"02e","p":3,"kind":"合称","alias":["密宗三大士","唐代三大士"],"one":"唐玄宗开元年间来华弘传印度密教的三位印度高僧善无畏、金刚智、不空。","ans":"开元三大士指唐玄宗开元年间来华的三位印度高僧**善无畏、金刚智、不空**。善无畏译出《大日经》，金刚智与不空传金刚界密法。三人受到朝廷推崇，在长安系统翻译**真言密教经典**并设坛灌顶，促成了**中国汉传密宗的正式确立**。","pts":["唐开元年间来华高僧善无畏、金刚智、不空","系统译出《大日经》等金胎两部密宗根本圣典","开创并确立了汉传密宗（真言宗）法统"],"members":[["善无畏","中天竺僧人，入长安受玄宗敬重，译出胎藏界《大日经》"],["金刚智","南天竺僧人，弘传金刚界密法，译出《金刚顶瑜伽中略出念诵法》"],["不空","师从金刚智，唐代四大翻译家之一，集密教大成，官至特进试鸿胪卿"]],"mem":"首字口诀：“**善金不**”（善无畏、金刚智、不空）；玄宗开元年间齐聚长安立密宗。","mix":"汉传佛教四大翻译家包含不空（另三位鸠摩罗什、真谛、玄奘），善无畏与金刚智不在四大译家之列。","mcq":[{"q":"下列高僧中，兼列“开元三大士”与“佛经四大翻译家”的是","o":["善无畏","不空","金刚智","鸠摩罗什"],"a":1,"w":"不空既是弘传密宗的开元三大士之一，也是佛经四大翻译家之一。"}],"rel":[{"t":"密宗","n":"汉传密宗创立核心"},{"t":"不空","n":"三大士之一兼四大译家"},{"t":"佛经四大翻译家","n":"不空名列其中"}],"exam":[]},{"id":"b02-040","t":"什门四圣","cid":"02d","p":1,"kind":"合称","exam":["2022选择"],"alias":["什门","罗什四圣"],"one":"鸠摩罗什四大弟子：道生、僧肇、道融、僧叡。","ans":"什门四圣指**鸠摩罗什门下四位杰出弟子：道生、僧肇、道融、僧叡**。四人**在后秦长安译场随罗什译经、讲学**。僧肇著**《肇论》**，阐发般若空义；道生倡**“顿悟成佛”**和一阐提人也能成佛；道融通晓经论，参与译经；僧叡协助译场并为多部译经作序。他们使罗什传译的**大乘中观思想**在中国扎根，道生的顿悟说后来影响**禅宗**。","pts":["罗什四大弟子","道生、僧肇、道融、僧叡","僧肇《肇论》，道生顿悟成佛"],"members":[["道生","倡“顿悟成佛”"],["僧肇","著《肇论》"],["道融","通晓经论，参与译经"],["僧叡","协助译场，为译经作序"]],"mem":"口诀“**生肇融叡**”。功能各记一个：肇写《肇论》，生讲顿悟，融叡襄助译场。","mix":"什门四圣是弟子合称，不是四大翻译家；慧远是同时期庐山高僧，不是罗什弟子。另有“什门八俊”等更大范围的说法。","mcq":[{"q":"著有《肇论》，属“什门四圣”的是","o":["道安","道生","慧远","僧肇"],"a":3,"w":"《肇论》是僧肇的代表作。"},{"q":"提出“顿悟成佛”的鸠摩罗什弟子是","o":["僧肇","道生","道融","僧叡"],"a":1,"w":"道生主张顿悟成佛，后影响禅宗。"}],"rel":[{"t":"鸠摩罗什","n":"老师"},{"t":"顿悟","n":"道生的主张"},{"t":"三论宗","n":"所传三论的宗派"},{"t":"道安","n":"同期高僧，常作干扰项"},{"t":"译场","n":"四圣参与的译场"}]},{"id":"b02-041","t":"安世高、支谦","cid":"02d","p":2,"kind":"人物","alias":["安世高","支谦","支娄迦谶"],"one":"东汉安世高译小乘经典，三国支谦译经文辞典雅。","ans":"安世高是**东汉桓帝时来华的安息国僧人**，约148年到洛阳，主要翻译**小乘禅数之学**经典，如《安般守意经》，是佛经汉译的开创者之一。支谦是**三国吴国**月氏后裔，通晓多种语言，译有《维摩诘经》《大明度经》等，译文**文辞典雅**，善用中国习语。二人与东汉译大乘般若的支娄迦谶合称早期译经代表。二人开启了佛经汉译的先河，为后来罗什、玄奘的大规模翻译奠定了基础。","pts":["安世高：东汉，安息人，译小乘经典","支谦：三国吴，译《维摩诘经》，文辞典雅","佛经汉译开端"],"mem":"时代与风格各记一字：“安”东汉，译“小乘”；“支”三国，译“典雅”。对比支娄迦谶：东汉大乘般若。三人同在“罗什之前”的早期译经阶段。","mix":"安世高译小乘，支娄迦谶译大乘，是东汉并称的两位译家；支谦是三国吴人，不要写成东汉。四大译经家不包括这几位。","mcq":[{"q":"东汉时来华译经、主要翻译小乘经典的僧人是","o":["支谦","安世高","鸠摩罗什","真谛"],"a":1,"w":"安世高是安息僧人，东汉译小乘；支谦为三国吴人。"}],"rel":[{"t":"鸠摩罗什","n":"后起的旧译代表"},{"t":"永平求法与《四十二章经》","n":"同属佛经汉译开端"},{"t":"中国翻译史四次高潮","n":"第一次高潮的早期"}],"exam":[]},{"id":"b02-042","t":"窥基","cid":"02d","p":3,"kind":"人物","alias":["慈恩大师","百部疏主","大乘基"],"one":"唐代唯识宗高僧，玄奘弟子，汉传佛教法相唯识宗实际创始人之一。","ans":"窥基（632–682），字洪道，唐代高僧，**玄奘核心弟子与法嗣**。长居大慈恩寺，世称**慈恩大师**。他协助玄奘翻译佛经并撰写大量注疏，著有《成唯识论述记》，号称“百部疏主”，是**法相宗（唯识宗）的实际创立者**之一。","pts":["唐代高僧，玄奘弟子，世称慈恩大师","撰《成唯识论述记》，号称“百部疏主”","汉传法相宗（唯识宗）的实际创立者之一"],"mem":"谐音记忆：“**玄奘带窥基，慈恩立唯识**”；慈恩寺里窥基著述多，号称“百部疏主”。","mix":"玄奘译出《成唯识论》奠定法相宗基础，但唯识宗的教理体系整理与宗派实际建立主要由窥基完成。","mcq":[{"q":"玄奘弟子中，著有《成唯识论述记》、号称“百部疏主”，与玄奘共同创立汉传法相宗的高僧是","o":["窥基","圆测","神秀","辨机"],"a":0,"w":"窥基常住大慈恩寺，世称慈恩大师，是法相唯识宗的实际创始人之一。"}],"rel":[{"t":"玄奘","n":"玄奘弟子与主要助手"},{"t":"法相宗（唯识宗）","n":"该宗派实际创立者"},{"t":"佛经四大翻译家","n":"协助玄奘译场工作"}],"exam":[]},{"id":"b02-043","t":"大藏经","cid":"02b","p":3,"kind":"作品","alias":["藏经","一切经"],"one":"汉文及东方各语系佛教典籍经、律、论三藏的总集全称。","ans":"大藏经又称“一切经”，是**汉文佛教典籍的总集**。按**经、律、论三藏**分类汇编，兼收历代高僧撰述。宋代敕刻**《开宝藏》为第一部木刻本大藏经**，明清有《永乐北藏》《乾隆大藏经》，奠定了东亚汉字文化圈佛教文献整理之典范。","pts":["汉文佛教典籍汇编总集，涵盖经律论三藏","宋代《开宝藏》为第一部木刻本大藏经","是东亚汉字文化圈佛学研究与文献保存集大成者"],"mem":"记忆法：“**经律论合称三藏，宋代开宝首刻印**”。","mix":"“三藏”原指经藏、律藏、论藏三种类别的佛典；《大藏经》则是历代将所有三藏及注疏汇纂印行的丛书统称。","mcq":[{"q":"中国历史上第一部木版雕刻印刷的汉文大藏经是","o":["《赵城金藏》","《开宝藏》","《永乐北藏》","《房山石经》"],"a":1,"w":"北宋开宝年间开雕的《开宝藏》（又称《蜀版大藏经》）是中国第一部官刻本大藏经。"}],"rel":[{"t":"《出三藏记集》","n":"大藏经编纂之目录先导"},{"t":"佛教三大语系","n":"汉文大藏经是汉传根基"},{"t":"玄奘","n":"译经大量收入大藏经"}],"exam":[]},{"id":"b02-044","t":"禅宗五家七宗","cid":"02e","p":2,"kind":"合称","alias":["五家七宗","禅门五宗","五家七派"],"one":"禅宗南宗的五家分派，加临济分出的黄龙、杨岐，合称七宗。","ans":"五家七宗指**禅宗慧能南宗系统在唐末五代至宋代形成的分派**。五家为**临济、曹洞、沩仰、云门、法眼**，其中临济宗在宋代又分出**黄龙、杨岐**两派，合称“七宗”。各家在接引学人的方法上各有特色，如临济宗的棒喝。五家中**临济宗、曹洞宗流传最久**，后来分别传入日本，成为日本禅宗的主要源头。","pts":["五家：临济、曹洞、沩仰、云门、法眼","临济分出黄龙、杨岐，合七宗","临济、曹洞流传最久"],"members":[["临济宗","义玄创立，棒喝，后分黄龙、杨岐"],["曹洞宗","良价、本寂，传入日本"],["沩仰宗","灵祐、慧寂，最早衰落"],["云门宗","文偃创立"],["法眼宗","文益创立"],["黄龙派","临济分支"],["杨岐派","临济分支"]],"mem":"五家首字串联：临、曹、沩、云、法。可编成“临曹沩云法”，再加“临济分二（黄龙杨岐）”。七宗是五家加二，不另加新家。","mix":"七宗是五家加上临济分出的黄龙、杨岐，没有新增独立的家。五家同属慧能南宗一系，北宗神秀一系早已衰落。","mcq":[{"q":"下列属于禅宗“五家”的是","o":["黄龙宗","杨岐宗","云门宗","三论宗"],"a":2,"w":"五家是临济、曹洞、沩仰、云门、法眼；黄龙、杨岐是临济分支，三论宗不属禅宗。"}],"rel":[{"t":"禅宗","n":"所属宗派"},{"t":"禅宗六祖","n":"传承源流"},{"t":"慧能与《六祖坛经》","n":"南宗开创者"},{"t":"汉传佛教八宗","n":"同属汉传宗派"}],"exam":[]},{"id":"b02-045","t":"张道陵、张角","cid":"02g","p":3,"kind":"人物","alias":["张天师与张角","早期道教创始人"],"one":"东汉末期早期道教两大派别的开创者：张道陵创五斗米道，张角创太平道。","ans":"张道陵与张角是**东汉末期早期道教创始人**。张道陵在四川鹤鸣山创立**五斗米道（天师道）**，被尊为“张天师”，开创道教教职世袭体系；张角在北方创立**太平道**，以符水治病传教，于184年发动**黄巾起义**。二人开辟了道教组织化教派时代。","pts":["张道陵创五斗米道（天师道），世称祖天师","张角创太平道，以符水布道并组织黄巾起义","标志着中国道教正式形成有组织的宗教体系"],"mem":"区分口诀：“**天师道陵走四川，太平张角闹黄巾**”；西南五斗米，北方太平道。","mix":"张道陵创立五斗米道（天师道），注重修道世袭传教；张角创立太平道，旨在发动反抗东汉王朝的农民起义。","mcq":[{"q":"东汉顺帝年间在四川鹤鸣山创立五斗米道、被尊为道教“祖天师”的是","o":["张道陵","张角","张鲁","葛洪"],"a":0,"w":"张道陵创立五斗米道（天师道），为正一天师道之始祖。"}],"rel":[{"t":"五斗米道（天师道）与太平道","n":"所创早期道教派别"},{"t":"道教四大名山","n":"青城龙虎奉张道陵"},{"t":"正一道","n":"张道陵后裔继承派别"}],"exam":[]},{"id":"b02-046","t":"太上老君","cid":"02g","p":3,"kind":"人物","alias":["道德天尊","老君","太清道德天尊"],"one":"道教最高尊神“三清”之一，先秦思想家老子的神格化身尊号。","ans":"太上老君是**道教最高信仰“三清”尊神之一**，位列太清境道德天尊。东汉道教将先秦道家学派创始人**老子神格化**，尊为教祖，神化其为“太上老君”。道教视其为开天辟地与传道度人的至尊化身，尊《道德经》为宗经，**标志着道家向道教的宗教演变**。","pts":["道教三清尊神之一，全称太清道德天尊","由先秦道家先驱老子神化演变而来","道教尊为教祖与传经开道的根本尊神"],"mem":"巧记：“**老子西出函谷关，道教神化拜老君**”；三清为玉清元始、上清灵宝、太清道德（老君）。","mix":"老子是先秦时期的历史人物与哲学家；太上老君是道教在神化老子后形成的最高宗教神祇。","mcq":[{"q":"在道教最高神仙体系“三清”中，由先秦思想家老子神格化而来的是","o":["元始天尊","道德天尊","灵宝天尊","太乙救苦天尊"],"a":1,"w":"道德天尊又称太上老君，居太清境，是道教对老子的神化尊称。"}],"rel":[{"t":"太上老君与道教三清","n":"道教最高三清体系"},{"t":"《道德经》与《道藏》","n":"所撰经典升华为道藏"},{"t":"道法自然与无为而治","n":"老子哲学原初思想"}],"exam":[]},{"id":"b02-047","t":"宗教改革","cid":"02h","p":3,"kind":"事件","alias":["欧洲宗教改革","16世纪宗教改革"],"one":"16世纪欧洲反对罗马教会神权统治、催生基督教新教的深刻思想社会运动。","ans":"宗教改革是**16世纪欧洲反罗马教会统治的深刻变革**。1517年马丁·路德发表**《九十五条论纲》**反对赎罪券，倡导**“因信称义”**；加尔文提出预定论。该运动打破了天主教神权大一统格局，催生了**基督教新教三大主流教派**，加速了欧洲近代化。","pts":["1517年马丁·路德发论纲倡导“因信称义”","反对教皇权威与赎罪券，主张信徒直通上帝","分裂天主教并创立基督教新教三大宗派"],"mem":"记忆法：“**1517路德纲，因信称义立新教**”；核心信条是唯独圣经、因信称义。","mix":"宗教改革产生的是新教（抗罗宗），包含路德宗、加尔文宗、英国国教等；天主教与东正教早在1054年即已完成东西大分裂。","mcq":[{"q":"1517年发表《九十五条论纲》抨击教会出售赎罪券、拉开欧洲宗教改革序幕的宗教改革家是","o":["马丁·路德","加尔文","亨利八世","慈运理"],"a":0,"w":"德意志维滕贝格大学神学教授马丁·路德发表《九十五条论纲》，正式揭开欧洲宗教改革的序幕。"}],"rel":[{"t":"马丁·路德与德语《圣经》","n":"改革领袖与译经成果"},{"t":"新教三大宗派","n":"宗教改革产生的新教派系"},{"t":"天主教、东正教与新教","n":"基督教三大教派格局确立"}],"exam":[]},{"id":"b02-048","t":"麦加与麦地那","cid":"02h","p":3,"kind":"地理","alias":["伊斯兰教两大圣地","两圣地"],"one":"伊斯兰教最神圣的第一、第二大圣地，穆罕默德传教与建政核心圣城。","ans":"麦加与麦地那位于沙特阿拉伯，是**伊斯兰教第一、第二大圣地**。**麦加为穆罕默德诞生地**与克尔白圣寺所在地，为全球穆斯林朝觐方向；公元622年**穆罕默德迁徙麦地那（“希吉拉”）**并建立穆斯林政权，该年成为**伊斯兰历纪元元年**。","pts":["沙特麦加为第一圣地、穆罕默德诞生地与朝向","麦地那为第二圣地、穆罕默德陵寝与早期政权中心","622年迁徙麦地那（希吉拉）定为伊斯兰教历纪元"],"mem":"巧记：“**生于麦加立朝向，迁至麦地开纪元**”；希吉拉出逃是伊斯兰教纪元之始。","mix":"伊斯兰教圣城排位：第一麦加（朝觐圣地），第二麦地那（先知寺），第三耶路撒冷（远寺圣地，阿克萨清真寺）。","mcq":[{"q":"伊斯兰历（回历）将哪一年定为纪元元年","o":["610年穆罕默德受启示之年","622年穆罕默德迁徙麦地那之年","630年光复麦加之年","632年穆罕默德归真之年"],"a":1,"w":"公元622年穆罕默德率信徒由麦加迁徙至麦地那（史称“希吉拉”），这一年被定为伊斯兰历纪元元年。"}],"rel":[{"t":"伊斯兰教","n":"创教圣地与信仰中心"},{"t":"伊斯兰教五功","n":"朝功以麦加为终点"},{"t":"《古兰经》","n":"麦加章与麦地那章"}],"exam":[]},{"id":"b02-049","t":"《出三藏记集》","cid":"02d","p":3,"kind":"作品","alias":["僧祐录"],"one":"南朝梁代僧祐编撰的现存最早的中国佛教经典目录与译经史料汇编。","ans":"《出三藏记集》十五卷，南朝梁代高僧**僧祐编撰**，是**中国现存最早的佛经目录**与佛学文献专著。该书承袭东晋道安《综理众经目录》体例，详录译经史料并收录大量珍贵经序，为**研究早期佛教翻译史与文献学**的奠基性典籍。","pts":["南朝梁僧祐编撰，现存最早的佛经目录","继承道安体例，收录丰富译经目录与经序","中国佛教文献学与翻译史研究的奠基之作"],"mem":"记忆法：“**道安开目录，僧祐存最早**”；东晋道安最早编录但已佚，梁代僧祐编撰得以完整流传。","mix":"中国最早的佛经目录是东晋道安《综理众经目录》（已佚）；“现存最早”的佛经目录则是僧祐《出三藏记集》。","mcq":[{"q":"南朝梁代僧祐编撰、保存了大量早期汉译佛典序文与译者传记的中国现存最早佛经目录是","o":["《开元释教录》","《出三藏记集》","《历代三宝纪》","《众经目录》"],"a":1,"w":"僧祐所撰《出三藏记集》十五卷是中国现存最早的佛经目录。"}],"rel":[{"t":"道安","n":"继承其经录体例"},{"t":"大藏经","n":"佛典目录汇编先河"},{"t":"支谦《法句经序》","n":"收录早期翻译史料"}],"exam":[]},{"id":"c-007","t":"四谛","cid":"02a","p":1,"kind":"合称","alias":["苦集灭道","四圣谛"],"one":"苦、集、灭、道，佛教最根本的教义。","ans":"四谛是**释迦牟尼初次说法（初转法轮）时宣说的佛教根本教义**，即**苦谛、集谛、灭谛、道谛**，简称“苦集灭道”。苦谛指人生充满生老病死之苦；集谛指苦的原因是贪欲与烦恼；灭谛指断除烦恼即可达到**涅槃**；道谛指通向涅槃的方法，主要是**八正道**。相传释迦牟尼成道后在鹿野苑为五比丘初次说法，讲的就是四谛。它构成“认识问题、找出原因、确立目标、给出方法”的完整逻辑，是各宗派共同承认的基础。","pts":["苦集灭道，初转法轮所说","苦的原因是贪欲烦恼","灭达涅槃，道即八正道"],"members":[["苦谛","人生皆苦：生老病死等"],["集谛","苦的原因是贪欲烦恼"],["灭谛","断除烦恼达到涅槃"],["道谛","解脱的方法，即八正道"]],"mem":"医生看病四步：诊断（**苦**）、查病因（**集**）、说明可治愈（**灭**）、开药方（**道**，八正道）。先问“有什么病”，再问“为什么”“能不能好”“怎么治”。","mix":"“谛”意为真理。道谛的内容就是八正道，别把八正道当成四谛之外的另一组教义。","mcq":[{"q":"四谛中指出“苦的原因”的是","o":["灭谛","集谛","苦谛","道谛"],"a":1,"w":"集谛说明苦由贪欲烦恼聚集招感而来。"},{"q":"四谛中“道谛”的具体内容是","o":["五戒","六度","八正道","三法印"],"a":2,"w":"道谛是通向涅槃的方法，即八正道。"}],"rel":[{"t":"八正道","n":"道谛的具体内容"},{"t":"佛教基本教义","n":"四谛是核心"},{"t":"释迦牟尼","n":"初转法轮宣说"},{"t":"涅槃","n":"灭谛的境界"}],"exam":[]},{"id":"c-008","t":"三法印","cid":"02a","p":2,"kind":"合称","alias":["三法印","诸行无常","诸法无我","涅槃寂静"],"one":"诸行无常、诸法无我、涅槃寂静，检验是否佛法的三条标准。","ans":"三法印是佛教判别某种说法是否合乎佛法的**三条标准**，即**诸行无常、诸法无我、涅槃寂静**。“诸行无常”指一切现象都在生灭变化；“诸法无我”指一切事物都没有永恒不变的自我实体；“涅槃寂静”指**熄灭烦恼后达到的寂静境界**。“印”有印证、印信之意，符合这三条的才算佛法正见，它们概括了佛教对世界与人生的基本看法。","pts":["诸行无常","诸法无我","涅槃寂静，判别佛法的标准"],"members":[["诸行无常","一切现象不断生灭变化"],["诸法无我","事物没有永恒的自我实体"],["涅槃寂静","烦恼熄灭后的寂静境界"]],"mem":"按“变化、无我、解脱”的逻辑线记：世界在变（无常），所以没有不变的我（无我），看透后就能达到寂静（涅槃）。有的说法再加“有漏皆苦”成四法印。","mix":"三法印与四圣谛（苦集灭道）不同，前者是判别标准，后者是教义结构。“有漏皆苦”属于四法印的第四项。","mcq":[{"q":"下列属于佛教“三法印”的是","o":["苦、集、灭","诸行无常","佛、法、僧","天、人、阿修罗"],"a":1,"w":"三法印为诸行无常、诸法无我、涅槃寂静。"}],"rel":[{"t":"涅槃","n":"三法印之一的目标"},{"t":"佛教基本教义","n":"同属核心教义"},{"t":"缘起与业报轮回","n":"无常无我的因果基础"}],"exam":[]},{"id":"c-009","t":"六道","cid":"02a","p":2,"kind":"合称","alias":["六道轮回","六趣"],"one":"天、人、阿修罗、畜生、饿鬼、地狱，众生依业轮回之所。","ans":"六道是佛教所说众生依**业力**轮回转生的**六种去处**，即**天、人、阿修罗、畜生、饿鬼、地狱**。前三者称“三善道”，后三者称“三恶道”。佛教认为众生因所造善恶业的不同而在六道中往复流转，只有修行证得**涅槃**才能脱出轮回。六道观念把因果报应具体化，对中国民间的善恶观、地狱想象和文学艺术影响很深。","pts":["天、人、阿修罗、畜生、饿鬼、地狱","前三善道，后三恶道","依业轮回，涅槃方可解脱"],"members":[["天","三善道，福报最大"],["人","三善道"],["阿修罗","三善道，好斗"],["畜生","三恶道"],["饿鬼","三恶道"],["地狱","三恶道，苦最重"]],"mem":"顺口顺序“天人修，畜鬼狱”：前三个是善道（天、人、修罗），后三个是恶道（畜生、饿鬼、地狱）。人道夹在中间，所以说“人身难得”。","mix":"六道是轮回的六个去处，不是六种修行道路；加上声闻、缘觉、菩萨、佛四圣，合称“十法界”。","mcq":[{"q":"下列不属于佛教“六道”的是","o":["饿鬼","菩萨","阿修罗","畜生"],"a":1,"w":"六道为天、人、阿修罗、畜生、饿鬼、地狱，菩萨属于“四圣”。"}],"rel":[{"t":"缘起与业报轮回","n":"六道轮回的教义基础"},{"t":"涅槃","n":"脱离六道的目标"},{"t":"佛教基本教义","n":"同属核心教义"}],"exam":[]},{"id":"a02-001","t":"八正道","cid":"02a","p":1,"kind":"合称","alias":["正道"],"one":"四谛中道谛的内容：正见、正思维、正语、正业、正命、正精进、正念、正定。","ans":"八正道是**佛教四谛中“道谛”的具体内容**，指通向涅槃的八条正确修行途径，即**正见、正思维、正语、正业、正命、正精进、正念、正定**。其中正见、正思维属慧，正语、正业、正命属戒，正精进、正念、正定属定，可归入**“戒定慧”三学**。八正道避开纵欲与苦行两个极端，因此又称**“中道”**。它是释迦牟尼初转法轮所说的修行纲领，也是信徒日常修行的基本准则。","pts":["道谛的内容，通向涅槃","八项：见思语业命进念定","归入戒定慧，也称中道"],"members":[["正见","正确认识四谛与缘起"],["正思维","正确的思考与意愿"],["正语","不妄语、不恶口等"],["正业","正当的行为，不杀不盗不淫"],["正命","正当的谋生方式"],["正精进","勤修善法、断除恶法"],["正念","心念专注于真理"],["正定","通过禅定使心专一"]],"mem":"口诀“**见思语业命，进念定**”：先想对（见、思），再说对做对活对（语、业、命），最后修心（进、念、定）。分组数字 2+3+3：慧2、戒3、定3。","mix":"八正道是道谛的内容，不是四谛之外的教义；大乘的“六度”（布施、持戒、忍辱、精进、禅定、智慧）是另一套。","mcq":[{"q":"下列不属于八正道的是","o":["正语","正念","正命","正信"],"a":3,"w":"八正道为正见、正思维、正语、正业、正命、正精进、正念、正定，没有“正信”。"},{"q":"八正道是四谛中哪一谛的具体内容","o":["灭谛","道谛","集谛","苦谛"],"a":1,"w":"道谛指解脱之道，即八正道。"}],"rel":[{"t":"四谛","n":"道谛的内容"},{"t":"戒定慧三学","n":"八正道可归入三学"},{"t":"中道","n":"不苦不乐的修行路线"},{"t":"六度（六波罗蜜）","n":"大乘的另一套修行法"}],"exam":[]},{"id":"a02-002","t":"戒定慧三学","cid":"02a","p":2,"kind":"合称","alias":["三学","戒定慧"],"one":"戒学、定学、慧学，佛教修行的三个层次。","ans":"戒定慧三学是佛教概括**修行体系**的三个方面，即**戒学、定学、慧学**。“戒”指持守戒律，防止身口意的过错；“定”指通过禅定使内心专注安定；“慧”指在定的基础上生起的**智慧**，能洞见诸法无常无我的真相。三者层层递进，由戒生定，由定发慧，最终指向**解脱与涅槃**。三藏中的律藏、经藏、论藏大体对应戒、定、慧。","pts":["戒学、定学、慧学","由戒生定，由定发慧","指向解脱，大体对应律、经、论"],"members":[["戒","持守戒律，止恶行善"],["定","禅定，专注安定"],["慧","智慧，洞见真相"]],"mem":"逻辑线记：先守规矩（戒），心才静得下来（定），静下来才看得清（慧）。三学与八正道对应：正语、正业、正命属戒，正精进、正念、正定属定，正见、正思维属慧。","mix":"三学（戒定慧）与三宝（佛法僧）、三藏（经律论）容易混；常见说法是律藏重戒、经藏重定、论藏重慧。","mcq":[{"q":"佛教“三学”指的是","o":["佛、法、僧","戒、定、慧","经、律、论","贪、嗔、痴"],"a":1,"w":"三学为戒、定、慧；贪嗔痴是“三毒”。"}],"rel":[{"t":"三宝","n":"另一组佛教三合称"},{"t":"涅槃","n":"修行最终目标"},{"t":"佛教基本教义","n":"八正道归入三学"}],"exam":[]},{"id":"a02-003","t":"涅槃","cid":"02a","p":2,"kind":"概念","alias":["泥洹","圆寂","寂灭","涅槃寂静"],"one":"熄灭烦恼、超越生死轮回的境界，佛教修行的最高目标。","ans":"涅槃是梵语nirvana的音译，意为“熄灭”，指**熄灭贪、嗔、痴等烦恼**、超越生死轮回的境界，是**佛教修行的最高目标**，也是三法印中“涅槃寂静”所指。涅槃并不等于死亡：觉悟者在世时可得涅槃，称“有余涅槃”，去世后彻底不再轮回，称“无余涅槃”。后世也用“涅槃”“圆寂”指高僧去世。释迦牟尼在拘尸那迦入灭，即被称为入涅槃。","pts":["意为熄灭，灭除贪嗔痴烦恼","超越生死轮回，修行最高目标","不等于死亡，有余与无余涅槃"],"mem":"一个画面：火被吹灭了。烦恼之火熄灭，人就从轮回里解脱。常见误解是把涅槃当死亡，其实活着也能证得，死后才是“无余”。","mix":"涅槃常被误解为死亡；“圆寂”是僧人去世的敬称，与涅槃相关但不同义。“涅槃”也有“灭度”“泥洹”等旧译。","mcq":[{"q":"关于佛教“涅槃”，下列说法正确的是","o":["仅指人死亡","熄灭烦恼、超脱轮回的境界","天上的极乐世界","祭祀亡灵的仪式"],"a":1,"w":"涅槃意为熄灭，指灭除烦恼、超越轮回的最高境界。"}],"rel":[{"t":"三法印","n":"涅槃寂静是其一"},{"t":"缘起与业报轮回","n":"涅槃即脱离轮回"},{"t":"戒定慧三学","n":"修行通向涅槃"}],"exam":[]},{"id":"a02-004","t":"缘起与业报轮回","cid":"02a","p":3,"kind":"概念","alias":["缘起论","因果报应","六道轮回","业力说"],"one":"佛教核心理论基石，主张万物因缘和合而生及依业受报流转六道。","ans":"缘起与业报轮回是**佛教核心理论基石**。缘起论主张万法由**因缘和合**而生，诸法无自性；业报论主张众生因善恶行为积累**业力**，决定在**六道中受报流转**。二者共同构成了佛教解释生命现象与指导止恶行善、求求解脱的学说基础。","pts":["佛教核心理论与世界观","因缘和合生万法与诸法无自性","善恶业力决定六道生死轮回"],"mem":"通行口诀：“**缘起说因果，业报定六道**”；事出有因是缘起，自作自受是业报。","mix":"缘起论主张“诸法无我”，反对外道神创论；业报轮回强调自身行为负责，非宿命论。","mcq":[{"q":"佛教解释世界万物生成与生命流转规律的核心理论是","o":["缘起与业报轮回","天人感应与五行相生","代赎与末日审判","道法自然与无为而治"],"a":0,"w":"佛教以因缘和合的缘起论与善恶业报流转六道的业报论为核心理论基石。"}],"rel":[{"t":"三法印","n":"佛教义理基石"},{"t":"释迦牟尼","n":"理论创立者"},{"t":"婆罗门教","n":"批判改造其轮回说"}],"exam":[]},{"id":"a02-005","t":"六度（六波罗蜜）","cid":"02a","p":3,"kind":"合称","alias":["六波罗蜜","六度","六波罗蜜多"],"one":"大乘佛教菩萨由生死苦海渡达涅槃彼岸的六种根本修行法门。","ans":"六度又称六波罗蜜，是大乘佛教**菩萨修行的根本行持**。“度”意为到彼岸，指**布施、持戒、忍辱、精进、禅定、般若**六种法门，以般若智慧为前导。大乘以此普度众生，是区别于小乘自度、成就**佛果与涅槃彼岸**的必由途径。","pts":["大乘菩萨由生死渡达涅槃的六法门","布施、持戒、忍辱、精进、禅定、般若","以般若智慧为诸度之统摄前导"],"members":[["布施","檀那，分财施、法施、无畏施"],["持戒","尸罗，遵守戒律防非止恶"],["忍辱","羼提，忍受苦难折磨心不动摇"],["精进","毗梨耶，勇猛向前精修善法"],["禅定","禅那，心注一境静虑澄明"],["般若","波若，照见诸法实相的终极智慧"]],"mem":"首字顺口溜：“**施戒忍精禅般**”；“波罗蜜”是梵文音译，意思是“到彼岸”。","mix":"六度中前五度为福德资粮，第六度“般若”为智慧资粮，所谓“五度如盲，般若为导”。","mcq":[{"q":"在大乘佛教“六度”修行中，被视为诸度之先导、照见实相的根本智慧是","o":["禅定","般若","忍辱","持戒"],"a":1,"w":"般若意为终极智慧，是大乘六度之首导与核心。"}],"rel":[{"t":"大乘佛教","n":"大乘菩萨道修行法门"},{"t":"涅槃","n":"六度修行所达彼岸"},{"t":"八正道","n":"原始佛教解脱之道"}],"exam":[]},{"id":"a02-006","t":"三毒","cid":"02a","p":3,"kind":"合称","alias":["贪嗔痴","三不善根","三垢"],"one":"佛教指贪、嗔、痴三种残害身心、引生一切烦恼恶业的根本毒素。","ans":"三毒是佛教所指**贪、嗔、痴**三种根本烦恼，又称“三不善根”。贪为贪欲占有，嗔为怨怒仇视，痴为愚昧无知。三毒毒害众生慧命，是一切**恶业与苦果之根源**，佛教主张以**戒定慧三学**对治此三毒以获解脱。","pts":["佛教指贪、嗔、痴三种根本烦恼","毒害善心慧命并引生一切轮回苦果","佛教以戒定慧三学分别对治"],"members":[["贪","对顺境顺物引生贪婪爱恋与无厌占有"],["嗔","对逆境逆缘引生嗔恚愤怒与怨恨厌恶"],["痴","对真实事理愚昧无明、颠倒妄见"]],"mem":"通行称谓“**贪嗔痴**”；对应“戒定慧”三学分别对治：**戒克贪、定伏嗔、慧破痴**。","mix":"痴指“无明”，即不明因果因缘之理，是一切烦恼的源头，并非单纯指智力低下。","mcq":[{"q":"佛教认为毒害众生善心、引生一切恶业的“三毒”是指","o":["生、老、病","苦、集、灭","贪、嗔、痴","断、见、思"],"a":2,"w":"三毒即贪欲、嗔恚、愚痴三种根本烦恼。"}],"rel":[{"t":"佛教基本教义","n":"断除烦恼的理论指向"},{"t":"涅槃","n":"熄灭三毒之寂灭境界"}],"exam":[]},{"id":"a02-007","t":"四大皆空","cid":"02a","p":3,"kind":"合称","alias":["四大","四大本空"],"one":"佛教指构成物质世界的地、水、火、风四种元素皆无实体自性。","ans":"四大皆空是**佛教物质观与空宗要义**。“四大”指构成一切物质形态的**地、水、火、风**四种元素，分别具坚、湿、暖、动四性。佛教认为世间万物皆为四大假合而成，**本质虚妄无独立自性**，破除执着方能悟入般若性空境界。","pts":["佛教指构成物质的地、水、火、风四大元素","万物皆由四大因缘假合生成","本质无独立恒常自性，破除人法二执"],"members":[["地大","性坚，支持万物，如骨肉毛发"],["水大","性湿，摄聚万物，如血液涕泪"],["火大","性暖，成熟万物，如体温热气"],["风大","性动，生长万物，如呼吸行动"]],"mem":"口诀：“**地水火风是四大，因缘和合本是空**”；民间常误作酒色财气，切记佛教所指是物质元素。","mix":"佛教“四大”指“地水火风”四大物质要素；俗语戏指的“酒、色、财、气”并非佛教四大。","mcq":[{"q":"佛教用语“四大皆空”中构成世间物质的“四大”是指","o":["金、木、水、火","酒、色、财、气","天、地、日、月","地、水、火、风"],"a":3,"w":"佛教四大指地、水、火、风四种构成色法的物质元素。"}],"rel":[{"t":"三法印","n":"诸行无常性空之体现"},{"t":"《心经》","n":"色不异空、色即是空"}],"exam":[]},{"id":"a02-008","t":"佛陀十大弟子","cid":"02a","p":3,"kind":"合称","alias":["释迦牟尼十大弟子","十大弟子"],"one":"释迦牟尼佛说法传教时期各有卓越特长的十位杰出常随侍从弟子。","ans":"佛陀十大弟子是**释迦牟尼常随侍从弟子**中的十位杰出代表。包括**舍利弗（智慧第一）**、目犍连（神通）、摩诃迦叶（头陀）、**阿难（多闻）**、须菩提（解空）等。十人各有专长，在**弘法传教与早期经典结集**中发挥了不可替代的历史奠基作用。","pts":["释迦牟尼僧团中十位特长卓著的代表弟子","舍利弗智慧、阿难多闻、目犍连神通等各擅胜场","佛灭后在经律结集与佛法传承中起核心作用"],"members":[["舍利弗","智慧第一，早期教团辅佐首领，先于佛入灭"],["目犍连","神通第一，尝入地狱救母，目连救母之原型"],["摩诃迦叶","头陀第一，佛灭后主持王舍城第一次经典结集"],["阿难","多闻第一，佛之堂弟兼常随侍者，诵出经藏"],["须菩提","解空第一，般若经典对话主要应机者"],["富楼那","说法第一，辩才无碍，热忱布教"],["迦旃延","论议第一，善于分别法相、辩明法理"],["阿那律","天眼第一，双目失明而证得天眼通"],["优波离","持戒第一，第一次结集中诵出律藏"],["罗睺罗","密行第一，释迦牟尼成道前出家之子"]],"mem":"巧记称号：“**迦叶头陀阿难闻，舍利智慧目连神，空推菩提戒波离**”。","mix":"摩诃迦叶主持第一次集结（头陀第一），阿难负责诵出经藏（多闻第一），优波离负责诵出律藏（持戒第一）。","mcq":[{"q":"在佛陀十大弟子中，长于博闻强记、在第一次佛经结集中诵出经藏的是","o":["阿难","优波离","舍利弗","摩诃迦叶"],"a":0,"w":"阿难为“多闻第一”，佛灭后第一次结集时诵出佛陀所说经藏。"}],"rel":[{"t":"释迦牟尼","n":"师从世尊"},{"t":"大藏经","n":"弟子结集诵出经律"}],"exam":[]},{"id":"a02-009","t":"佛教四大圣地","cid":"02b","p":2,"kind":"合称","alias":["四大圣地","佛教圣地"],"one":"蓝毗尼、菩提伽耶、鹿野苑、拘尸那迦，对应佛陀生平四事。","ans":"佛教四大圣地是与释迦牟尼生平密切相关的四处遗迹，即**蓝毗尼、菩提伽耶、鹿野苑、拘尸那迦**。蓝毗尼是**诞生**地，今属尼泊尔；菩提伽耶是菩提树下**成道**处；鹿野苑是**初转法轮**之处；拘尸那迦是**涅槃**之地，均在印度。这四处被佛教徒视为朝圣中心，法显、玄奘西行求法时都曾巡礼，其记述成为研究古印度的重要史料。","pts":["蓝毗尼、菩提伽耶、鹿野苑、拘尸那迦","诞生、成道、初转法轮、涅槃","法显、玄奘都曾巡礼"],"members":[["蓝毗尼","佛陀诞生地，今属尼泊尔"],["菩提伽耶","菩提树下成道"],["鹿野苑","初转法轮，说四谛"],["拘尸那迦","佛陀涅槃处"]],"mem":"按生平顺序“生、成、转、灭”：蓝毗尼生，菩提伽耶成，鹿野苑转法轮，拘尸那迦灭。首字串联“蓝菩鹿拘”，想成“蓝菩萨抱着鹿”也行。","mix":"蓝毗尼在尼泊尔，其余三处在印度；那烂陀寺是古代佛教学府，不在四大圣地之列。","mcq":[{"q":"佛教四大圣地中，释迦牟尼初转法轮之处是","o":["蓝毗尼","菩提伽耶","拘尸那迦","鹿野苑"],"a":3,"w":"鹿野苑是初转法轮处；蓝毗尼诞生，菩提伽耶成道，拘尸那迦涅槃。"}],"rel":[{"t":"释迦牟尼","n":"生平四节点"},{"t":"那烂陀寺","n":"印度佛学中心，易混"},{"t":"玄奘","n":"西行曾巡礼"}],"exam":[]},{"id":"a02-010","t":"佛教三大语系","cid":"02b","p":2,"kind":"合称","alias":["三大语系","佛教三大传承"],"one":"汉语系（汉传）、藏语系（藏传）、巴利语系（南传）。","ans":"佛教三大语系指**汉语系、藏语系、巴利语系**，按经典使用的语言和传播路线划分。**汉语系佛教**经北方丝绸之路传入中国内地，再传朝鲜、日本、越南，即汉传佛教；**藏语系佛教**于7世纪传入西藏，流行于藏、蒙古等地，即藏传佛教；**巴利语系佛教**向南传入斯里兰卡和东南亚，即南传佛教。三者共同构成当今世界佛教的格局。","pts":["汉语系、藏语系、巴利语系","汉传、藏传、南传","分别对应北传内地、西藏、南传东南亚"],"members":[["汉语系","汉传佛教，大乘为主，传中国内地、日韩越"],["藏语系","藏传佛教，7世纪传入西藏"],["巴利语系","南传上座部，传斯里兰卡与东南亚"]],"mem":"方向与语言配对：向北传的用汉语、藏语，向南传的用巴利语。三个传承名“汉、藏、南”，对应三种语言“汉语、藏语、巴利语”。","mix":"汉传、藏传都以大乘为主，藏传带有浓厚密教色彩；南传是上座部。“北传”有时合指汉传和藏传。","mcq":[{"q":"下列佛教语系与传承的对应，正确的是","o":["巴利语系：藏传佛教","藏语系：南传佛教","汉语系：藏传佛教","巴利语系：南传佛教"],"a":3,"w":"巴利语系即南传上座部佛教。"}],"rel":[{"t":"汉传佛教","n":"汉语系"},{"t":"藏传佛教","n":"藏语系"},{"t":"南传佛教","n":"巴利语系"}],"exam":[]},{"id":"a02-011","t":"阿育王","cid":"02b","p":2,"kind":"人物","alias":["阿输迦","无忧王"],"one":"孔雀王朝国王，皈依佛教，派僧人四出传教。","ans":"阿育王是**古印度孔雀王朝**第三代国王，约公元前3世纪在位，统一了印度大部分地区。他在**羯陵伽战争**后深感杀戮之苦，转而皈依佛教，以“**法**”治国，在各地刻立**石柱法敕**，并支持举行第三次结集。他派僧人到各地和邻国弘法，其子**摩哂陀**把佛教传入**斯里兰卡**，使佛教从地方宗教发展为世界性宗教，他因此被称为第一位大力推广佛教的君主。","pts":["孔雀王朝国王，前3世纪在位","羯陵伽战争后皈依佛教","派僧人四出传教，佛教走向世界"],"mem":"一个故事：战争打赢了，看到尸横遍野，国王醒悟，改刀兵为佛法。“无忧王”是汉译别名。记住“孔雀王朝＋羯陵伽战争＋石柱＋传到斯里兰卡”四个关键词。","mix":"阿育王是印度的君主，与中国的汉明帝（永平求法）、梁武帝等“佞佛”皇帝不同；他的佛教传播路线是向南传到斯里兰卡，奠定了南传佛教的基础。","mcq":[{"q":"古印度孔雀王朝的哪位国王皈依佛教，并派僧人到各地传教","o":["旃陀罗笈多","迦腻色迦","阿育王","戒日王"],"a":2,"w":"阿育王在羯陵伽战争后皈依佛教，大力弘法；迦腻色迦属贵霜王朝。"}],"rel":[{"t":"南传佛教","n":"其子传入斯里兰卡"},{"t":"释迦牟尼","n":"所弘扬的佛教创始人"},{"t":"印度河文明","n":"印度古代史背景"}],"exam":[]},{"id":"a02-012","t":"那烂陀寺","cid":"02b","p":3,"kind":"地理","alias":["那烂陀","那兰陀寺"],"one":"古印度著名佛教寺院与最高学府，玄奘西行求法修习唯识之圣地。","ans":"那烂陀寺是**古印度最高佛教学府与寺院遗址**，位于今印度比哈尔邦。盛期汇聚万名学者，大乘佛学尤盛。唐代高僧**玄奘在此师从戒贤**深造《瑜伽师地论》，义净亦曾留居。12世纪毁于战火，是**古代中印文化交流的巅峰历史象征**。","pts":["古印度最高佛教学府与学术中心","唐玄奘西行求法在此师从戒贤修习唯识","中印古代佛教文化交流的重要地理枢纽"],"mem":"谐音记忆：“**那烂陀里求戒贤，玄奘唯识传大唐**”。","mix":"玄奘在那烂陀寺师从戒贤法师，研习的是大乘瑜伽唯识学派，非中观派或小乘部派。","mcq":[{"q":"唐代玄奘西行印度求法的最高学府、师从戒贤法师研习唯识理论的寺院是","o":["鹿野苑","白马寺","那烂陀寺","大慈恩寺"],"a":2,"w":"那烂陀寺为古印度规模最大的佛教最高学府，玄奘在此研习五年。"}],"rel":[{"t":"玄奘","n":"玄奘在此求法师从戒贤"},{"t":"法相宗（唯识宗）","n":"玄奘在此修习唯识回国创宗"},{"t":"义净与《南海寄归内法传》","n":"义净亦曾留学那烂陀寺"}],"exam":[]},{"id":"a02-013","t":"达赖与班禅（活佛转世与金瓶掣签）","cid":"02b","p":2,"kind":"制度","alias":["达赖喇嘛","班禅额尔德尼","金瓶掣签","活佛转世","班禅"],"one":"格鲁派两大活佛系统，清中央册封并以金瓶掣签认定转世。","ans":"达赖与班禅是藏传佛教**格鲁派的两大活佛转世系统**。**1653年**顺治帝册封五世达赖喇嘛，**1713年**康熙帝册封五世班禅为“班禅额尔德尼”，确立了历代达赖、班禅必须经中央政府册封的制度。**1793年**乾隆时颁布《钦定藏内善后章程》，规定大活佛转世灵童须经**金瓶掣签**认定，并报中央批准。这一制度强化了中央对西藏宗教事务的管理，体现了历代中央政府对西藏的主权。","pts":["格鲁派两大活佛转世系统","1653年封五世达赖，1713年封五世班禅","1793年金瓶掣签，中央批准"],"mem":"三个年份连成线：1653（顺治封达赖）、1713（康熙封班禅）、1793（乾隆定金瓶掣签）。顺、康、乾三帝依次排列，间隔约60年、80年，记“五三、一三、九三”。","mix":"册封五世达赖的是顺治，册封五世班禅的是康熙；金瓶掣签是乾隆时期的《钦定藏内善后章程》。元代八思巴封帝师是更早的事，不要混用。","mcq":[{"q":"下列关于金瓶掣签的表述，正确的是","o":["康熙帝制定，用于册封五世班禅","顺治帝册封五世达赖时确立","1793年《钦定藏内善后章程》确立","元代八思巴时期创立"],"a":2,"w":"金瓶掣签由乾隆时期1793年《钦定藏内善后章程》确立。"}],"rel":[{"t":"藏传佛教","n":"所属宗教体系"},{"t":"宗喀巴与格鲁派","n":"两大系统所属教派"},{"t":"康熙帝","n":"册封五世班禅"}],"more":"1653年：顺治册封五世达赖阿旺罗桑嘉措。\n1713年：康熙册封五世班禅罗桑益西为“班禅额尔德尼”。\n1793年：乾隆《钦定藏内善后章程》，金瓶掣签。","exam":[]},{"id":"a02-014","t":"宗喀巴与格鲁派","cid":"02b","p":2,"kind":"人物","alias":["宗喀巴","格鲁派","黄教","罗桑扎巴"],"one":"明初藏传佛教改革者，创格鲁派，俗称黄教。","ans":"宗喀巴（1357–1419）出生于今青海湟中，是**明初藏传佛教改革家**，**格鲁派**创始人。他针对当时僧团戒律松弛的弊病，倡导**严守戒律、先显后密**，1409年在拉萨创建**甘丹寺**，著有《菩提道次第广论》。格鲁派僧人戴黄色僧帽，故俗称**黄教**。宗喀巴死后，其弟子逐步形成**达赖、班禅**两大转世系统，格鲁派成为藏传佛教影响最大的教派。","pts":["明初宗教改革家，青海湟中人","创格鲁派，俗称黄教，建甘丹寺","弟子形成达赖、班禅系统"],"mem":"“格鲁”意为“善规”，改革的重点就是严格戒律。画面：戴黄帽的僧人。四大派“宁萨噶格”里，格鲁最后出现，也最强盛。","mix":"黄教是格鲁派，红教常指宁玛派，白教指噶举派，花教指萨迦派；宗喀巴在明初，不要与元代八思巴混淆。","mcq":[{"q":"藏传佛教格鲁派（黄教）的创始人是","o":["八思巴","莲花生","宗喀巴","松赞干布"],"a":2,"w":"宗喀巴是明初格鲁派创始人，八思巴为元代萨迦派高僧。"}],"rel":[{"t":"藏传佛教四大派","n":"格鲁为其一"},{"t":"达赖与班禅（活佛转世与金瓶掣签）","n":"格鲁派两大系统"},{"t":"藏传佛教","n":"所属体系"}],"more":"主要著作：《菩提道次第广论》《密宗道次第广论》。\n1409年建甘丹寺，后世又有哲蚌寺、色拉寺并称三大寺。","exam":[]},{"id":"a02-015","t":"藏传佛教四大派","cid":"02b","p":3,"kind":"合称","alias":["藏传四大派","西藏四大教派"],"one":"藏传佛教发展中形成并传承至今的宁玛、萨迦、噶举、格鲁四大派别。","ans":"藏传佛教四大派是**藏传佛教四大主流宗派**。包括**宁玛派（红教）**、**萨迦派（花教）**、**噶举派（白教）**与**格鲁派（黄教）**。格鲁派由宗喀巴改革后创立，发展出达赖与班禅两大转世体系，成为近代影响最广的宗派。","pts":["宁玛（红）、萨迦（花）、噶举（白）、格鲁（黄）","格鲁派由宗喀巴创立，达赖与班禅转世系统","构成藏传佛教多流派并存的传承格局"],"members":[["宁玛派（红教）","藏传佛教最古老教派，尊莲花生大士为祖师，重密宗大圆满传承"],["萨迦派（花教）","因主寺墙涂红白蓝三色条纹得名，元代八思巴受封帝师执掌西藏"],["噶举派（白教）","早期僧侣穿白裙，强调密法口耳相传，支系众多"],["格鲁派（黄教）","宗喀巴创立并严明戒律，僧人戴黄色僧帽，达赖与班禅两大活佛系统出此派"]],"mem":"颜色与名称对应口诀：“**红宁玛、花萨迦、白噶举、黄格鲁**”，宗喀巴黄教最晚出。","mix":"萨迦派在元代掌政（八思巴封帝师），明清以来的达赖和班禅则出自宗喀巴创立的格鲁派（黄教）。","mcq":[{"q":"在藏传佛教四大派中，由宗喀巴创立、僧人戴黄色僧帽、形成达赖与班禅活佛转世系统的是","o":["宁玛派","萨迦派","噶举派","格鲁派"],"a":3,"w":"格鲁派俗称黄教，由宗喀巴于15世纪初改革创立。"}],"rel":[{"t":"藏传佛教","n":"四大派构成其主体格局"},{"t":"宗喀巴与格鲁派","n":"四大派中最晚出之主力"},{"t":"达赖与班禅（活佛转世与金瓶掣签）","n":"格鲁派确立的活佛制度"}],"exam":[]},{"id":"a02-016","t":"永平求法与《四十二章经》","cid":"02c","p":2,"kind":"事件","alias":["永平求法","汉明帝求法","白马驮经","四十二章经","《四十二章经》"],"one":"汉明帝永平年间遣使求法，建白马寺，相传译出《四十二章经》。","ans":"永平求法是**东汉明帝永平年间**官方遣使求取佛法的事件。相传明帝夜梦金人，派蔡愔、秦景等出使西域，在大月氏遇到印度僧人**迦叶摩腾、竺法兰**，以**白马驮经**同返洛阳，明帝在城西建**白马寺**安置。二僧在寺中译出**《四十二章经》**，被传为**最早的汉译佛经**。此事常被视为佛教正式传入中国的标志，但其中的传说成分，学界仍有讨论。","pts":["东汉明帝永平年间遣使求法","迦叶摩腾、竺法兰白马驮经，建白马寺","《四十二章经》相传为最早汉译佛经"],"mem":"一个故事连起来：明帝梦金人，派人西行，请回两位僧人，白马驮经到洛阳，建白马寺，译《四十二章经》。“四十二”可联想“一章一个要点”，短小精悍的小经。","mix":"这是官方标志，不是佛教传入的最早时间：佛教在两汉之际已沿丝绸之路传入，永平求法只是见于记载的官方事件。“最早汉译佛经”是传统说法，学界另有安世高译经等观点。","mcq":[{"q":"相传为最早汉译佛经的是","o":["《金刚经》","《法华经》","《四十二章经》","《阿弥陀经》"],"a":2,"w":"《四十二章经》相传由迦叶摩腾、竺法兰在洛阳译出。"}],"rel":[{"t":"白马寺","n":"为安置二僧而建"},{"t":"安世高、支谦","n":"东汉译经先驱"},{"t":"丝绸之路","n":"佛教入华通道"}],"exam":[]},{"id":"a02-017","t":"《大唐西域记》","cid":"02c","p":1,"kind":"作品","alias":["西域记","玄奘西域记"],"one":"玄奘口述、辩机笔录的西域与印度游记，646年成书。","ans":"《大唐西域记》是**唐代玄奘口述、弟子辩机笔录的地理游记**，共十二卷，**贞观二十年（646年）成书**。玄奘回国后奉唐太宗之命撰写，按行程记述他亲历的**110个国家和地区**及听闻的28国的地理、风俗、物产、宗教和历史传说，对佛教遗迹、寺院、那烂陀寺的记载尤为详细。它是研究**7世纪中亚、南亚历史地理**的重要文献，为近代考古确认鹿野苑、那烂陀寺等遗址提供了依据，也是《西游记》取经故事的史实来源。","pts":["玄奘口述，辩机笔录，646年成书","记110国亲历、28国传闻","研究中亚南亚史地的重要文献"],"mem":"数字记“**110加28**”，成书年是**646**：玄奘645年回到长安，第二年书成。三位求法僧三本书：法显《佛国记》、玄奘《大唐西域记》、义净《南海寄归内法传》。","mix":"署名常写“玄奘述，辩机撰”，别误成玄奘自撰；《佛国记》作者是东晋法显，《南海寄归内法传》作者是唐代义净。","mcq":[{"q":"《大唐西域记》的口述者与笔录者分别是","o":["玄奘、辩机","义净、玄奘","玄奘、窥基","法显、慧远"],"a":0,"w":"玄奘口述，弟子辩机笔录成书。"},{"q":"下列著作与作者对应正确的是","o":["《佛国记》—玄奘","《佛国记》—法显","《大唐西域记》—义净","《南海寄归内法传》—玄奘"],"a":1,"w":"《佛国记》是法显所著；《大唐西域记》属玄奘，《南海寄归内法传》属义净。"}],"rel":[{"t":"玄奘","n":"口述者"},{"t":"法显《佛国记》","n":"同类求法游记"},{"t":"义净与《南海寄归内法传》","n":"同类求法著作"},{"t":"那烂陀寺","n":"书中详记的佛学中心"},{"t":"丝绸之路","n":"记述的路线背景"}],"exam":[]},{"id":"a02-018","t":"朱士行","cid":"02c","p":2,"kind":"人物","alias":["朱士行西行","朱子行"],"one":"曹魏高僧，260年西行于阗求《放光般若经》，汉地西行求法第一人。","ans":"朱士行是**三国曹魏时期的高僧**，被认为是**汉地第一位西行求法的僧人**。他在洛阳讲《道行般若经》时感到译文残缺，于**甘露五年（260年）**从雍州出发西行，到达**于阗**，抄得《**放光般若经**》梵本九十章，派弟子送回洛阳，自己终老于于阗。《放光般若经》后经竺叔兰等译出，促进了般若学在中土的传播。他开启了此后法显、玄奘等人西行求法的先例。","pts":["曹魏高僧，汉地第一位西行求法者","260年到于阗求《放光般若经》","开西行求法之先"],"mem":"“朱”开头想“第一”：朱士行＝第一位西行，260年，终点于阗。顺序记人：朱士行（三国）→法显（东晋）→玄奘（唐）→义净（唐）。","mix":"朱士行西行只到于阗（今新疆和田），没有到天竺；法显、玄奘才到了印度。他与东汉安世高（译经）不同，是求法者。","mcq":[{"q":"被视为汉地第一位西行求法僧人的是","o":["法显","玄奘","朱士行","义净"],"a":2,"w":"朱士行260年西行至于阗求《放光般若经》，早于法显、玄奘。"}],"rel":[{"t":"法显《佛国记》","n":"后继的西行者"},{"t":"玄奘","n":"后继的西行者"},{"t":"西域","n":"其所到之地"}],"exam":[]},{"id":"a02-019","t":"义净与《南海寄归内法传》","cid":"02c","p":2,"kind":"人物","alias":["义净","南海寄归内法传","大唐西域求法高僧传"],"one":"唐代高僧，海路往返印度，著《南海寄归内法传》。","ans":"义净（635–713）是**唐代高僧**，与法显、玄奘并称西行求法三大家。他于**671年**从广州乘船，经**海路**到达印度，在那烂陀寺学习十余年，**695年**携梵本回洛阳，后译出佛经数十部。所著**《南海寄归内法传》**记述印度及南海诸国的佛教戒律与风俗，《**大唐西域求法高僧传**》为唐代西行高僧立传，是研究中外交通的重要史料。部分口径把他列入四大译经家。","pts":["唐代高僧，海路往返印度","著《南海寄归内法传》","另著《大唐西域求法高僧传》"],"mem":"三人路线对比：义净＝海路往返，玄奘＝陆路往返，法显＝陆去海回。书名《南海寄归内法传》里的“南海”“寄归”就是海路线索。","mix":"义净（海路往返，唐）与玄奘（陆路，唐）、法显（陆去海回，东晋）易混；四大译经家通行口径是鸠摩罗什、真谛、玄奘、不空，另一口径以义净代不空。","mcq":[{"q":"唐代高僧义净往返印度走的是","o":["陆路往返","海路往返","去时海路、回时陆路","去时陆路、回时海路"],"a":1,"w":"义净经海路往返，著《南海寄归内法传》。"}],"rel":[{"t":"玄奘","n":"同为唐代求法，走陆路"},{"t":"法显《佛国记》","n":"另一位著名求法者"},{"t":"那烂陀寺","n":"其留学之地"},{"t":"佛经四大翻译家","n":"另一口径的成员"}],"exam":[]},{"id":"a02-020","t":"鉴真东渡","cid":"02c","p":1,"kind":"事件","alias":["鉴真","鉴真和尚","东渡日本"],"one":"唐代律宗高僧鉴真六次东渡，753年抵日本，传律宗，建唐招提寺。","ans":"鉴真东渡是**唐代律宗高僧鉴真（688–763）应日本僧人邀请，六次东渡，终于在753年抵达日本**的事件。鉴真出身扬州，742年起应荣睿、普照之请赴日传戒，前五次因海难、官府阻拦失败，其间双目失明。抵日后他在东大寺设坛传戒，**759年建唐招提寺**，把**律宗**传入日本，被尊为日本律宗初祖。他还带去佛经、医药知识和建筑雕塑技艺，对日本佛教、医药、建筑影响深远。","pts":["律宗高僧，六次东渡，753年抵日","建唐招提寺，传律宗","不是翻译家，2026选择答案"],"mem":"“**六次东渡，七五三抵日**”：六次、753。对称记法：玄奘西行（645回长安），鉴真东渡（753到日本）。画面是失明的老僧第六次踏上日本的土地。","mix":"鉴真不是佛经翻译家，是2026年选择题“哪个不是四大翻译家”的答案；他东渡日本，玄奘西行印度，方向相反。","mcq":[{"q":"下列人物中，不属于佛经翻译家的是","o":["真谛","鉴真","鸠摩罗什","玄奘"],"a":1,"w":"鉴真是律宗高僧，东渡传律，不是翻译家。"},{"q":"鉴真第六次东渡抵达日本的年份是","o":["759年","742年","748年","753年"],"a":3,"w":"742年应邀，748年第五次失败，753年抵达，759年建唐招提寺。"}],"rel":[{"t":"律宗","n":"鉴真传至日本的宗派"},{"t":"玄奘","n":"西行对东渡"},{"t":"佛经四大翻译家","n":"鉴真不在其列"},{"t":"海上丝绸之路","n":"东渡的海路背景"}],"exam":[]},{"id":"a02-021","t":"三武一宗灭佛","cid":"02c","p":2,"kind":"合称","alias":["三武一宗","四次灭佛","会昌灭佛","会昌法难"],"one":"北魏太武帝、北周武帝、唐武宗、后周世宗的四次灭佛。","ans":"三武一宗灭佛指中国历史上**四次大规模禁毁佛教**的事件，即**北魏太武帝、北周武帝、唐武宗、后周世宗**。太武帝在446年灭佛；周武帝在574年灭佛道二教；**唐武宗会昌五年（845年）**毁寺还俗，史称“会昌法难”；后周世宗在955年毁寺铸钱。灭佛的原因多与寺院占有大量土地、人口，影响国家赋税兵役有关，其中会昌法难对佛教打击最重，但佛教此后仍继续发展。","pts":["北魏太武帝、北周武帝、唐武宗、后周世宗","会昌法难（845）影响最大","原因：寺院经济冲击国家赋税"],"members":[["北魏太武帝","446年，第一次灭佛"],["北周武帝","574年，佛道并禁"],["唐武宗","845年，会昌灭佛"],["后周世宗","955年，毁寺铸钱"]],"mem":"“三武一宗”：三位谥号或庙号带“武”的皇帝（北魏太武帝、北周武帝为谥号，唐武宗为庙号）加一位“宗”（后周世宗，庙号）。时间顺序是北魏→北周→唐→后周，约相隔一百多年一次。","mix":"三武一宗灭佛的第三位是唐武宗，不是唐太宗；还有“佞佛”的梁武帝，与“灭佛”的几位皇帝正好相反。","mcq":[{"q":"下列君主中，属于“三武一宗”灭佛的是","o":["梁武帝","汉武帝","唐武宗","隋文帝"],"a":2,"w":"三武一宗为北魏太武帝、北周武帝、唐武宗、后周世宗。"}],"rel":[{"t":"汉传佛教","n":"受其冲击"},{"t":"禅宗","n":"会昌后更盛行"},{"t":"安史之乱","n":"唐代寺院经济背景"}],"exam":[]},{"id":"a02-022","t":"真谛","cid":"02d","p":2,"kind":"人物","alias":["拘那罗陀","波罗末陀","Paramartha"],"one":"南朝译经家，西天竺人，译《摄大乘论》《俱舍论》，四大译家之一。","ans":"真谛（499–569）梵名**拘那罗陀**，是**西天竺优禅尼国人**，南朝梁时来华，是**佛经四大翻译家之一**。他在梁、陈战乱中辗转岭南与江南，译出大量经论，主要有《**摄大乘论**》《**俱舍论**》《大乘起信论》（相传）等，共数十部。他译介的摄论学说，后来形成**摄论宗**，对唯识学在中国的传播有开创之功，也为玄奘的新译唯识学打下基础。","pts":["西天竺人，南朝梁时来华","译《摄大乘论》《俱舍论》","四大译家之一，开唯识学传译"],"mem":"四大译家按时间排：罗什（后秦）、真谛（梁陈）、玄奘（唐）、不空（唐），口诀“罗真玄不”。他的名字与佛教二谛之一“真谛”相同，看到“真谛”就想到《摄大乘论》。","mix":"真谛与佛教“真谛、俗谛”二谛同名，题干要看是人名还是教义；他是南朝人，不要写成唐人。卒年有569年等说法。","mcq":[{"q":"下列属于佛经四大翻译家，且译出《摄大乘论》《俱舍论》的是","o":["不空","真谛","义净","道安"],"a":1,"w":"真谛是南朝梁、陈时西天竺僧人，译《摄大乘论》《俱舍论》。"}],"rel":[{"t":"佛经四大翻译家","n":"所属合称"},{"t":"鸠摩罗什","n":"前一位译家"},{"t":"玄奘","n":"承其唯识学"}],"exam":[]},{"id":"a02-023","t":"不空","cid":"02d","p":2,"kind":"人物","alias":["不空金刚","不空三藏"],"one":"唐代密宗高僧，开元三大士之一，四大译经家之一。","ans":"不空（705–774）是**唐代密宗高僧**，相传出生于狮子国或北天竺，师从**金刚智**，与善无畏、金刚智并称**“开元三大士”**。他历经玄宗、肃宗、代宗三朝，受朝廷尊崇，在长安翻译了大量密教经典，如《金刚顶经》《仁王经》等一百余部，是**佛经四大翻译家之一**。有的口径以义净代不空。他使密宗在唐代达到兴盛，其教法后来传入日本，成为东密的来源之一。","pts":["唐代密宗高僧，师金刚智","开元三大士之一","四大译家之一，译密教经典"],"mem":"开元三大士口诀“善金不”：善无畏、金刚智、不空。四大译家“罗真玄不”：罗什、真谛、玄奘、不空。两个口诀里“不空”都排最后。","mix":"四大译家另一口径以义净代不空；开元三大士是善无畏、金刚智、不空，不含玄奘；不空与同名“空”的佛教概念不同。","mcq":[{"q":"下列属于唐代密宗“开元三大士”的是","o":["不空","玄奘","义净","鉴真"],"a":0,"w":"开元三大士是善无畏、金刚智、不空。"}],"rel":[{"t":"密宗","n":"所属宗派"},{"t":"佛经四大翻译家","n":"所属合称"},{"t":"玄奘","n":"同为唐代译家"}],"exam":[]},{"id":"a02-024","t":"支娄迦谶","cid":"02d","p":3,"kind":"人物","alias":["支谶","支楼迦谶"],"one":"东汉时期大月氏来华高僧，最早将大乘佛教般若经典译入汉地的翻译家。","ans":"支娄迦谶约2世纪在世，简称支谶，**东汉时期大月氏高僧**。他在洛阳译出**《道行般若经》**等经典，是**最早将大乘佛教典籍译入汉地**的翻译家。他与译小乘禅经的安世高并称，为汉魏两晋**般若思想与格义佛学**奠定了文献基础。","pts":["东汉末大月氏译经僧，简称支谶","最早将大乘佛教般若经典译入中国","与安世高并为东汉佛经翻译双璧"],"mem":"对比巧记：“**世高译小乘禅数，支谶译大乘般若**”；“支”字源于大月氏国名。","mix":"安世高来自安息国，主译小乘阿含与禅数经典；支娄迦谶来自大月氏，主译大乘般若类经典。","mcq":[{"q":"东汉末年在洛阳译出《道行般若经》，最早将大乘佛教般若思想系统介绍到中国的高僧是","o":["鸠摩罗什","安世高","支娄迦谶","竺法护"],"a":2,"w":"支娄迦谶为大月氏人，开创了汉地翻译大乘般若经典的先河。"}],"rel":[{"t":"大乘佛教","n":"汉译大乘经典先驱"},{"t":"鸠摩罗什","n":"早期译家与旧译大家承继"},{"t":"道安","n":"其译作被道安考订入录"}],"exam":[]},{"id":"a02-025","t":"竺法护","cid":"02d","p":3,"kind":"人物","alias":["敦煌菩萨","昙摩罗刹","支法护"],"one":"西晋著名译经大师，世居敦煌，译经百余部，世称“敦煌菩萨”。","ans":"竺法护（约239–316），梵名昙摩罗刹，**西晋时期著名译经大师**。世居敦煌，通晓多国西域语言，号称**“敦煌菩萨”**。他西行求法翻译出**《正法华经》《光赞般若经》**等百余部大乘典籍，为佛教在北方民间的普及与大乘思想传播立下殊勋。","pts":["西晋时期大译经家，世称“敦煌菩萨”","译出《正法华经》等百余部大乘佛典","为大乘佛教在北方的广泛传播奠基"],"mem":"记忆法：“**敦煌菩萨竺法护，西晋译经正法华**”。","mix":"竺法护所译为《正法华经》（西晋译本），后秦鸠摩罗什所译为《妙法莲华经》（通行本），两者同一梵本源流但译笔不同。","mcq":[{"q":"西晋时期通晓西域三十六国语言、译出《正法华经》等百余部经典，被尊称为“敦煌菩萨”的译经家是","o":["法显","支娄迦谶","道安","竺法护"],"a":3,"w":"竺法护世居敦煌，译经数量极丰，后世尊称为“敦煌菩萨”。"}],"rel":[{"t":"《法华经》","n":"首译《正法华经》"},{"t":"鸠摩罗什","n":"先后翻译法华经典"},{"t":"敦煌藏经洞","n":"敦煌早期佛教开拓者"}],"exam":[]},{"id":"a02-026","t":"竺道生","cid":"02d","p":2,"kind":"人物","alias":["道生","生公","生公说法"],"one":"鸠摩罗什弟子，倡“顿悟成佛”“一阐提人皆得成佛”。","ans":"竺道生（约355–434）是**东晋南朝高僧**，**鸠摩罗什的弟子**，为“**什门四圣**”之一。他提出**“顿悟成佛”**说，认为佛性不可分割，悟道不必逐级渐修；又倡**“一阐提人皆得成佛”**，即连断绝善根者也有佛性，因此一度被僧团驱逐，后来传入的《大般涅槃经》证明了他的见解。传说他在苏州虎丘讲经，“**生公说法，顽石点头**”。他的顿悟说为后来**禅宗**南宗的顿悟思想开启先河。","pts":["罗什弟子，什门四圣之一","顿悟成佛，一阐提人皆有佛性","“生公说法，顽石点头”"],"mem":"一个画面：虎丘山上，生公对着石头讲经，石头也点头。什门四圣口诀“肇生融叡”：僧肇、道生、道融、僧叡。","mix":"竺道生主张顿悟，与慧能“顿悟”相联系，但慧能是唐代禅宗，二者相隔三百年。什门四圣还有僧肇，写《肇论》。","mcq":[{"q":"提出“一阐提人皆得成佛”，且为什门四圣之一的是","o":["僧肇","道融","僧叡","竺道生"],"a":3,"w":"竺道生倡一阐提也能成佛和顿悟成佛。"}],"rel":[{"t":"什门四圣","n":"所属合称"},{"t":"鸠摩罗什","n":"其老师"},{"t":"慧能与《六祖坛经》","n":"顿悟思想的后继"}],"exam":[]},{"id":"a02-027","t":"《金刚经》","cid":"02d","p":2,"kind":"作品","alias":["《金刚般若波罗蜜经》","金刚般若经"],"one":"鸠摩罗什译的般若类佛经，禅宗重要经典，敦煌出土唐刻本是最早有纪年的印刷品。","ans":"《金刚经》全称《金刚般若波罗蜜经》，是**大乘佛教般若类经典**，宣讲“应无所住而生其心”，主张破除一切执着。通行本为**后秦鸠摩罗什所译**，属“旧译”代表作。禅宗六祖**慧能**听人诵此经而开悟，此后该经成为禅宗要典。敦煌藏经洞出土的**唐咸通九年（868年）刻本**，卷首有释迦说法图，现藏**大英图书馆**，是世界上现存最早有明确纪年的雕版印刷品。","pts":["鸠摩罗什译，大乘般若经典","慧能闻诵此经而开悟","敦煌唐咸通九年刻本，最早有纪年印刷品"],"mem":"两个记忆点串成一条线：罗什译经，慧能听经开悟，868年刻成书。年份记“868”，可联想“咸通”年号加一个“八六八”的顺口数字。印刷品这条线索可与《印刷术》词条一并记。","mix":"《心经》通行本是玄奘译，《金刚经》通行本是罗什译；玄奘也有《金刚经》译本，但流传不及罗什本。敦煌刻本现藏英国，不在国内。","mcq":[{"q":"世界上现存最早有明确纪年的雕版印刷品，是敦煌出土的唐咸通九年刻本","o":["《心经》","《法华经》","《坛经》","《金刚经》"],"a":3,"w":"唐咸通九年（868年）刻本《金刚经》，现藏大英图书馆。"}],"rel":[{"t":"鸠摩罗什","n":"通行本译者"},{"t":"《心经》","n":"同属般若经，译者不同"},{"t":"敦煌藏经洞","n":"唐刻本出土地"},{"t":"印刷术","n":"现存最早有纪年印刷品"},{"t":"慧能与《六祖坛经》","n":"闻经开悟"}],"more":"名句：一切有为法，如梦幻泡影，如露亦如电，应作如是观。\n应无所住而生其心。","exam":[]},{"id":"a02-028","t":"《心经》","cid":"02d","p":2,"kind":"作品","alias":["《般若波罗蜜多心经》","般若心经"],"one":"玄奘译，约260字，大乘般若经典中最短、流传最广的一部。","ans":"《心经》全称《般若波罗蜜多心经》，是**大乘佛教般若类经典的精要**，全文仅约**260字**，是佛经中篇幅最短、流传最广的一部。通行本为**唐代玄奘所译**，属“新译”。经中讲“**色不异空，空不异色，色即是空，空即是色**”，用空观说明五蕴皆空，以观自在菩萨（观音）为说法主体。该经为汉传各宗共诵，在日常诵读、抄经、书法中最为常见。","pts":["般若经典，约260字，最短","通行本为玄奘所译","色即是空，空即是色"],"mem":"“心”是核心提要的意思：把六百卷《大般若经》压缩成两百六十字。记忆口诀：玄奘译《心经》，罗什译《金刚经》，两位译家各管一本通行本。","mix":"鸠摩罗什也译过心经的异本，但通行本是玄奘本。《金刚经》通行本是罗什译，二者译者容易互换。","mcq":[{"q":"下列关于《心经》的说法，正确的是","o":["通行本为鸠摩罗什所译","全文约260字，篇幅短小","是净土宗专奉经典","因载有“应无所住而生其心”而闻名"],"a":1,"w":"《心经》通行本为玄奘译，约260字；“应无所住”出自《金刚经》。"}],"rel":[{"t":"玄奘","n":"通行本译者"},{"t":"《金刚经》","n":"同属般若经，常对举"},{"t":"佛经四大翻译家","n":"玄奘为四大之一"},{"t":"佛教基本教义","n":"空观与缘起"}],"more":"名句：色不异空，空不异色，色即是空，空即是色。｜《心经》","exam":[]},{"id":"a02-029","t":"《法华经》","cid":"02d","p":3,"kind":"作品","alias":["妙法莲华经","法华三部经"],"one":"大乘佛教核心经典，主张“会三归一、开权显实”，天台宗根本依据。","ans":"《法华经》全称《妙法莲华经》，是**大乘佛教的核心根本经典**。通行本由后秦**鸠摩罗什翻译**。该经以生动譬喻阐发**“开权显实、会三归一”**之理，倡导一切众生皆可成佛。它是隋代智顗**创立天台宗的根本依据**，在东亚文化圈流传极广。","pts":["大乘根本经典，通行本为鸠摩罗什所译","主张会三归一与一切众生皆成佛道","为中国天台宗立宗立教之根本经典"],"mem":"记忆法：“**罗什译妙法，天台立宗本**”；经中“火宅喻、化城喻”寓意会三乘归于一佛乘。","mix":"《正法华经》为西晋竺法护译本，文字较为古拙；通行全天下的版本为后秦鸠摩罗什译《妙法莲华经》。","mcq":[{"q":"提出“会三归一、开权显实”，成为中国天台宗依据根本经典的大乘佛经是","o":["《法华经》","《华严经》","《金刚经》","《维摩诘经》"],"a":0,"w":"《法华经》（《妙法莲华经》）为天台宗主要立教经典。"}],"rel":[{"t":"天台宗","n":"依据此经创宗"},{"t":"鸠摩罗什","n":"通行译本之翻译家"},{"t":"竺法护","n":"早先译有《正法华经》"}],"exam":[]},{"id":"a02-030","t":"汉传佛教八宗","cid":"02e","p":1,"kind":"合称","alias":["八宗","汉传八宗"],"one":"天台、三论、法相、华严、律、净土、禅、密，隋唐形成的八个宗派。","ans":"汉传佛教八宗指**隋唐时期形成的八个汉传佛教宗派：天台宗、三论宗、法相宗、华严宗、律宗、净土宗、禅宗、密宗**。其中**天台宗是最早的本土化宗派**，创始人智顗依据《法华经》；法相宗由玄奘、窥基创立，主“万法唯识”；华严宗以法藏为实际创始人，依《华严经》；律宗由道宣创立，鉴真传至日本；净土宗念阿弥陀佛求往生；**禅宗影响最大**；密宗以持咒仪轨为特色。八宗反映了佛教中国化的成熟。","pts":["隋唐形成的八个宗派","天台宗最早本土化","禅宗影响最大"],"members":[["天台宗","隋智顗，《法华经》，最早本土化"],["三论宗","隋吉藏，《中论》《百论》《十二门论》"],["法相宗（唯识宗）","玄奘、窥基，万法唯识"],["华严宗","法藏（贤首），《华严经》"],["律宗","道宣，研习戒律"],["净土宗","慧远、善导，念阿弥陀佛"],["禅宗","达摩、慧能，见性成佛"],["密宗","善无畏、金刚智、不空，持咒"]],"mem":"口诀“**天三法华，律净禅密**”：天台、三论、法相、华严、律、净土、禅、密。前四个偏义理，后四个偏实践。","mix":"也有把俱舍、成实等学派并列的更多宗说法；日本的真言宗、日莲宗不在汉传八宗之内。","mcq":[{"q":"下列属于汉传佛教八宗的是","o":["净土宗","格鲁派","真言宗","日莲宗"],"a":0,"w":"格鲁派属藏传，真言宗、日莲宗是日本宗派。"},{"q":"八宗中最早形成的本土化宗派是","o":["天台宗","禅宗","法相宗","华严宗"],"a":0,"w":"天台宗由隋代智顗创立，是最早的本土宗派。"}],"rel":[{"t":"天台宗","n":"最早本土宗派"},{"t":"法相宗（唯识宗）","n":"玄奘创立"},{"t":"华严宗","n":"法藏创立"},{"t":"净土宗","n":"念佛往生"},{"t":"禅宗","n":"影响最大"}],"exam":[]},{"id":"a02-031","t":"法相宗（唯识宗）","cid":"02e","p":2,"kind":"流派","alias":["法相宗","唯识宗","慈恩宗"],"one":"玄奘与弟子窥基创立，依《成唯识论》，主张万法唯识。","ans":"法相宗又称唯识宗、慈恩宗，是**唐代玄奘及其弟子窥基创立的汉传佛教宗派**。该宗以印度瑜伽行派学说为依据，以**《成唯识论》**为主要典籍，主张“**万法唯识**”，认为一切现象都由心识变现，并详细分析八识。窥基住大慈恩寺，故称慈恩宗。该宗义理繁复，传承不久便衰落，但其因明、唯识学对**后世佛学和哲学**影响深远，并传入日本。","pts":["玄奘、窥基创立","依《成唯识论》，万法唯识","义理繁复，传承较短"],"mem":"“法相”就是研究万法的相状，“唯识”是结论：一切唯有识。玄奘带回经论，弟子窥基整理成宗，因住大慈恩寺，又叫“慈恩宗”。","mix":"玄奘既是译家又是宗派创立者，与鸠摩罗什区别：罗什传三论，玄奘传唯识。窥基常被误当作玄奘本人。","mcq":[{"q":"玄奘与窥基创立的汉传宗派是","o":["法相宗","华严宗","天台宗","律宗"],"a":0,"w":"法相宗即唯识宗，依《成唯识论》。"}],"rel":[{"t":"玄奘","n":"创立者"},{"t":"汉传佛教八宗","n":"八宗之一"},{"t":"佛经四大翻译家","n":"玄奘为新译代表"},{"t":"《大唐西域记》","n":"玄奘西行记录"}],"exam":[]},{"id":"a02-032","t":"华严宗","cid":"02e","p":3,"kind":"流派","alias":["贤首宗","法界宗"],"one":"汉传佛教八大宗派之一，依《华严经》，主张“法界缘起”与圆融无碍。","ans":"华严宗又称贤首宗，是**汉传佛教八大宗派**之一。唐代杜顺开山，由三祖**法藏（贤首大师）实际创立**。该宗以《华严经》为核心依据，提出“四法界”与**“法界缘起”**学说，阐发事事无碍、一即一切的**圆融宇宙观**，体现了佛学中国化的高峰。","pts":["汉传佛教八宗之一，法藏实际创立，又称贤首宗","以《华严经》为宗经，倡导“法界缘起”说","提出事事无碍与圆融学说，为佛教中国化高峰"],"mem":"巧记：“**贤首法藏立华严，法界缘起事事融**”；华严宗讲“一即一切，一切即一”。","mix":"天台宗主讲“一念三千”与《法华经》；华严宗主讲“法界缘起”与《华严经》，二者并称汉传义学双璧。","mcq":[{"q":"以《华严经》为依据，提出“四法界”与“法界缘起”学说，由法藏实际创立的汉传佛教宗派是","o":["天台宗","三论宗","华严宗","法相宗"],"a":2,"w":"华严宗由唐代法藏（贤首）实际创立，主张法界缘起与圆融无碍。"}],"rel":[{"t":"汉传佛教八宗","n":"汉传八大宗派之一"},{"t":"天台宗","n":"中国化佛教教理双璧"},{"t":"缘起与业报轮回","n":"缘起学说的极致阐发"}],"exam":[]},{"id":"a02-033","t":"律宗","cid":"02e","p":2,"kind":"流派","alias":["南山律宗","南山宗"],"one":"唐代道宣创立，研习戒律，鉴真传至日本。","ans":"律宗是**以研习和传持戒律为中心的汉传佛教宗派**，由**唐代道宣**创立，因道宣住终南山，又称**南山律宗**。该宗依据**《四分律》**，主张严守戒律是修行的根本。唐代**鉴真**是律宗高僧，**六次东渡日本，753年抵达**，在日本建唐招提寺，传授戒律，使律宗在日本扎根。律宗奠定了中国佛教僧团受戒、守戒的制度基础。","pts":["唐道宣创立，南山律宗","依《四分律》，重戒律","鉴真传至日本"],"mem":"“律”就是戒律，名字已经说明主题。线索：道宣在终南山立宗，鉴真把它带过海，到日本建唐招提寺。","mix":"鉴真是律宗高僧，创立者是道宣；他也不是翻译家，2026届选择题曾把他放在干扰项里。","mcq":[{"q":"下列关于律宗的说法，正确的是","o":["由玄奘创立","高僧鉴真曾东渡传至日本","依《法华经》","是中国最早的本土宗派"],"a":1,"w":"律宗由道宣创立，鉴真六次东渡，把律宗传到日本。"}],"rel":[{"t":"鉴真东渡","n":"传律入日本"},{"t":"汉传佛教八宗","n":"八宗之一"},{"t":"天台宗","n":"最早本土宗派，对举"},{"t":"神道教","n":"日本本土宗教，对照"}],"exam":[]},{"id":"a02-034","t":"密宗","cid":"02e","p":2,"kind":"流派","alias":["密教","真言宗","唐密"],"one":"唐开元年间善无畏、金刚智、不空传入，重持咒和仪轨。","ans":"密宗又称密教、真言宗，是**以持咒、结印、观想等秘密仪轨为特色的佛教宗派**。**唐玄宗开元年间**，印度僧人**善无畏、金刚智、不空**先后来华译经传法，合称“**开元三大士**”，密宗由此在中国形成。三人中**不空**影响最大，被列为四大翻译家之一，译出大量密教经典。会昌灭佛后，汉地密宗渐趋衰落，但传入日本的真言宗流传至今。","pts":["以持咒、仪轨为特色","善无畏、金刚智、不空，开元三大士","不空为四大翻译家之一"],"members":[["善无畏","开元四年（716年）到长安，译《大日经》"],["金刚智","开元年间来华，传金刚界密法"],["不空","师从金刚智，四大翻译家之一"]],"mem":"三大士口诀：善、金、不（善无畏、金刚智、不空）。记得第三位“不空”最重要，因为他同时是四大翻译家之一，两处都能考。","mix":"开元三大士是来华印度僧人，不是中国人；四大翻译家的“不空”与三大士的“不空”是同一人。另一种口径用义净代替不空。","mcq":[{"q":"下列不属于“开元三大士”的是","o":["善无畏","金刚智","不空","义净"],"a":3,"w":"开元三大士是善无畏、金刚智、不空；义净是海路求法的高僧。"}],"rel":[{"t":"佛经四大翻译家","n":"不空同列其中"},{"t":"汉传佛教八宗","n":"八宗之一"},{"t":"义净与《南海寄归内法传》","n":"易混高僧"},{"t":"三武一宗灭佛","n":"灭佛使汉地密宗衰落"}],"exam":[]},{"id":"a02-035","t":"三论宗","cid":"02e","p":3,"kind":"流派","alias":["空宗","嘉祥宗","中观宗"],"one":"汉传佛教主要宗派之一，依印度中观三部论典，主张“八不中道”与破邪显正。","ans":"三论宗又称中观宗，是**汉传佛教重要宗派**。由隋代**吉藏（嘉祥大师）集大成并创立**。该宗以鸠摩罗什所译龙树《中论》《十二门论》与提婆《百论》为根本依据，主张**“八不中道”**与“破邪显正”，破除一切边见执着，**继承印度大乘中观空宗思想**。","pts":["隋代吉藏创立，承袭印度大乘中观学派","依据鸠摩罗什所译《中论》《百论》《十二门论》","主张“八不中道”与“破邪显正”之般若性空"],"mem":"记忆法：“**中论、百论、十二门，吉藏立起三论宗**”；八不中道：“不生不灭、不断不常”。","mix":"三论宗所依“三论”是《中论》《百论》《十二门论》；若加上《大智度论》则称为“四论宗”。","mcq":[{"q":"汉传佛教“三论宗”依据的三部中观论典是《中论》《十二门论》与","o":["《十住毗婆沙论》","《摄大乘论》","《成唯识论》","《百论》"],"a":3,"w":"三论宗依据龙树《中论》《十二门论》与提婆《百论》立宗。"}],"rel":[{"t":"鸠摩罗什","n":"翻译所依据的三论"},{"t":"汉传佛教八宗","n":"汉传宗派重要流派"},{"t":"中道","n":"核心义理八不中道"}],"exam":[]},{"id":"a02-036","t":"禅宗六祖","cid":"02e","p":2,"kind":"合称","alias":["禅宗六代祖师","初祖至六祖"],"one":"达摩、慧可、僧璨、道信、弘忍、慧能，禅宗在中国的六代祖师。","ans":"禅宗六祖指**禅宗在中国传承的六代祖师**，依次是**达摩、慧可、僧璨、道信、弘忍、慧能**。**达摩**自天竺来华，为初祖，在嵩山少林寺面壁，慧可立雪断臂求法；**弘忍**在湖北黄梅传法，因神秀、慧能的偈子，将衣钵传给**慧能**。慧能居岭南，主张顿悟，开创南宗，其言行由弟子辑为**《六祖坛经》**。此后禅宗不再传衣，分出五家七宗。","pts":["达摩、慧可、僧璨、道信、弘忍、慧能","达摩为初祖，慧能为六祖","五祖弘忍传衣钵给慧能"],"members":[["初祖达摩","天竺来华，少林寺面壁"],["二祖慧可","立雪断臂，从达摩受法"],["三祖僧璨","传法于道信"],["四祖道信","在黄梅传法"],["五祖弘忍","黄梅东山，传衣钵于慧能"],["六祖慧能","南宗开创者，《六祖坛经》"]],"mem":"首字口诀：达慧僧道弘慧，“达”想到达摩，“慧”想到慧可，两个“慧”首尾呼应：最前面的慧可，最后面的慧能。画面：达摩面壁，慧可立雪，弘忍黄梅夜传衣钵。","mix":"初祖达摩，六祖慧能，不要把慧可（二祖）与慧能（六祖）互换。神秀是北宗创始人，不在六祖之列。","mcq":[{"q":"禅宗五祖弘忍把衣钵传给了","o":["神秀","慧可","慧能","道信"],"a":2,"w":"弘忍传衣钵于慧能，慧能成为六祖，神秀另立北宗。"},{"q":"禅宗的初祖是","o":["慧能","达摩","弘忍","僧璨"],"a":1,"w":"达摩为禅宗初祖，慧能为六祖。"}],"rel":[{"t":"达摩","n":"初祖"},{"t":"慧能与《六祖坛经》","n":"六祖与典籍"},{"t":"少林寺","n":"达摩面壁处"},{"t":"禅宗五家七宗","n":"六祖之后的分派"}],"exam":[]},{"id":"a02-037","t":"神秀与南顿北渐","cid":"02e","p":1,"kind":"人物","alias":["神秀","南能北秀","南顿北渐","北宗"],"one":"神秀是禅宗北宗创始人，主渐修，与慧能合称“南能北秀”。","ans":"神秀（约606–706）是**禅宗五祖弘忍的弟子，北宗创始人**，主张**渐修**。他在湖北当阳玉泉寺传法，后被武则天迎入洛阳，受朝廷礼遇，号称“两京法主、三帝国师”，北宗在北方盛极一时。《坛经》记载神秀作偈“身是菩提树，心如明镜台，时时勤拂拭，勿使惹尘埃”，慧能和以“菩提本无树，明镜亦非台”，由此得弘忍衣钵。两派合称**“南能北秀”，修行方式称“南顿北渐”**，后北宗衰落，南宗成禅宗主流。","pts":["弘忍弟子，北宗创始人，主渐修","偈“身是菩提树，心如明镜台”","南能北秀，南顿北渐"],"mem":"“**能顿秀渐**”：慧能顿，神秀渐。偈语有树有台、要天天擦，是渐；无树无台、本无一物，是顿。","mix":"慧能偈通行本作“本来无一物”，敦煌本作“佛性常清净”。神秀生年另有605年说。","mcq":[{"q":"“身是菩提树，心如明镜台”的作者是","o":["神秀","弘忍","慧能","达摩"],"a":0,"w":"这是神秀所作偈，慧能和以“菩提本无树”。"},{"q":"“菩提本无树，明镜亦非台”体现的修行主张是","o":["持咒","持名念佛","顿悟","渐修"],"a":2,"w":"慧能偈强调本来清净，主顿悟。"}],"rel":[{"t":"慧能与《六祖坛经》","n":"南宗对手"},{"t":"顿悟","n":"南宗主张"},{"t":"禅宗","n":"所属宗派"},{"t":"武则天","n":"礼遇神秀的皇帝"}],"exam":[]},{"id":"a02-038","t":"少林寺","cid":"02e","p":2,"kind":"地理","alias":["嵩山少林寺","少林"],"one":"河南登封嵩山，北魏孝文帝时建，达摩面壁处，禅宗祖庭。","ans":"少林寺位于**河南登封嵩山少室山北麓**，**北魏孝文帝**时为安置天竺僧人跋陀而建。相传**达摩**到此面壁九年，创立禅宗，因此少林寺被尊为**禅宗祖庭**。慧可在此立雪断臂，向达摩求法，是禅宗史上的著名故事。隋唐以后，少林僧人以武艺闻名，形成**少林武术**，有“天下功夫出少林”的说法。少林寺塔林与嵩山“天地之中”历史建筑群一同列入世界文化遗产。","pts":["河南登封嵩山，北魏孝文帝时建","达摩面壁，禅宗祖庭","少林武术"],"mem":"一个画面：嵩山、少林、达摩面壁、慧可立雪。位置口诀：“少林在嵩山，武术出少林，禅宗从少林”，三处提示一次记完。","mix":"白马寺是佛教传入中国后第一座官办寺院，在洛阳；少林寺在登封，是禅宗祖庭。嵩山属中岳，不要与五台山、峨眉山这些佛教名山混淆。","mcq":[{"q":"被尊为禅宗祖庭、相传达摩面壁处的寺院是","o":["白马寺","少林寺","东林寺","灵隐寺"],"a":1,"w":"少林寺在河南嵩山，达摩在此面壁，故为禅宗祖庭。"}],"rel":[{"t":"达摩","n":"面壁于此"},{"t":"禅宗六祖","n":"初祖传法地"},{"t":"白马寺","n":"最早官办寺院，对举"},{"t":"慧远与东林寺","n":"另一著名佛寺"}],"exam":[]},{"id":"a02-039","t":"慧远与东林寺","cid":"02e","p":3,"kind":"人物","alias":["庐山慧远","东林白莲社"],"one":"东晋高僧慧远在庐山东林寺首结白莲社修念佛三昧，被尊为净土宗初祖。","ans":"慧远与东林寺代表了**中国净土宗发轫历史**。东晋高僧慧远在江西**庐山创建东林寺**，结“白莲社”共修念佛三昧，期生西方净土，后世**尊慧远为净土宗初祖**。他还著有《沙门不敬王者论》，坚持僧团独立于世俗王权，在佛教史上地位崇高。","pts":["东晋高僧慧远在庐山建东林寺，创白莲社","倡导念佛往生极乐净土，被尊为净土宗初祖","著《沙门不敬王者论》，力保佛法独立品格"],"mem":"记忆口诀：“**庐山东林结白莲，慧远初祖净土传**”；“虎溪三笑”典故亦与慧远东林寺相关。","mix":"净土宗初祖为东晋庐山慧远，而唐代善导大师是净土宗实际的教义集大成者与制度化开创者。","mcq":[{"q":"在庐山东林寺创建白莲社、倡导专修念佛求生西方极乐，被后世尊为净土宗初祖的东晋高僧是","o":["慧远","善导","道安","僧肇"],"a":0,"w":"东晋慧远在庐山东林寺结社念佛，被尊为净土宗初祖。"}],"rel":[{"t":"净土宗","n":"尊为该宗初祖"},{"t":"道安","n":"师承高僧道安"},{"t":"汉传佛教八宗","n":"净土宗法统源流"}],"exam":[]},{"id":"a02-040","t":"四大菩萨","cid":"02f","p":1,"kind":"合称","alias":["文殊普贤观音地藏"],"one":"文殊、普贤、观音、地藏，分别象征智、行、悲、愿。","ans":"四大菩萨是**汉传佛教最受崇奉的四位大乘菩萨：文殊、普贤、观音、地藏**，分别象征**智、行、悲（大慈大悲）、愿**。他们各有道场，即**“四大佛教名山”**：文殊在山西五台山，普贤在四川峨眉山，观音在浙江普陀山，地藏在安徽九华山。四位菩萨信仰在民间影响很大，观音以“救苦救难”最普及，地藏发愿“地狱不空，誓不成佛”。","pts":["文殊、普贤、观音、地藏","智、行、悲、愿","对应五台、峨眉、普陀、九华"],"members":[["文殊菩萨","智，五台山（山西），骑青狮"],["普贤菩萨","行，峨眉山（四川），骑白象"],["观音菩萨","悲，普陀山（浙江）"],["地藏菩萨","愿，九华山（安徽）"]],"mem":"口诀“**智行悲愿**”配“文普观地”。山名配对口诀：**五文、峨普、陀观、九地**（五台文殊，峨眉普贤，普陀观音，九华地藏）。","mix":"观音是菩萨，不是佛；普陀山（观音）与九华山（地藏）最常互换；四大菩萨与四大天王、佛陀十大弟子是不同的组合。","mcq":[{"q":"四大佛教名山中，供奉观音菩萨的是","o":["普陀山","峨眉山","九华山","五台山"],"a":0,"w":"观音道场在浙江普陀山。"},{"q":"象征“愿”，道场在九华山的菩萨是","o":["普贤菩萨","文殊菩萨","观音菩萨","地藏菩萨"],"a":3,"w":"地藏发愿“地狱不空，誓不成佛”，道场在安徽九华山。"}],"rel":[{"t":"四大佛教名山","n":"道场一一对应"},{"t":"菩萨与罗汉","n":"概念辨析"},{"t":"大乘佛教","n":"菩萨信仰的来源"},{"t":"道教四大名山","n":"常被对举"}],"exam":[]},{"id":"a02-041","t":"佛教节日：浴佛节、盂兰盆节、腊八","cid":"02f","p":3,"kind":"常识","alias":["佛教三大民俗节日","佛诞节与盂兰盆节"],"one":"融入中国传统民俗的重要佛教节日，分别纪念佛诞、目连救母与佛成道。","ans":"佛教节日浴佛节、盂兰盆节、腊八是**融入中国民俗的佛教岁时**。农历**四月初八浴佛节**灌沐佛像庆佛诞；**七月十五盂兰盆节**依目连救母设斋供僧、超度亡灵；**腊月初八腊八节**为佛成道日，施粥济众，体现了**佛教与孝道慈善的融合**。","pts":["四月初八浴佛节庆祝释迦牟尼诞辰","七月十五盂兰盆节源于目连救母并行超度孝道","腊月初八纪念释迦牟尼成道，施粥祈福"],"mem":"节气日期表：“**四八浴佛生，七月半盂兰度，腊八佛成道喝粥**”；融入了儒家孝道与慈善。","mix":"七月十五在道教为中元节（地官赦罪），在佛教为盂兰盆节（僧自恣日、解脱亡灵），民间二者习俗融为一体。","mcq":[{"q":"相传源于“目连救母”典故，于农历七月十五举行施食供僧、超度祖先的佛教节日是","o":["浴佛节","盂兰盆节","腊八节","涅槃节"],"a":1,"w":"盂兰盆节于农历七月十五举行，旨在藉供养僧众功德解救地狱苦难，倡导报恩孝亲。"}],"rel":[{"t":"腊八节与小年","n":"民间节日习俗交融"},{"t":"释迦牟尼","n":"诞辰与成道纪念"},{"t":"变文与俗讲","n":"目连救母文本载体"}],"exam":[]},{"id":"a02-042","t":"变文与俗讲","cid":"02f","p":3,"kind":"概念","alias":["敦煌变文","寺院俗讲"],"one":"唐代寺院面向世俗大众宣讲佛经故事及演义的通俗宣教与说唱文学形式。","ans":"变文与俗讲是唐代寺院**通俗说唱文学与弘法形式**。俗讲是僧侣面向世俗大众宣讲佛经或历史故事的活动，变文则是其**说唱底本**，多采用**韵散相间体制**。敦煌遗书发现大量变文如《目连救母变文》，是**中国通俗说唱与小说戏曲的源头之一**。","pts":["唐代寺院通俗化讲经弘法形式与底本","变文采用韵散相间、讲唱结合体制","敦煌出土代表作，为后世话本戏曲重要源头"],"mem":"区别巧记：“**俗讲是演说表演，变文是讲唱底本**”；韵文配合唱，散文负责说。","mix":"俗讲是口头宣讲演出形式，变文是具体的文学文本脚本；内容既包括佛经故事（如目连救母），也扩充至历史传说（如伍子胥变文）。","mcq":[{"q":"唐代寺院面向世俗信众讲经弘法时所使用的韵散相间、讲唱结合的说唱底本被称为","o":["传奇","诸宫调","变文","话本"],"a":2,"w":"变文是唐代寺院僧侣举行俗讲时使用的讲唱文学脚本，20世纪在敦煌藏经洞大量发现。"}],"rel":[{"t":"敦煌藏经洞","n":"变文写本主要出土地"},{"t":"佛教节日：浴佛节、盂兰盆节、腊八","n":"盂兰盆节目连故事流传"},{"t":"佛教汉译词","n":"佛教文化对汉语文学渗透"}],"exam":[]},{"id":"a02-043","t":"太上老君与道教三清","cid":"02g","p":2,"kind":"合称","alias":["三清","三清尊神","元始天尊","灵宝天尊","道德天尊","太上老君"],"one":"元始天尊、灵宝天尊、道德天尊，后者即太上老君，道教最高三位尊神。","ans":"三清是**道教供奉的最高三位尊神**，即**元始天尊、灵宝天尊（太上道君）、道德天尊**，分别居玉清、上清、太清三境。其中**道德天尊就是太上老君**，由**老子**神化而来。道教奉老子为教祖，唐代李氏王朝因同姓尊老子为祖先，追尊为“玄元皇帝”。道观主殿多称三清殿，供奉三清。三清体现了道教把哲学家神化、构建神仙谱系的特点。","pts":["元始天尊、灵宝天尊、道德天尊","道德天尊即太上老君，由老子神化","居玉清、上清、太清三境"],"members":[["元始天尊","居玉清境，三清之首"],["灵宝天尊","居上清境，又称太上道君"],["道德天尊","居太清境，即太上老君、老子"]],"mem":"口诀：元始、灵宝、道德，对应玉清、上清、太清，首字顺序“元灵道”。老君这条线：老子，神化为太上老君，也就是道德天尊，在三清里排第三。","mix":"三清是三位尊神，与“三清山”“三清殿”是同一概念的延伸，不要与玉皇大帝（俗称天帝）混淆。太上老君在《西游记》里炼丹，形象由此也很常见。","mcq":[{"q":"道教“三清”中，由老子神化而来的是","o":["元始天尊","灵宝天尊","玉皇大帝","道德天尊"],"a":3,"w":"道德天尊即太上老君，由老子神化。"}],"rel":[{"t":"老子","n":"太上老君的原型"},{"t":"《道德经》与《道藏》","n":"道教经典"},{"t":"道教","n":"所属宗教"},{"t":"《封神演义》","n":"三教神仙谱系的文学代表"}],"exam":[]},{"id":"a02-044","t":"五斗米道（天师道）与太平道","cid":"02g","p":2,"kind":"流派","alias":["五斗米道","天师道","太平道","张道陵","张角"],"one":"东汉两大早期道教教团：张道陵创五斗米道，张角创太平道。","ans":"五斗米道与太平道是**东汉后期形成的两大早期道教教团**。五斗米道由**张道陵**在东汉顺帝时于蜀地鹤鸣山创立，入道者须交五斗米，后称**天师道**，其孙张鲁曾在汉中建立政教合一的政权。太平道由**张角**创立，奉《太平经》，以符水治病传教，**184年发动黄巾起义**，提出“苍天已死，黄天当立”。两派是道教教团组织的开端，天师道后世发展为正一道。","pts":["张道陵创五斗米道，后称天师道","张角创太平道，184年黄巾起义","两派为早期道教教团，天师道演变为正一道"],"members":[["五斗米道","张道陵，蜀地，入道交五斗米，后称天师道"],["太平道","张角，《太平经》，184年黄巾起义"]],"mem":"一南一北，一蜀一冀：张道陵在四川（蜀），张角在河北一带。关键词配对：五斗米对应交米，太平道对应符水治病。184年是甲子年，黄巾口号“岁在甲子，天下大吉”。","mix":"张道陵创“教”，张角发动“起义”，前者后来成为道教正统（天师道），后者随黄巾失败而被镇压。别把《太平经》和《太平广记》混淆，后者是宋代小说总集。","mcq":[{"q":"东汉末年发动黄巾起义的太平道创始人是","o":["张道陵","张鲁","张衡","张角"],"a":3,"w":"张角创太平道，184年发动黄巾起义；张道陵创五斗米道。"}],"rel":[{"t":"张道陵、张角","n":"创始人并称"},{"t":"黄巾起义","n":"太平道发动"},{"t":"正一道","n":"天师道后世发展"},{"t":"道教","n":"早期教团"}],"exam":[]},{"id":"a02-045","t":"正一道","cid":"02g","p":2,"kind":"流派","alias":["正一教","龙虎山天师道","张天师"],"one":"元代形成，以龙虎山张天师为首，重符箓、道士可婚娶。","ans":"正一道是**元代天师道统领江南各符箓派后形成的道教派别**，与北方全真道并称两大派。该派以**江西龙虎山张天师为首**，奉张道陵为祖，以画符、念咒、驱邪、斋醮为主要活动，**重符箓而轻内丹**。正一道**道士可以婚娶**，可居家修行，与全真道出家清修不同。元代朝廷授予龙虎山天师统领江南道教的权力，**张天师世袭**，一直延续至明清。","pts":["元代整合江南符箓派，龙虎山张天师为首","重符箓斋醮，道士可婚娶","与全真道并称两大派"],"mem":"南北对举口诀：北全真，南正一；全真出家，正一婚娶。龙虎山、张天师、符箓三个词永远连在一起。正一可以联想“正”统天师道的“一”脉相承。","mix":"正一道的源头是东汉张道陵的天师道，全真道是金代新创，二者不是同一渊源。龙虎山属道教四大名山之一。","mcq":[{"q":"以龙虎山张天师为首、道士可以婚娶的道教派别是","o":["全真道","太平道","上清派","正一道"],"a":3,"w":"正一道以龙虎山张天师为首，重符箓，可居家婚娶。"}],"rel":[{"t":"全真道","n":"南北两大派对举"},{"t":"五斗米道（天师道）与太平道","n":"正一道的源头"},{"t":"道教四大名山","n":"龙虎山属其一"},{"t":"道教","n":"所属宗教"}],"exam":[]},{"id":"a02-046","t":"全真七子","cid":"02g","p":3,"kind":"合称","alias":["全真道七真","北七真"],"one":"金代全真道祖师王重阳在北方收录的七位核心著名弟子统称。","ans":"全真七子是**全真道创始人王重阳的七位弟子**：**马钰、谭处端、刘处玄、丘处机、王处一、郝大通、孙不二**。七人继承王重阳**三教合一**思想，分别开创龙门派、遇仙派等分支。其中丘处机远赴西域大雪山谒见成吉思汗，使全真道在金元时期达到全盛。","pts":["金代全真道祖师王重阳的七位著名弟子","马钰、谭处端、刘处玄、丘处机等七大门徒","丘处机西见成吉思汗，推动全真道极盛"],"members":[["马钰","号丹阳子，全真第二代掌教，开创全真遇仙派"],["谭处端","号长真子，开创全真南无派"],["刘处玄","号长生子，开创全真随山派"],["丘处机","号长春子，开创龙门派，西行谒见成吉思汗劝止杀戮"],["王处一","号玉阳子，开创全真嵛山派"],["郝大通","号广宁子，精通易学，开创全真华山派"],["孙不二","号清静散人，马钰之妻，全真教女丹派开创者"]],"mem":"顺口溜记七子：“**马谭刘丘王郝孙，丹阳长春最绝伦**”；丘处机开创的龙门派流传最广。","mix":"王重阳是全真教创教祖师，全真七子是王重阳的弟子，王重阳本人不在“七子”之中。","mcq":[{"q":"在“全真七子”中，开创全真龙门派、曾远赴西域大雪山谒见成吉思汗劝以“敬天爱民、清心寡欲”的是","o":["马钰","郝大通","丘处机","王处一"],"a":2,"w":"丘处机道号长春子，应成吉思汗之召西行大雪山觐见，推动全真道走向极盛。"}],"rel":[{"t":"全真道","n":"全真教弘传中坚力量"},{"t":"三教合一","n":"践行三教合一宗旨"},{"t":"正一道","n":"北方全真与南方正一对立"}],"exam":[]},{"id":"a02-047","t":"八仙","cid":"02g","p":3,"kind":"合称","alias":["八仙过海","民间八仙"],"one":"中国民间广为流传的八位道教神仙，代表男女老幼贫贱富贵的世俗百态。","ans":"八仙是中国民间著名的**道教仙人神话群体**，由**铁拐李、汉钟离、张果老、吕洞宾、何仙姑、蓝采和、韩湘子、曹国舅**组成。分别代表男女老幼富贵贫贱等世相，暗喻凡人皆可成仙。“**八仙过海，各显神通**”体现了鲜明的平民化色彩。","pts":["民间流传的八位道教平民神仙组合","铁拐李、吕洞宾、何仙姑等八位平民化仙人","代表男女老幼富贵贫贱不同阶层，体现成仙普遍性"],"members":[["铁拐李","李玄，拐杖与葫芦，借尸还魂，列八仙之首"],["汉钟离","钟离权，手摇芭蕉扇，号正阳祖师"],["张果老","倒骑毛驴，手持鱼鼓简板，传为唐代术士"],["吕洞宾","吕岩，纯阳子，背负宝剑，全真祖师与民间仙医"],["何仙姑","八仙中唯一女性，手持荷花，象征慈爱高洁"],["蓝采和","手挽花篮，着破烂蓝衫行歌，行为玩世不恭"],["韩湘子","韩愈侄孙，吹奏横笛紫箫，善吹箫化雪"],["曹国舅","宋代国舅曹景休，手持玉板，代表富贵阶层归道"]],"mem":"顺口溜：“**铁拐汉钟张果老，吕仙何姑蓝采和，韩湘曹舅各显能**”。","mix":"八仙中的吕洞宾同时被全真教尊为纯阳祖师（“北五祖”之一）；韩湘子在唐传奇中被附会为文豪韩愈的侄孙。","mcq":[{"q":"在民间传说“八仙过海”的八位仙人中，唯一的女性神仙是","o":["九天玄女","麻姑","妈祖","何仙姑"],"a":3,"w":"何仙姑是八仙中唯一的女性形象，手持荷花。"}],"rel":[{"t":"中国古代神话","n":"平民神仙神话体系"},{"t":"全真道","n":"吕洞宾被奉为北五祖之一"},{"t":"饮中八仙","n":"盛唐诗文酒中八客对照"}],"exam":[]},{"id":"a02-048","t":"寇谦之、陆修静、陶弘景","cid":"02g","p":3,"kind":"人物","alias":["南北朝道教改革家","寇陆陶"],"one":"南北朝时期推动道教清整改造、规范仪轨并确立神仙体系的三位道教宗师。","ans":"寇谦之、陆修静、陶弘景是**南北朝时期道教改革代表人物**。北魏寇谦之改革天师道创**“北天师道”**；刘宋陆修静编撰《三洞经书目录》确立**道教斋醮科仪**；南朝梁陶弘景隐居茅山号“山中宰相”，编《真灵位业图》**系统构建道教神仙谱系**。","pts":["北魏寇谦之整饬天师道，创立北天师道","南朝陆修静编经书目录并健全斋醮科仪","陶弘景隐居茅山，撰《真灵位业图》确立神仙体系"],"mem":"巧记三人功绩：“**北寇改天师，陆修定科仪，弘景茅山画神谱**”。","mix":"寇谦之在北魏推行新天师道并得太武帝支持；陆修静（南朝宋）总括三洞经卷；陶弘景（南朝梁）集茅山上清派大成。","mcq":[{"q":"南朝梁代隐居茅山、被称为“山中宰相”，撰写《真灵位业图》系统确立道教神仙谱系的道教学者是","o":["陶弘景","陆修静","寇谦之","葛洪"],"a":0,"w":"陶弘景隐居茅山，开创茅山派，所撰《真灵位业图》首次构建了严整的七级道教神仙等级体系。"}],"rel":[{"t":"道教","n":"南北朝道教官方化与理论化"},{"t":"葛洪《抱朴子》","n":"继承东晋道教炼丹神仙论"},{"t":"正一道","n":"天师道改制渊源"}],"exam":[]},{"id":"a02-049","t":"《道德经》与《道藏》","cid":"02g","p":3,"kind":"作品","alias":["老子五千言与道藏","道教根本经典"],"one":"老子所著道家五千言圣典与历代道教经书教规文献总集的合称。","ans":"《道德经》与《道藏》代表了**道教核心经典体系**。《道德经》五千言由老子所作，是**道教尊崇的根本圣典**与义理源泉；《道藏》则是**汇集历代道教经籍的总集**，按“三洞四辅十二类”编排，现存明代《正统道藏》，是研究中国宗教与科技的宝库。","pts":["《道德经》为老子所撰，道教尊为根本经典","《道藏》为历代道教文献丛书总集","以“三洞四辅”分类，现存明《正统道藏》最完整"],"mem":"对仗记：“**道德经为百经首，三洞四辅汇道藏**”；现存最完整的道藏版本是明朝《正统道藏》。","mix":"《道德经》本为先秦道家哲学著作，东汉后被道教尊为开山宗经；《道藏》是道教典籍丛书总集，涵盖宗教、养生、医药、化学等诸多领域。","mcq":[{"q":"历代道教经书文献总集《道藏》在传统分类上采用的编纂体系是","o":["经律论三藏","三洞四辅十二类","四库七录","五经正义"],"a":1,"w":"《道藏》依照“三洞”（洞真、洞玄、洞神）与“四辅”（太玄、太平、太清、正一）编排。"}],"rel":[{"t":"《道德经》","n":"道家道教根本经典"},{"t":"大藏经","n":"道佛两教经典总集对照"},{"t":"太上老君","n":"老子神化为教祖"}],"exam":[]},{"id":"a02-050","t":"炼丹术与火药","cid":"02g","p":3,"kind":"常识","alias":["道教外丹与火药","火药起源"],"one":"中国古代道士在炼制外丹长生药的实践中偶然发明火药的历史现象。","ans":"炼丹术与火药揭示了**中国古代宗教与科技的交融**。道教方士在炼制长生外丹时，加热硫黄、硝石、木炭等矿物引发爆燃，**偶然孕育了火药发明**。唐代已有伏火方记载，宋代广泛用于军事，是**中国古代四大发明之一**。","pts":["道士炼制外丹仙药过程中探索矿物化学反应","硫黄、硝石、木炭混合伏火实验导致火药发明","唐代首现记载，宋代军用，构成中国四大发明"],"mem":"口诀：“**外丹求长生，硝硫炭爆燃出火药**”；长生不死药没炼成，反倒催生了火药。","mix":"火药发明源于道教的“外丹术”（炼制矿物药石），而非后代强身吐纳的“内丹术”。","mcq":[{"q":"中国古代四大发明之一的火药，最初是由哪一群体在何种活动中偶然探索发现的","o":["农学家配制农药","冶铁工匠高温锻造","道教方士炼制外丹药","中医学者炮制草药"],"a":2,"w":"古代道家术士在尝试用硫黄、硝石、木炭炼制长生外丹时，偶然发现了混合物爆燃的火药配方。"}],"rel":[{"t":"火药","n":"科技发明成果本体"},{"t":"四大发明","n":"列为四大发明之一"},{"t":"葛洪《抱朴子》","n":"总结早期外丹炼金术"}],"exam":[]},{"id":"a02-051","t":"妈祖信俗","cid":"02g","p":3,"kind":"常识","alias":["天后信仰","妈祖文化","天妃信仰"],"one":"以崇奉海上和平女神妈祖（林默）为核心、庇佑航海平安的中国民间信仰。","ans":"妈祖信俗是**中国代表性的海洋民间信仰**。源于北宋福建湄洲岛神化女子林默，尊为天后圣母。该信仰以**护国庇民、保佑航海**为核心，随海上丝路播迁海外。2009年被列入**人类非物质文化遗产代表作名录**，是凝聚同胞与侨胞的精神纽带。","pts":["源于北宋福建湄洲岛林默，尊为天后圣母","以护航救难、仁爱济世为核心的海洋信俗","2009年列入联合国人类非物质文化遗产代表作"],"mem":"核心关键词：“**北宋林默湄洲岛，天后护航入非遗**”；2009年入选人类非遗。","mix":"妈祖本名林默，生于北宋福建莆田；妈祖信俗是首个信俗类世界级非遗，不属于佛教或正统道教，是典型的中国民间海洋信仰。","mcq":[{"q":"源于北宋福建莆田湄洲岛林默姑娘救助海难传说、2009年被联合国教科文组织列入“人类非物质文化遗产代表作名录”的民间信仰是","o":["临水夫人信俗","黄大仙信俗","保生大帝信俗","妈祖信俗"],"a":3,"w":"妈祖信俗于2009年成为中国首个信俗类世界级非物质文化遗产。"}],"rel":[{"t":"道教","n":"被道教吸纳封为天后"},{"t":"中国古代神话","n":"民间造神与护航神祇"},{"t":"丝绸之路：长安-天山廊道路网","n":"海上丝绸之路文化纽带"}],"exam":[]},{"id":"a02-052","t":"世界三大宗教","cid":"02i","p":1,"kind":"合称","alias":["三大宗教"],"one":"佛教、基督教、伊斯兰教，其中佛教创立最早。","ans":"世界三大宗教指**佛教、基督教、伊斯兰教**，是信徒遍布多个洲、不限于单一民族的普世性宗教。**佛教最早**，约前6至前5世纪由释迦牟尼创立于古印度；基督教在**1世纪**由耶稣创立于巴勒斯坦；伊斯兰教在**7世纪初**由穆罕默德创立于阿拉伯半岛。经典依次为三藏、《圣经》、《古兰经》。三者都传入中国：佛教在两汉之际，基督教在唐代以景教形式传入，伊斯兰教在唐代，与本土道教并存。","pts":["佛教、基督教、伊斯兰教","佛教最早，其次基督教、伊斯兰教","经典：三藏、《圣经》、《古兰经》"],"members":[["佛教","前6至前5世纪，古印度，释迦牟尼，三藏"],["基督教","1世纪，巴勒斯坦，耶稣，《圣经》"],["伊斯兰教","7世纪初，阿拉伯半岛，穆罕默德，《古兰经》"]],"mem":"时间越排越晚：**前6世纪、1世纪、7世纪**，口诀“佛基伊”。创立地对应“印、巴、阿”：印度、巴勒斯坦、阿拉伯半岛。","mix":"犹太教、印度教、道教不在三大之列；印度教信徒虽多，但属民族宗教。","mcq":[{"q":"世界三大宗教中创立最早的是","o":["伊斯兰教","基督教","犹太教","佛教"],"a":3,"w":"佛教约前6至前5世纪创立，基督教1世纪，伊斯兰教7世纪。"},{"q":"下列不属于世界三大宗教的是","o":["印度教","伊斯兰教","基督教","佛教"],"a":0,"w":"三大宗教是佛教、基督教、伊斯兰教。"}],"rel":[{"t":"佛教基本教义","n":"佛教要义"},{"t":"基督教","n":"成员之一"},{"t":"伊斯兰教","n":"成员之一"},{"t":"印度教","n":"常被误列"},{"t":"道教","n":"本土宗教对照"}],"exam":[]},{"id":"a02-053","t":"犹太教","cid":"02h","p":1,"kind":"流派","alias":["希伯来宗教","塔纳赫"],"one":"希伯来人的一神教，奉雅威，以摩西律法为核心，经典为《希伯来圣经》。","ans":"犹太教是**古代希伯来人（犹太人）的民族宗教，最早的一神教之一**，奉**雅威（耶和华）**为唯一真神。它以**摩西律法（十诫）为核心**，传统认为摩西带领希伯来人出埃及，在西奈山领受十诫。经典是**《希伯来圣经》**（犹太教称《塔纳赫》，与基督教《旧约》大体对应），前五卷称《摩西五经》。教义强调上帝与以色列人立约，圣地为**耶路撒冷**。犹太教是基督教的母体，也影响了伊斯兰教。","pts":["希伯来人的民族一神教，奉雅威","摩西律法与十诫，《希伯来圣经》","圣地耶路撒冷，基督教的母体"],"mem":"画面：摩西带族人出埃及，在西奈山领十诫。亲缘链：犹太教（母）→基督教（子，1世纪）→伊斯兰教（受影响，7世纪）。犹太教《塔纳赫》与基督教《旧约》大体对应，犹太教不认《新约》。","mix":"犹太教是宗教，犹太人是民族；“《旧约》”是基督教的叫法，犹太教称《希伯来圣经》。犹太教不承认耶稣是弥赛亚。","mcq":[{"q":"下列哪部基督教典籍与《希伯来圣经》大体对应","o":["《旧约》","《新约》","《古兰经》","《吠陀》"],"a":0,"w":"《希伯来圣经》与基督教《旧约》大体对应，卷目与编次因传统而异。"},{"q":"传统上认为带领希伯来人出埃及并领受十诫的人物是","o":["摩西","所罗门","大卫","耶稣"],"a":0,"w":"摩西出埃及，在西奈山领十诫，是摩西律法的来源。"}],"rel":[{"t":"犹太人","n":"民族与宗教的关系"},{"t":"摩西与“十诫”","n":"律法的核心"},{"t":"基督教","n":"由犹太教产生"},{"t":"耶路撒冷","n":"圣地"},{"t":"《圣经》","n":"《旧约》即《希伯来圣经》"}],"exam":[]},{"id":"a02-054","t":"基督教","cid":"02h","p":1,"kind":"流派","alias":["基督宗教"],"one":"1世纪耶稣创立，经典《圣经》，分天主教、东正教、新教三大派。","ans":"基督教是**1世纪由巴勒斯坦的耶稣创立的宗教**，信奉上帝，以耶稣为基督（救世主），**经典是《圣经》，含《旧约》和《新约》**。它从犹太教中产生，向罗马帝国传播，**4世纪末成为罗马国教**。**1054年东西教会大分裂**，分为西部的天主教和东部的东正教，**16世纪马丁·路德发动宗教改革，产生新教**。三大派别合称基督教，与佛教、伊斯兰教并称世界三大宗教。","pts":["1世纪耶稣创立，经典《圣经》","4世纪末成罗马国教","1054年分裂，16世纪产生新教"],"mem":"年份链“**1—4—1054—16**”：1世纪生，4世纪成国教，1054年分天主教与东正教，16世纪出新教。入华四波口诀：唐景教、元也里可温、明清天主教、近代新教。","mix":"天主教、东正教、新教都属基督教；汉语里“基督教”狭义常指新教。1054年是东西分裂，16世纪是宗教改革，别互换。","mcq":[{"q":"1054年基督教分裂为","o":["逊尼派与什叶派","新教与东正教","天主教与新教","天主教与东正教"],"a":3,"w":"新教产生于16世纪宗教改革。"},{"q":"基督教的经典《圣经》由哪两部分组成","o":["《古兰经》与《圣训》","《塔纳赫》与《塔木德》","《吠陀》与《奥义书》","《旧约》与《新约》"],"a":3,"w":"旧约源自犹太教，新约记耶稣及使徒言行。"}],"rel":[{"t":"犹太教","n":"母体"},{"t":"《圣经》","n":"经典"},{"t":"天主教、东正教与新教","n":"三大派别"},{"t":"基督教成为罗马国教","n":"4世纪末的转折"},{"t":"景教","n":"唐代入华的第一波"}],"exam":[]},{"id":"a02-055","t":"伊斯兰教","cid":"02h","p":1,"kind":"流派","alias":["清真教","回教"],"one":"7世纪初穆罕默德创立，奉安拉，经典《古兰经》，唐代传入中国。","ans":"伊斯兰教是**7世纪初穆罕默德在阿拉伯半岛创立的一神教**，信奉**安拉**，“伊斯兰”意为“顺从”，信徒称穆斯林。经典是**《古兰经》**，辅以《圣训》；基本功修为念、礼、斋、课、朝**五功**，圣地是麦加、麦地那。后分**逊尼派与什叶派**两大派别。伊斯兰教**唐代传入中国**，传统说法是651年大食使节朝见唐高宗，后在回族、维吾尔族等十个少数民族中流传。","pts":["7世纪初穆罕默德创立，奉安拉","《古兰经》，五功","分逊尼、什叶；唐代传入中国"],"mem":"三个地点：**麦加**（生、天启）、**麦地那**（622年迁徙，伊斯兰历元年）、**中国**（651年传入）。五功口诀“**念礼斋课朝**”。","mix":"651年是传入时间的传统说法，学界也有其他看法。伊斯兰教与阿拉伯不是同义，穆斯林遍布多国。","mcq":[{"q":"传统说法中，伊斯兰教传入中国的时间是","o":["67年","651年","635年","前2年"],"a":1,"w":"前2年是伊存授经（佛教），67年是永平求法（佛教），635年是景教入唐。"},{"q":"下列不属于伊斯兰教“五功”的是","o":["斋戒","朝觐","礼拜","受洗"],"a":3,"w":"五功为念、礼、斋、课、朝；受洗是基督教仪式。"}],"rel":[{"t":"《古兰经》","n":"经典"},{"t":"伊斯兰教五功","n":"基本功修"},{"t":"麦加与麦地那","n":"两大圣地"},{"t":"逊尼派与什叶派","n":"两大教派"},{"t":"世界三大宗教","n":"所属合称"}],"exam":[]},{"id":"a02-056","t":"《圣经》","cid":"02h","p":2,"kind":"作品","alias":["圣经","《新旧约全书》","旧约","新约","《旧约》","《新约》"],"one":"基督教经典，分《旧约》《新约》，是西方文学与文化的源头之一。","ans":"《圣经》是**基督教的经典**，分**《旧约》和《新约》**两部分。《旧约》本是**犹太教经典《希伯来圣经》**，新教口径共39卷，《新约》共27卷，记述耶稣生平和早期教会。《圣经》的重要译本有**哲罗姆的拉丁文通行本**、**路德的德文本**和**1611年英王钦定本**，翻译活动推动了各国语言的规范。《圣经》提供了大量典故与母题，是**西方文学、艺术与伦理的重要源头**。","pts":["分《旧约》《新约》，新教39+27卷","拉丁通行本、路德德译本、1611钦定本","西方文学与文化源头"],"mem":"数字：旧39，新27，合66卷（新教口径）。三大译本串联：拉丁文通行本（哲罗姆），德文本（路德），英文钦定本（1611）。“旧约”是犹太教留下的，“新约”是耶稣之后写的。","mix":"天主教《旧约》为46卷，与新教的39卷不同。《旧约》本用希伯来文，《新约》用希腊文；《七十子希腊文本》是《旧约》的早期希腊文译本。","mcq":[{"q":"按新教通行口径，《旧约》和《新约》的卷数分别是","o":["27卷、39卷","46卷、27卷","39卷、27卷","39卷、36卷"],"a":2,"w":"新教《旧约》39卷、《新约》27卷；天主教《旧约》为46卷。"}],"rel":[{"t":"《七十子希腊文本》","n":"《旧约》希腊文译本"},{"t":"《钦定本圣经》","n":"1611年英译本"},{"t":"马丁·路德与德语《圣经》","n":"德语译本"},{"t":"基督教","n":"所属宗教"},{"t":"犹太教","n":"《旧约》的来源"}],"more":"哲罗姆译拉丁文通行本（Vulgate）。\n路德译德文本，1522年新约，1534年全本。\n英王钦定本，1611年。","exam":[]},{"id":"a02-057","t":"《古兰经》","cid":"02h","p":2,"kind":"作品","alias":["古兰经","《可兰经》"],"one":"伊斯兰教经典，阿拉伯文，共114章，被视为安拉启示。","ans":"《古兰经》是**伊斯兰教的根本经典**，用**阿拉伯文**写成，共**114章**，穆斯林认为是真主**安拉**通过天使启示给**先知穆罕默德**的话。启示约持续二十余年，穆罕默德去世后由弟子整理，**第三任哈里发奥斯曼时期**编定标准本。《古兰经》是伊斯兰教义、教法的首要依据，圣训居于其次。全书开篇是《开端章》，内容涉及信仰、礼仪、道德和法律，对**阿拉伯语和伊斯兰世界的文化**影响深远。","pts":["伊斯兰教根本经典，阿拉伯文","共114章，安拉启示给穆罕默德","奥斯曼时期编定，教义教法首要依据"],"mem":"数字：114章。画面：穆罕默德在山洞里听到天使传话，弟子记下，奥斯曼定本。“古兰”是阿拉伯语“诵读”的意思，经文以诵读为本。","mix":"《古兰经》和《圣经》的区别：《古兰经》被认为是安拉的直接语言，因此阿拉伯文原本最具权威，译本多称“译解”；《圣经》是多位作者、多语言写成。","mcq":[{"q":"《古兰经》共有","o":["30章","66章","114章","150章"],"a":2,"w":"《古兰经》共114章，用阿拉伯文写成。"}],"rel":[{"t":"伊斯兰教","n":"所属宗教"},{"t":"伊斯兰教五功","n":"教义实践"},{"t":"逊尼派与什叶派","n":"教派分裂的背景"},{"t":"《圣经》","n":"另一部一神教经典，对举"}],"exam":[]},{"id":"a02-058","t":"摩西与“十诫”","cid":"02h","p":2,"kind":"人物","alias":["摩西","十诫","摩西十诫","摩西五经"],"one":"希伯来先知，率族人出埃及，在西奈山领受十诫。","ans":"摩西是**古代希伯来人的先知和领袖**，传说他率领被奴役的希伯来人**出埃及**，渡过红海，在**西奈山**领受上帝所赐的**十诫**。十诫规定只敬拜唯一的上帝、不可杀人、不可偷盗、不可作假见证、孝敬父母等，是犹太教律法的核心。传统认为《圣经》开头的《创世记》《出埃及记》《利未记》《民数记》《申命记》五卷为摩西所作，称**《摩西五经》**。十诫奠定了**犹太教、基督教的道德基础**，也影响了西方法律观念。","pts":["希伯来先知，率族人出埃及","西奈山领受十诫","《摩西五经》，犹太教、基督教道德基础"],"mem":"记三个“出”：出埃及，西奈山上受诫，五经里的《出埃及记》。画面：摩西手捧两块石板，板上刻着十条诫命。“摩西五经”五卷首字：创、出、利、民、申。","mix":"摩西属犹太教，是《旧约》人物，与耶稣相隔上千年，不要互换。“十诫”专指西奈山所受的十条诫命，与后世教会的“七宗罪”无关。","mcq":[{"q":"传说中率领希伯来人出埃及并在西奈山领受“十诫”的人是","o":["亚伯拉罕","大卫","耶稣","摩西"],"a":3,"w":"摩西率族人出埃及，在西奈山受十诫。"}],"rel":[{"t":"希伯来","n":"摩西所属民族"},{"t":"犹太教","n":"律法源头"},{"t":"《圣经》","n":"《摩西五经》属《旧约》"},{"t":"《十二铜表法》","n":"同为早期成文法，对照"}],"exam":[]},{"id":"a02-059","t":"耶稣","cid":"02h","p":2,"kind":"人物","alias":["耶稣基督","基督","拿撒勒的耶稣"],"one":"基督教创始人，被尊为基督（救世主），公元纪年以其诞生年份为起点。","ans":"耶稣是**基督教的创始人**，约生于**巴勒斯坦的伯利恒**，在拿撒勒长大，约三十岁开始传道，选**十二门徒**，宣讲上帝的国与博爱。他被犹大出卖，由罗马总督钉在**十字架**上，基督徒相信他三日后复活。“**基督**”是希腊语“受膏者”，即希伯来语“弥赛亚”，意为救世主。**公元纪年**以耶稣诞生年份为起点，他的言行记载于**《新约》**四福音书，是基督教信仰的中心。","pts":["基督教创始人，称基督（救世主）","十二门徒，被钉十字架，三日复活","公元纪年起点，言行见《新约》福音书"],"mem":"画面：伯利恒马槽降生，十二门徒，十字架受难，三日复活。“基督”两个字等于“弥赛亚”，意思是救世主。纪年线索：公元前（BC）、公元后（AD）以他为界。","mix":"耶稣被基督徒尊为救主，教会组织的扩展由使徒保罗等人推动。实际生年学界认为在公元前6至前4年之间，与公元元年并不重合。","mcq":[{"q":"“基督”一词的含义是","o":["受膏者，救世主","先知","大祭司","圣灵"],"a":0,"w":"“基督”是希腊语“受膏者”，对应希伯来语“弥赛亚”。"}],"rel":[{"t":"基督教","n":"创始人"},{"t":"《圣经》","n":"《新约》记其生平"},{"t":"摩西与“十诫”","n":"犹太教先知，对照"},{"t":"耶路撒冷","n":"受难之地"}],"exam":[]},{"id":"a02-060","t":"天主教、东正教与新教","cid":"02h","p":2,"kind":"合称","alias":["基督教三大派","天主教","东正教","新教","基督新教"],"one":"基督教的三大派别：1054年分出天主教与东正教，16世纪宗教改革产生新教。","ans":"天主教、东正教与新教是**基督教的三大派别**。**1054年东西教会大分裂**，以罗马教皇为首的西派称**罗马天主教**，以君士坦丁堡牧首为首的东派称**希腊东正教**。**1517年马丁·路德**发表《九十五条论纲》，掀起宗教改革，脱离罗马教廷的各派统称**新教**，主要有路德宗、加尔文宗和安立甘宗。在中国，“基督教”通常专指新教。三大派在教权、圣像和礼仪上各有不同，共同构成现代基督教的格局。","pts":["1054年东西教会分裂，天主教与东正教","1517年路德宗教改革，产生新教","新教三大宗派：路德宗、加尔文宗、安立甘宗"],"members":[["天主教","以罗马教皇为首，使用拉丁礼仪"],["东正教","以君士坦丁堡牧首为精神领袖，俄、希等国自治教会"],["新教","16世纪宗教改革后产生，在中国常称“基督教”"]],"mem":"时间线两个数字：1054（东西分裂）、1517（宗教改革）。先“东西”分，后“新旧”分：1054分出东正教，1517分出新教。三个名字对应三个关键词：教皇（天主教）、牧首（东正教）、路德（新教）。","mix":"“基督教”广义指三大派，中国习惯用狭义指新教；“天主教”在中国不属于“基督教”的俗称范围。东正教的首都是君士坦丁堡，后以俄罗斯为最大教会。","mcq":[{"q":"1054年基督教东西教会大分裂后形成的两派是","o":["天主教与新教","新教与东正教","天主教与东正教","路德宗与加尔文宗"],"a":2,"w":"1054年分裂为罗马天主教与希腊东正教；新教产生于16世纪宗教改革。"}],"rel":[{"t":"新教三大宗派","n":"新教的主要分支"},{"t":"宗教改革","n":"新教产生原因"},{"t":"马丁·路德与《九十五条论纲》","n":"改革起点"},{"t":"基督教","n":"所属宗教"},{"t":"拜占庭建筑与圣索菲亚大教堂","n":"东正教的中心"}],"exam":[]},{"id":"a02-061","t":"逊尼派与什叶派","cid":"02h","p":2,"kind":"流派","alias":["逊尼派","什叶派","逊尼","什叶"],"one":"伊斯兰教两大派，因穆罕默德继承人问题分裂，逊尼派占多数，什叶派以伊朗为中心。","ans":"逊尼派与什叶派是**伊斯兰教的两大教派**。**632年穆罕默德去世后，因继承人问题发生分歧**：**逊尼派主张由选举产生哈里发**，承认前四任哈里发的正统，**信徒占穆斯林绝大多数**；**什叶派认为应由穆罕默德的堂弟兼女婿阿里及其后裔继承**，称教长为伊玛目，**以伊朗为中心**，在伊拉克、巴林等地也占多数。两派在教义、礼仪上基本一致，分歧集中于权力继承与宗教权威，中国穆斯林多属逊尼派。","pts":["因穆罕默德继承人问题分裂","逊尼派主选举，占多数；什叶派拥阿里，伊朗为中心","教义基本一致，分歧在继承与权威"],"members":[["逊尼派","主张选举哈里发，约占穆斯林多数"],["什叶派","拥护阿里及其后裔为伊玛目，以伊朗为中心"]],"mem":"两派一句话区分：逊尼选举、占多数；什叶拥阿里、以伊朗为中心。“什叶”本义是“追随者”，指阿里的追随者。国家线索：沙特多为逊尼派，伊朗是什叶派大本营。","mix":"两派分裂的原因是政治继承，而非对《古兰经》的看法不同。逊尼派承认前四任哈里发，什叶派只承认阿里。","mcq":[{"q":"下列关于伊斯兰教两大派的说法，正确的是","o":["逊尼派主张阿里及其后裔继承","什叶派占穆斯林绝大多数","什叶派以伊朗为中心","两派对《古兰经》的真伪有根本分歧"],"a":2,"w":"什叶派以伊朗为中心；逊尼派占多数，主张选举哈里发；两派同尊《古兰经》。"}],"rel":[{"t":"伊斯兰教","n":"所属宗教"},{"t":"《古兰经》","n":"两派共尊经典"},{"t":"伊斯兰教五功","n":"两派共有的宗教义务"},{"t":"天主教、东正教与新教","n":"基督教教派分裂，对照"}],"exam":[]},{"id":"a02-062","t":"伊斯兰教五功","cid":"02h","p":3,"kind":"合称","alias":["五功","穆斯林五项天命"],"one":"伊斯兰教要求穆斯林必须履行的五项根本宗教功课：念、礼、斋、课、朝。","ans":"伊斯兰教五功是**穆斯林必须履行的五项基本功课**。包括**念功（证信）、礼功（每日五拜）、斋功（斋月封斋）、课功（出纳天课）、朝功（朝觐麦加）**。五功将内心信仰、道德责任与身体力行融为一体，构成了**伊斯兰教信仰实践的核心支柱**。","pts":["包含念、礼、斋、课、朝五大根本宗教天命","穆斯林信仰落实在言语、身行与财物上的基本天命","维系全球穆斯林宗教生活与社会认同的基石"],"members":[["念功","证信，念诵“万物非主，唯有真主；穆罕默德是真主的使者”之清真言"],["礼功","礼拜，遵照规定仪礼每日面向麦加举行晨、晌、晡、昏、宵五次拜功"],["斋功","斋戒，伊斯兰历九月（莱麦丹月）整月白昼不饮不食、戒绝私欲"],["课功","天课，每年按资产的一定比例交纳天课善款，济贫助困"],["朝功","朝觐，身体健康且经济条件允许的穆斯林一生至少朝拜麦加圣寺一次"]],"mem":"顺口溜记忆：“**念礼斋课朝，五功不可少**”；念为口舌，礼斋为身体，课为财产，朝为毕生。","mix":"“课功”（天课）属于法定的强制性宗教课税与再分配慈善，而非随意自发的散钱布施（非强制施舍称为“萨达卡”）。","mcq":[{"q":"在伊斯兰教“五功”中，规定经济条件完备的信徒一生至少前往麦加圣寺巡礼一次的是","o":["念功","礼功","朝功","课功"],"a":2,"w":"朝功规定凡身体健康、旅费充裕的成年穆斯林，一生中至少应到麦加朝觐一次。"}],"rel":[{"t":"伊斯兰教","n":"教义信仰的实践化"},{"t":"麦加与麦地那","n":"朝功朝觐的目的地"},{"t":"开斋节与古尔邦节","n":"斋月结束与朝觐庆典"}],"exam":[]},{"id":"a02-063","t":"开斋节与古尔邦节","cid":"02h","p":3,"kind":"常识","alias":["肉孜节与宰牲节","伊斯兰两大节日"],"one":"伊斯兰教最隆重的两大传统节日：标志斋月结束的开斋节与巡礼朝觐的古尔邦节。","ans":"开斋节与古尔邦节是**伊斯兰教最隆重的两大传统节日**。**开斋节（肉孜节）**于伊斯兰历十月初举行，庆祝为期一月的莱麦丹斋戒圆满结束；**古尔邦节（宰牲节）**于十二月十日举行，纪念易卜拉欣献子忠信，有宰牲济贫之俗，**体现感恩与团聚精神**。","pts":["伊斯兰教两大重要节日，又称肉孜节与宰牲节","开斋节在十月初庆祝斋月圆满封斋结束","古尔邦节在十二月十日宰杀牲畜济贫感恩"],"mem":"区分口诀：“**十月初开斋，腊月十宰牲**”；古尔邦节即宰牲节，与麦加朝觐同期。","mix":"开斋节在伊斯兰历十月一日，庆祝斋月（九月）结束；古尔邦节在十二月十日（朝觐期最后一天），纪念先知奉献故事宰牲分肉。","mcq":[{"q":"在伊斯兰历十月初举行，庆祝为期一个月的封斋戒期圆满结束的穆斯林传统节日是","o":["古尔邦节","圣纪节","阿舒拉节","开斋节"],"a":3,"w":"开斋节又称肉孜节，是穆斯林在伊斯兰历九月斋月结束后的重大庆祝节日。"}],"rel":[{"t":"伊斯兰教五功","n":"与斋功朝功密切对应"},{"t":"伊斯兰教","n":"伊斯兰节俗生活核心"},{"t":"佛教节日：浴佛节、盂兰盆节、腊八","n":"世界宗教节庆对照"}],"exam":[]},{"id":"a02-064","t":"耶路撒冷","cid":"02h","p":2,"kind":"地理","alias":["圣城","耶路撒冷旧城","阿克萨清真寺","哭墙"],"one":"犹太教圣殿所在地，耶稣受难地，伊斯兰教第三圣地，三教共同圣城。","ans":"耶路撒冷位于**巴勒斯坦地区**，是**犹太教、基督教、伊斯兰教三大宗教共同的圣城**。对犹太教，这里是**圣殿所在地**，残存的西墙（哭墙）是最神圣的祈祷地点；对基督教，这里是**耶稣受难和复活之地**，建有圣墓教堂；对伊斯兰教，这里的**阿克萨清真寺**是仅次于麦加、麦地那的第三圣地，相传穆罕默德由此夜行登霄。中世纪的**十字军东征**也以夺取耶路撒冷为目标。其归属至今存在争议，古城1981年列入世界遗产。","pts":["犹太教圣殿、哭墙","基督教耶稣受难地，圣墓教堂","伊斯兰教第三圣地，阿克萨清真寺"],"mem":"三教三个地标：犹太教的哭墙，基督教的圣墓教堂，伊斯兰教的阿克萨清真寺。伊斯兰三大圣地顺序：麦加、麦地那、耶路撒冷。","mix":"麦加是伊斯兰教第一圣地，也是朝觐目的地，耶路撒冷排第三。十字军东征的目标是“从穆斯林手中夺回圣城”，指的就是耶路撒冷。","mcq":[{"q":"被犹太教、基督教、伊斯兰教共同尊为圣城的是","o":["麦加","君士坦丁堡","罗马","耶路撒冷"],"a":3,"w":"耶路撒冷是三教共同圣城；麦加只属伊斯兰教。"}],"rel":[{"t":"十字军东征","n":"争夺圣城的战争"},{"t":"犹太教","n":"圣殿所在地"},{"t":"基督教","n":"耶稣受难地"},{"t":"伊斯兰教","n":"第三圣地"}],"exam":[]},{"id":"a02-065","t":"唐代三夷教","cid":"02h","p":2,"kind":"合称","alias":["三夷教","祆教","摩尼教"],"one":"唐代传入的景教、祆教、摩尼教三种外来宗教。","ans":"唐代三夷教指**唐代传入并流行的三种外来宗教**，即**景教、祆教、摩尼教**。景教是基督教聂斯托利派，635年传入长安，781年立有**《大秦景教流行中国碑》**；祆教是波斯琐罗亚斯德教，又称拜火教，南北朝时已传入，唐代设萨宝官管理；摩尼教由波斯人摩尼创立，唐代武则天时传入，回鹘人也信奉。**会昌五年（845年）唐武宗灭佛**时，三夷教都受到打击，逐渐衰落。三夷教反映了**唐代对外开放和宗教宽容**的格局。","pts":["景教、祆教、摩尼教","景教有781年大秦景教流行中国碑","845年会昌灭佛时受打击"],"members":[["景教","基督教聂斯托利派，635年入长安"],["祆教","波斯琐罗亚斯德教，又称拜火教"],["摩尼教","波斯人摩尼创立，唐代回鹘人信奉"]],"mem":"口诀：景、祆、摩，“景”想到大秦景教碑，“祆”想到拜火，“摩”想到摩尼。三个宗教都来自波斯一带，是丝路带来的。","mix":"伊斯兰教、佛教也在唐代流行，但“三夷教”专指景教、祆教、摩尼教。景教不是天主教，是基督教的聂斯托利派。","mcq":[{"q":"下列不属于唐代“三夷教”的是","o":["景教","摩尼教","祆教","佛教"],"a":3,"w":"三夷教是景教、祆教、摩尼教；佛教是东汉传入的另一系统。"}],"rel":[{"t":"景教","n":"三夷教之一"},{"t":"三武一宗灭佛","n":"会昌灭佛同时打击三夷教"},{"t":"基督教","n":"景教所属宗教"},{"t":"伊斯兰教","n":"唐代也传入的另一宗教"}],"exam":[]},{"id":"a02-066","t":"明清来华耶稣会士","cid":"02h","p":2,"kind":"人物","alias":["耶稣会士","利玛窦","龙华民","汤若望","南怀仁"],"one":"明末清初来华的天主教耶稣会传教士，以利玛窦、汤若望、南怀仁为代表。","ans":"明清来华耶稣会士是**明末清初来华的天主教耶稣会传教士**。**利玛窦**1582年到澳门，后入北京，与**徐光启**合译《几何原本》前六卷，绘《坤舆万国全图》；**龙华民**接任利玛窦主持在华传教；**汤若望**修订历法，入清后掌**钦天监**；**南怀仁**也曾任钦天监。他们以科学知识辅助传教，**促进了西学东渐**。徐光启是中国天主教徒而非传教士，李约瑟是英国科学史家，二者**不属于**耶稣会士。","pts":["利玛窦、龙华民、汤若望、南怀仁","天文历法与科学知识辅助传教","徐光启、李约瑟不是传教士"],"members":[["利玛窦","1582年到澳门，合译《几何原本》"],["龙华民","接任利玛窦，主张禁用“上帝”译名"],["汤若望","德国人，修订历法，掌钦天监"],["南怀仁","比利时人，清初钦天监，造天文仪器"]],"mem":"口诀：利龙汤南（利玛窦、龙华民、汤若望、南怀仁），按来华先后排列。排除法：徐光启是中国教徒（利玛窦的合作者），李约瑟是英国科学史家，二者都在名单之外。","mix":"2011年选择题的干扰项含利玛窦、龙华民、徐光启、李约瑟，要选“不是天主教传教士”的人，需判断出徐光启（中国教徒）与李约瑟（英国科学史家）不属于该类。","mcq":[{"q":"下列人物中不是来华耶稣会传教士的是","o":["利玛窦","汤若望","南怀仁","李约瑟"],"a":3,"w":"李约瑟是英国科学史家，不是传教士。"}],"rel":[{"t":"利玛窦","n":"代表人物"},{"t":"徐光启","n":"中国天主教徒，与利玛窦合译"},{"t":"上帝","n":"传教士借用的译名"},{"t":"景教","n":"唐代基督教入华，对举"}],"exam":[]},{"id":"a02-067","t":"也里可温","cid":"02h","p":3,"kind":"概念","alias":["也里可温教","也里可温人"],"one":"元代对基督教（主要为景教与罗马天主教）及其传教士信众的蒙古语统称。","ans":"也里可温是**元代对基督教及信徒的蒙古语统称**。词源意为“有福缘之人”。该称呼涵盖唐代传入的**景教（聂斯托利派）**与元代传入的**罗马天主教**。元廷设立崇福司统一管理其教务，是**中西宗教文化交流高潮的见证**。","pts":["元代对基督教各派信徒及僧侣的官方通称","涵括聂斯托利派（景教）与新入天主教方济各会","朝廷设“崇福司”管理，印证大一统下的宗教包容"],"mem":"时代链条：“**唐称景教，元称也里可温，明清天主教，近代出新教**”。","mix":"唐代传入的基督教东方聂斯托利派称为“景教”，元代则无论景教还是天主教，朝廷均通称为“也里可温”。","mcq":[{"q":"元代官方对基督教（包括景教与天主教）及其传教士、信徒所使用的蒙古语统称是","o":["也里可温","大秦景教","白莲教","摩尼教"],"a":0,"w":"元代将基督教总称为“也里可温”，意为“奉教之人”或“有福之人”，设崇福司管理。"}],"rel":[{"t":"基督教","n":"基督教入华历史第二阶段"},{"t":"基督教成为罗马国教","n":"基督教普世传播源头"},{"t":"天主教、东正教与新教","n":"入华派系源自西方教会"}],"exam":[]},{"id":"a02-068","t":"教宗利奥十四世","cid":"02h","p":3,"kind":"时事","alias":["利奥十四世","良十四世","罗伯特·普雷沃斯特"],"one":"天主教会第267任教宗，2025年5月当选，天主教史上首位美洲/美国籍教宗。","ans":"教宗利奥十四世（1955年生），原名罗伯特·普雷沃斯特，**天主教会第267任教宗**。在方济各逝世后，于**2025年5月8日当选**。他是历史上**首位美国籍教宗**，出身圣奥斯定会，曾任教廷主教部部长，标志着当代梵蒂冈牧灵格局的新走向。","pts":["2025年5月当选接替方济各，第267任教宗","原名罗伯特·普雷沃斯特，历史上首位美国籍教宗","曾任梵蒂冈圣座主教部部长，圣奥斯定会士出身"],"mem":"关键词挂钩：“**二五年五月方济各后，美国普雷沃斯特称利奥十四**”。","mix":"利奥十四世教廷中文亦译“良十四世”；他是首位美洲（美国芝加哥）出生的教宗，前任方济各为阿根廷籍。","mcq":[{"q":"2025年5月接替已故教宗方济各当选为天主教第267任教宗、成为历史上首位美国籍教宗的是","o":["本笃十六世","利奥十四世","保禄六世","约翰·保罗二世"],"a":1,"w":"罗伯特·普雷沃斯特于2025年5月8日当选天主教教宗，取名号为利奥十四世（良十四世）。"}],"rel":[{"t":"天主教、东正教与新教","n":"当代天主教会最高领袖"},{"t":"基督教","n":"全球最大宗教当代领袖"},{"t":"世界三大宗教","n":"世界主要宗教时事动态"}],"exam":[]},{"id":"a02-069","t":"印度教","cid":"02i","p":2,"kind":"流派","alias":["新婆罗门教","印度教徒"],"one":"由婆罗门教演变而来，主神梵天、毗湿奴、湿婆，与种姓制度相联。","ans":"印度教是**由古代婆罗门教演变而来的印度主要宗教**，约在公元前后吸收佛教、耆那教和民间信仰而形成。印度教信奉**三大主神：梵天（创造）、毗湿奴（保护）、湿婆（毁灭）**，信仰轮回与业报，与**种姓制度**紧密联系。经典有《吠陀》《薄伽梵歌》和两大史诗《摩诃婆罗多》《罗摩衍那》。印度教是**今天印度信徒最多的宗教**，对印度社会、文学与艺术影响深远。","pts":["由婆罗门教演变而来","梵天创造、毗湿奴保护、湿婆毁灭","轮回业报，与种姓制度相联"],"mem":"三大主神的职能口诀：造（梵天）、保（毗湿奴）、毁（湿婆）。可联想“造房子、保护房子、拆房子”。种姓四级：婆罗门、刹帝利、吠舍、首陀罗。","mix":"印度教（多神，信吠陀）与佛教（反对种姓，主张缘起）是印度两大系统，佛教起源于婆罗门教盛行时期，对种姓制度提出批评。","mcq":[{"q":"印度教三大主神中，负责“毁灭”的是","o":["梵天","毗湿奴","湿婆","因陀罗"],"a":2,"w":"梵天创造，毗湿奴保护，湿婆毁灭。"}],"rel":[{"t":"婆罗门教","n":"前身"},{"t":"印度教三大主神","n":"主神"},{"t":"种姓制度","n":"相关社会制度"},{"t":"佛教基本教义","n":"同源印度，对照"}],"exam":[]},{"id":"a02-070","t":"婆罗门教","cid":"02i","p":3,"kind":"流派","alias":["早期婆罗门教","吠陀教"],"one":"古印度古代多神教与等级森严的传统宗教，现代印度教的前身。","ans":"婆罗门教是**古印度早期传统宗教与现代印度教前身**。以**《吠陀》为根本圣典**，奉梵天为宇宙创造神，推行**“吠陀天启、祭祀万能、婆罗门至上”**三大纲领，极力维护严格的四种姓制度。公元前6世纪遭到佛教、耆那教等沙门思潮的强烈批判与反抗。","pts":["以《吠陀》为圣典的古印度多神教，印度教前身","奉行吠陀天启、祭祀万能、婆罗门至上三大纲领","与严酷的种姓制度相结合，遭到佛教等沙门思潮冲击"],"mem":"三大纲领口诀：“**天启吠陀、万能祭祀、至上婆罗门**”；四种姓制度之宗教根源。","mix":"婆罗门教主张吠陀天启、神造四种姓；佛教与耆那教则属于反叛其神权与阶级垄断的“沙门思潮”。","mcq":[{"q":"下列哪一项不属于古印度传统婆罗门教宣扬的“三大纲领”","o":["吠陀天启","祭祀万能","因缘缘起","婆罗门至上"],"a":2,"w":"“因缘缘起”为释迦牟尼佛教的核心教义，婆罗门教三大纲领是“吠陀天启、祭祀万能、婆罗门至上”。"}],"rel":[{"t":"吠陀","n":"婆罗门教根本圣典"},{"t":"印度教三大主神","n":"婆罗门教演变为印度教"},{"t":"耆那教","n":"同期的古印度宗教思潮"}],"exam":[]},{"id":"a02-071","t":"耆那教","cid":"02i","p":3,"kind":"流派","alias":["耆那教派"],"one":"与早期佛教同时在古印度兴起的沙门反婆罗门宗教，强调极严格的非暴力苦行。","ans":"耆那教是公元前6世纪在古印度兴起的**沙门思潮非婆罗门教流派**。创始人为第二十四代祖师**筏驮摩那（尊称大雄）**。该教否定吠陀天启与梵天创世，将**“非暴力（不杀生）”**奉为最高戒律，主张通过极端的**肉体苦行与自制**消除业障以求灵魂解脱。","pts":["公元前6世纪古印度沙门思潮重要派别，大雄创立","反对婆罗门教神创论与种姓特权","恪守绝对“不杀生（非暴力）”与极端苦行解脱"],"mem":"记忆法：“**大雄创耆那，极端苦行不杀生**”；与佛教同代，佛教主中道，耆那主苦行。","mix":"佛教主张远离苦乐两边的“中道”，反对无益的自虐苦行；耆那教则将“极度苦行”视为消除往世恶业、净化灵魂的必修手段。","mcq":[{"q":"公元前6世纪与释迦牟尼同时代、尊筏驮摩那为“大雄”，严格奉行“不杀生”与极端苦行的印度宗教是","o":["印度教","锡克教","婆罗门教","耆那教"],"a":3,"w":"耆那教由尊称为“大雄”的筏驮摩那创立，以绝对不杀生和严苛苦行著称。"}],"rel":[{"t":"婆罗门教","n":"共同反抗婆罗门神权"},{"t":"释迦牟尼","n":"同时代古印度思想家"},{"t":"中道","n":"佛教中道对立于耆那苦行"}],"exam":[]},{"id":"a02-072","t":"神道教","cid":"02i","p":3,"kind":"流派","alias":["神道","日本神道"],"one":"日本源远流长的本土民族宗教，崇拜自然精灵神祇与皇祖天照大神。","ans":"神道教是**日本本土的传统民族宗教**。起源于古代原始拜物教，以**“万物有灵”与“八百万神”崇拜**为特征。奉皇祖神**天照大神为最高主神**，敬奉神社与鸟居，注重驱邪祓禊。明治维新后一度被改造为服务天皇集权体制的国家神道，影响深远。","pts":["日本本土民族宗教，崇拜“八百万神”与自然灵","奉天照大神为最高皇祖神，以神社鸟居为象征","近代与皇权结合形成国家神道，塑造民族精神"],"mem":"记忆法：“**鸟居神道拜天照，八百万神在日本**”；神社门前设“鸟居”划分神圣与凡俗。","mix":"神道教没有明确的教义教规与单一先知创教者；历史中曾长期与汉传佛教形成“神佛习合”，明治时代才推行“神佛分离”。","mcq":[{"q":"以崇拜自然万物与祖先神祇为核心、尊天照大神为最高神祇的日本本土传统宗教是","o":["神道教","耆那教","东正教","景教"],"a":0,"w":"神道教是日本本土宗教，信奉八百万神，以太阳神天照大神为皇祖最高神。"}],"rel":[{"t":"世界三大宗教","n":"民族宗教与世界宗教对照"},{"t":"鉴真东渡","n":"佛教入日与神佛习合"},{"t":"中国古代神话","n":"东方神话信仰形态比较"}],"exam":[]},{"id":"d02-001","t":"礼仪之争","cid":"02h","p":3,"kind":"事件","alias":["中国礼仪之争"],"one":"明末清初天主教围绕中国教徒能否祭祖祭孔的争论，导致康熙禁教。","ans":"礼仪之争是17至18世纪**天主教关于中国教徒能否祭祖、祭孔的争论**。明末**利玛窦**允许尊孔祭祖（**“利玛窦规矩”**），遭多明我会反对。1704、1715年教宗**克莱孟十一世**颁禁令，**康熙帝**于1720至1721年禁教，阻断清初中西交流。","pts":["明末清初关于中国教徒能否祭祖祭孔的争论","教廷颁禁令否定“利玛窦规矩”，引发康熙禁教"],"mem":"因果链记三步：利玛窦入乡随俗准祭祖→罗马教皇（克莱孟十一世）翻脸下禁令→康熙怒斥干涉内政下令禁教。","mix":"莫与1793年马戛尔尼使团的“叩头礼仪之争”混淆：本条是17–18世纪天主教祭祖祭孔之争，后者是中英外交礼节冲突；康熙晚年下令禁教，雍正初年进一步全面推行。","mcq":[{"q":"明末清初“礼仪之争”的核心分歧在于中国天主教徒能否","o":["用汉语翻译《圣经》","在钦天监担任官员","举行传统祭祖与祭孔仪式","参加清廷科举考试"],"a":2,"w":"礼仪之争围绕中国教徒是否允许保留传统祭祖、祭孔礼仪展开，最终导致康熙禁教。"}],"rel":[{"t":"利玛窦","n":"“利玛窦规矩”为争论焦点"},{"t":"明清来华耶稣会士","n":"耶稣会多主调和中国礼俗"},{"t":"康熙帝","n":"维护利玛窦规矩并最终禁教"},{"t":"马戛尔尼使团","n":"易混：后者为外交叩头礼之争"}],"exam":[]},{"id":"d02-002","t":"汤若望与南怀仁","cid":"02h","p":3,"kind":"人物","alias":["汤若望","南怀仁"],"one":"明末清初相继掌管钦天监的两位来华耶稣会士，推动西方历法与天文东传。","ans":"汤若望与南怀仁是**明末清初相继掌管钦天监的耶稣会士**。德国人**汤若望**（1591–1666）助修**《崇祯历书》**，顺治朝改颁**《时宪历》**，后陷历狱；比利时人**南怀仁**（1623–1688）平反历狱继掌钦天监，铸天文仪、绘**《坤舆全图》**。","pts":["明末清初掌管钦天监的两位耶稣会士","汤若望修《时宪历》，南怀仁绘《坤舆全图》"],"mem":"顺口区分两代监正：**明末顺治汤若望，历书时宪陷历狱；康熙平反南怀仁，观象铸仪坤舆图**。","mix":"《坤舆万国全图》是明代利玛窦所绘，《坤舆全图》是清代南怀仁所绘，书名差两字勿混；二人均为天主教耶稣会士，而非近代新教传教士。","mcq":[{"q":"下列明末清初人物与成就对应错误的一项是","o":["利玛窦：《几何原本》前六卷合译","汤若望：改定清初《时宪历》","南怀仁：绘制《坤舆全图》","徐光启：《天工开物》"],"a":3,"w":"《天工开物》作者是明代宋应星，徐光启著《农政全书》并与汤若望等合修《崇祯历书》。"}],"rel":[{"t":"明清来华耶稣会士","n":"清初耶稣会士核心代表"},{"t":"徐光启","n":"与汤若望合修《崇祯历书》"},{"t":"利玛窦","n":"晚明西学东渐先驱"},{"t":"康熙帝","n":"起用南怀仁并习西学"}],"exam":[]}],"tables":[{"name":"佛经翻译与求法人物","note":"","rows":[["人物","时代","身份与译业","易混点"],["鸠摩罗什","后秦（龟兹人，401年到长安）","四大翻译家之一，“旧译”代表；译《法华经》《金刚经》《维摩诘经》《阿弥陀经》及《中论》等三论","弟子“什门四圣”：僧肇、道生、道融、僧叡"],["真谛","南朝梁、陈（西天竺人，546年来华）","四大翻译家之一，译《摄大乘论》《俱舍论》","与佛教“真谛、俗谛”二谛同名"],["玄奘","唐","四大翻译家之一，西行印度求法，“新译”代表，创法相宗（唯识宗），口述《大唐西域记》","即“唐僧”“唐三藏”"],["不空","唐","四大翻译家之一，密宗“开元三大士”之一，译密教经典","另一种口径以义净代不空"],["道安","东晋","统一僧人以“释”为姓，提出译经“五失本、三不易”，编经录","不属四大翻译家"],["法显","东晋","陆路西行、海路返回，著《佛国记》（《法显传》）","求法者，非四大译家"],["义净","唐","海路往返印度，著《南海寄归内法传》","走海路，玄奘走陆路"],["鉴真","唐","律宗高僧，六次东渡，753年抵日本，建唐招提寺，传律宗","不是翻译家（2026选择干扰项答案）"]]},{"name":"汉传佛教主要宗派","note":"","rows":[["宗派","创立者或代表","依据经典或特点"],["天台宗","隋智顗（智者大师）","《法华经》，止观并重，中国最早的本土宗派"],["三论宗","隋吉藏","《中论》《百论》《十二门论》"],["法相宗（唯识宗）","唐玄奘、窥基","《成唯识论》，“万法唯识”"],["华严宗","唐法藏（贤首）","《华严经》，法界缘起"],["律宗","唐道宣","研习戒律，鉴真传至日本"],["净土宗","东晋慧远（初祖）、唐善导","念“阿弥陀佛”，求往生西方极乐世界"],["禅宗","达摩（初祖）、慧能（六祖）","不立文字、直指人心、见性成佛，《六祖坛经》"],["密宗","唐“开元三大士”善无畏、金刚智、不空","持咒、仪轨"]]},{"name":"世界主要宗教","note":"","rows":[["宗教","创立时间与创始人","经典","要点"],["犹太教","古代希伯来人，摩西律法","《希伯来圣经》（即基督教《旧约》）","最早的一神教之一，信奉雅威（耶和华），圣地耶路撒冷"],["基督教","1世纪巴勒斯坦，耶稣","《圣经》（《旧约》《新约》）","1054年东西分裂为天主教、东正教；16世纪马丁·路德宗教改革产生新教"],["伊斯兰教","7世纪初阿拉伯半岛，穆罕默德","《古兰经》","信奉安拉，圣地麦加，分逊尼派、什叶派；唐代传入中国"],["佛教","前6至前5世纪古印度，释迦牟尼","三藏","世界三大宗教中最早，两汉之际传入中国"]]}]});